bool operator!=(const vccbGlobalGnbId_type &first, const vccbGlobalGnbId_type &second)
{
    return first.gnbId.id != second.gnbId.id || first.gnbId.idLength != second.gnbId.idLength ||
           first.plmn.longId != second.plmn.longId;
}

