void printSingleMoBlacklistCellsEntry(const blackCellsElementDb_type *pToDisplay)
{
    if (pToDisplay == NULL || !pToDisplay->usage)
    {
        return;
    }
    PRINT("(%3d,", pToDisplay->pciRange.pciStart);
    if (pToDisplay->pciRange.pciType == pciType_single)
    {
        PRINT("---");
    }
    else
    {
        PRINT("%3d", pToDisplay->pciRange.pciRange);
    }
    PRINT(") ");
}

