void printBlacklistCellsSpidRefs(const measurementObjectBlacklistCells_type *pToPrint)
{
    if (pToPrint == NULL)
    {
        return;
    }

    PRINT("Matrix of references to ENDC blacklisted cells sets per SPID/PLMN:\n");

    const unsigned int maxPlmnIdx = ITSCP_ARRAY_SIZE(pToPrint->refs.plmnSupportEntries);
    PRINT("| PLMN|");
    unsigned int plmnIdx = 0;
    for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
    {
        PRINT(" %2d |", plmnIdx);
    }
    PRINT("\n");
    PRINT("|SPID |\n");

    unsigned int spidIdx = 0;
    const unsigned int maxSpidIdx = ITSCP_ARRAY_SIZE(pToPrint->refs.plmnSupportEntries[0].spidRefs.spidEndcIdx);
    for (; spidIdx < maxSpidIdx; spidIdx++)
    {
        uint16_t spidRefIdxs[maxPlmnIdx];
        unsigned int spidRefIdxsCount = 0;
        for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
        {
            spidRefIdxs[plmnIdx] = UNKNOWN_IDX_IN_ENDC_BLACKLIST_CELLS_SETS;
            if (CI_use != pToPrint->refs.plmnSupportEntries[plmnIdx].usage)
            {
                continue;
            }
            const uint16_t refIdx = pToPrint->refs.plmnSupportEntries[plmnIdx].spidRefs.spidEndcIdx[spidIdx];
            if (UNKNOWN_IDX_IN_ENDC_BLACKLIST_CELLS_SETS != refIdx)
            {
                spidRefIdxs[plmnIdx] = refIdx;
                spidRefIdxsCount++;
            }
        }
        if (0 == spidRefIdxsCount)
        {
            continue;
        }
        PRINT("|%3d  |", spidIdx + 1);
        for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
        {
            const uint16_t refIdx = spidRefIdxs[plmnIdx];
            if (UNKNOWN_IDX_IN_ENDC_BLACKLIST_CELLS_SETS != refIdx)
            {
                PRINT(" %2d |", refIdx);
            }
            else
            {
                PRINT("  - |");
            }
        }
        PRINT("\n");
    }

    PRINT("|DEFAU|");
    for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
    {
        const uint16_t refIdx = pToPrint->refs.plmnSupportEntries[plmnIdx].spidRefs.spidDefaultEndcIdx;
        if (CI_use != pToPrint->refs.plmnSupportEntries[plmnIdx].usage ||
            UNKNOWN_IDX_IN_ENDC_BLACKLIST_CELLS_SETS == refIdx)
        {
            PRINT("  - |");
            continue;
        }
        PRINT(" %2d |", refIdx);
    }

    PRINT("\n\n");
}

void printBlacklistCellsRfspRefs(const measurementObjectBlacklistCells_type *pToPrint)
{
    if (pToPrint == NULL)
    {
        return;
    }

    PRINT("Matrix of references to SA blacklisted cells sets per RFSP/PLMN:\n");

    const unsigned int maxPlmnIdx = ITSCP_ARRAY_SIZE(pToPrint->refs.plmnSupportEntries);
    PRINT("| PLMN|");
    unsigned int plmnIdx = 0;
    for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
    {
        PRINT(" %2d |", plmnIdx);
    }
    PRINT("\n");
    PRINT("|RFSP |\n");

    unsigned int rfspIdx = 0;
    const unsigned int maxRfspIdx = ITSCP_ARRAY_SIZE(pToPrint->refs.plmnSupportEntries[0].rfspRefs.rfspSaIdx);
    for (; rfspIdx < maxRfspIdx; rfspIdx++)
    {
        uint16_t rfspRefIdxs[maxPlmnIdx];
        unsigned int rfspRefIdxsCount = 0;
        for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
        {
            rfspRefIdxs[plmnIdx] = UNKNOWN_IDX_IN_SA_BLACKLIST_CELLS_SETS;
            if (CI_use != pToPrint->refs.plmnSupportEntries[plmnIdx].usage)
            {
                continue;
            }
            const uint16_t refIdx = pToPrint->refs.plmnSupportEntries[plmnIdx].rfspRefs.rfspSaIdx[rfspIdx];
            if (UNKNOWN_IDX_IN_SA_BLACKLIST_CELLS_SETS != refIdx)
            {
                rfspRefIdxs[plmnIdx] = refIdx;
                rfspRefIdxsCount++;
            }
        }
        if (0 == rfspRefIdxsCount)
        {
            continue;
        }
        PRINT("|%3d  |", rfspIdx + 1);
        for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
        {
            const uint16_t refIdx = rfspRefIdxs[plmnIdx];
            if (UNKNOWN_IDX_IN_SA_BLACKLIST_CELLS_SETS != refIdx)
            {
                PRINT(" %2d |", refIdx);
            }
            else
            {
                PRINT("  - |");
            }
        }
        PRINT("\n");
    }

    PRINT("Default references to SA blacklisted cells sets per PLMN:\n");
    PRINT("|DEFAU|");
    for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
    {
        const uint16_t refIdx = pToPrint->refs.plmnSupportEntries[plmnIdx].rfspRefs.rfspDefaultSaIdx;
        if (CI_use != pToPrint->refs.plmnSupportEntries[plmnIdx].usage ||
            UNKNOWN_IDX_IN_SA_BLACKLIST_CELLS_SETS == refIdx)
        {
            PRINT("  - |");
            continue;
        }
        PRINT(" %2d |", refIdx);
    }
    PRINT("\n");

    PRINT("Follow option per PLMN [follow service group configuration (SG), follow RFSP configuration (RF)]:\n");
    PRINT("|FOLLO|");
    for (plmnIdx = 0; plmnIdx < maxPlmnIdx; plmnIdx++)
    {
        if (CI_use != pToPrint->refs.plmnSupportEntries[plmnIdx].usage)
        {
            PRINT("  - |");
            continue;
        }
        if (moBlacklistCellsSaPreferredOption_followServiceGroup ==
            pToPrint->refs.plmnSupportEntries[plmnIdx].saPreferredOption)
        {
            PRINT(" SG |");
        }
        else
        {
            PRINT(" RF |");
        }
    }

    PRINT("\n\n");
}

