/*
 * @brief      This function prints content of a given measurementObjectBlacklistCells_type object.
 * @param      argc - number of arguments. Exactly two are necessary - precisely one cellNum.
 * @param      argv - array for arguments. The second must be a cellNum.
 * @return     GOOD
 */
int GetMeasurementObjectBlacklistCells(int32_t argc, char *argv[])
{
    if (argc < 2 || argv[1] == NULL)
    {
        PRINT("Please provide cellNum\n");
        return GOOD;
    }
    if (argc > 2)
    {
        PRINT("Please provide EXACTLY ONE cellNum\n");
        return GOOD;
    }
    uint16_t maxCellNum = MAX_CELL_NUM_ITSCP_VCCB;
    uint16_t cellNum = StrUtil::itscp_strtoul<uint16_t>(argv[1]);
    if (cellNum >= maxCellNum)
    {
        PRINT("cellNum is out of range. \n");
        PRINT("cellNum = %d but MAX_CELL_NUM_ITSCP_VCCB = %d \n", cellNum, maxCellNum);
        return GOOD;
    }

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    const measurementObjectBlacklistCells_type *pToPrint = &pCell->measurementsData.measObjectBlacklistCells;
    printBlacklistCellsRefs(pToPrint);
    printBlacklistCellsSets(pToPrint);

    return GOOD;
}

/*
 * @brief      This function is used to convert the gnbId and cellId(14bit) to NR cell identity (36bit).
 * @param      pGnbId, cellId(14bit)
 * @return     NR Cell Identity (36 bit)
 */
uint64_t GnbIdCellId2NrCellId(const gnbId_type *pGnbId, uint16_t cellId)
{
    uint64_t nrCellId = cellId;
    if (NULL != pGnbId)
    {
        nrCellId |= ((uint64_t)pGnbId->id << (MAX_NR_CELLIDENTITY_BIT - pGnbId->idLength));
    }
    return nrCellId;
}

CellNum_type GetCellNumFromNrCellId(uint64_t nrCellId)
{

    VccbCellInfo_type *pCells = PCELLINFO;
    VccbGnbInfo_type *pGnbs = PGNBINFO;

    for (size_t index = 0; index < MAX_CELL_NUM_ITSCP_VCCB; index++)
    {
        VccbCellInfo_type *pCell = &pCells[index];
        if (EQUIP != pCell->status)
        {
            continue;
        }

        VccbGnbInfo_type *pGnb = &pGnbs[pCell->gnbNum];
        uint64_t tmpNci = GnbIdCellId2NrCellId(&pGnb->globalGnbId.gnbId, pCell->cellIdentity);
        if (tmpNci == nrCellId)
        {
            return (CellNum_type)index;
        }
    }
    return MAX_CELL_NUM_ITSCP_VCCB;
}

void updateDiff(uint32_t updatedValue, uint32_t *pValue, uint32_t *pDiff)
{
    uint32_t prev = *pValue;
    *pValue = updatedValue;
    if (prev <= *pValue)
    {
        *pDiff += (*pValue - prev);
    }
    else
    {
        *pDiff += (0xFFFFFFFF - prev + *pValue);
    }
    return;
}

int itscpSleep(unsigned long sleepTime)
{
    struct timespec sleep;
    struct timespec remain;

    if (sleepTime >= 1000L)
    {
        sleep.tv_sec = (long int)(sleepTime / 1000L);
        sleep.tv_nsec = (long int)((sleepTime % 1000L) * 1000000L);
    }
    else if (sleepTime > 0L)
    {
        sleep.tv_sec = 0L;
        sleep.tv_nsec = (long int)(sleepTime * 1000000L);
    }
    else
    {
        PRINT("Invalid sleepTime(%lu)\n", sleepTime);
        return ERROR;
    }

    while (1)
    {
        memset(&remain, 0, sizeof(remain));

        if (nanosleep(&sleep, &remain) == 0) break;

        if (errno != EINTR) PRINT("TIMEOUT\n");

        memcpy(&sleep, &remain, sizeof(sleep));
    }
    return 0;
}

void calculateCrrCount(uint32_t *normal, uint32_t *abnormal, monitoringBhca_type *p)
{
    uint32_t crrIndex;
    for (crrIndex = 0; crrIndex < MIN(PLOGFISHING->crrEventCount, MAX_CRR_COUNT); crrIndex++)
    {
        int isNormal = isNormalCrr(PLOGFISHING->eventList[crrIndex].eventId);
        if (isNormal == 1)
        {
            *normal += p->crrEventCountDiff[crrIndex];
        }
        else if (isNormal == 0)
        {
            *abnormal += p->crrEventCountDiff[crrIndex];
        }
    }
}

/**
 * @brief     Calculate Bhca periodically
 */
void calculateBhca(monitoringBhca_type *p)
{
    uint16_t i = 0;
    if (p == NULL)
    {
        PRINT("p(=NULL) in calculateBhca\n");
        return;
    }

    p->monitoringBhca_totAttemptDiff = 0;
    p->monitoringBhca_totCompleteDiff = 0;
    p->tDiffAttCmplt = 0;
    p->tDiffE1BearerSetup = 0;
    p->tDiffF1UEContextSetup = 0;
    p->tDiffE1BearerMod = 0;
    p->tDiffCallDuration = 0;
    p->monitoringBhca_totReleaseAttemptDiff = 0;
    p->monitoringBhca_totReleaseCompleteDiff = 0;
    p->monitoringBhca_totSyncedSizeDiff = 0;

    // SA
    p->monitoringBhca_totAttemptSaDiff = 0;
    p->monitoringBhca_totCompleteSaDiff = 0;
    p->monitoringBhca_totReleaseAttemptSaDiff = 0;
    p->monitoringBhca_totReleaseCompleteSaDiff = 0;

    uint32_t crrIndex;
    for (crrIndex = 0; crrIndex < MAX_CRR_COUNT; crrIndex++)
    {
        p->crrEventCountDiff[crrIndex] = 0;
    }

    for (i = 0; i < MAX_CALL_THREAD_NUM_ITSCP_VCCB; i++)
    {
        updateDiff(PDBG->monitoringBhca.nrofAttempt[i], &p->monitoringBhca_nrofAttempt[i],
                   &p->monitoringBhca_totAttemptDiff);
        updateDiff(PDBG->monitoringBhca.nrofComplete[i], &p->monitoringBhca_nrofComplete[i],
                   &p->monitoringBhca_totCompleteDiff);
        updateDiff(PDBG->monitoringBhca.nrofAttemptSa[i], &p->monitoringBhca_nrofAttemptSa[i],
                   &p->monitoringBhca_totAttemptSaDiff);
        updateDiff(PDBG->monitoringBhca.nrofCompleteSa[i], &p->monitoringBhca_nrofCompleteSa[i],
                   &p->monitoringBhca_totCompleteSaDiff);

        updateDiff(PDBG->monitoringBhca.nrofReleaseAttemptSa[i], &p->monitoringBhca_nrofReleaseAttemptSa[i],
                   &p->monitoringBhca_totReleaseAttemptSaDiff);
        updateDiff(PDBG->monitoringBhca.nrofReleaseCompleteSa[i], &p->monitoringBhca_nrofReleaseCompleteSa[i],
                   &p->monitoringBhca_totReleaseCompleteSaDiff);
        updateDiff(PDBG->monitoringBhca.nrofReleaseAttempt[i], &p->monitoringBhca_nrofReleaseAttempt[i],
                   &p->monitoringBhca_totReleaseAttemptDiff);
        updateDiff(PDBG->monitoringBhca.nrofReleaseComplete[i], &p->monitoringBhca_nrofReleaseComplete[i],
                   &p->monitoringBhca_totReleaseCompleteDiff);
        for (crrIndex = 0; crrIndex < MIN(PLOGFISHING->crrEventCount, MAX_CRR_COUNT); crrIndex++)
        {
            updateDiff(PLOGFISHING->eventList[crrIndex].occurrenceCount[i], &(p->crrEventCount[i][crrIndex]),
                       &(p->crrEventCountDiff[crrIndex]));
        }
        updateDiff((uint32_t)PSTAT->localStat.hasCallStat1[i].syncedSize, &p->monitoringBhca_sycnedSize[i],
                   &p->monitoringBhca_totSyncedSizeDiff);

        UPDATE_TO_MAX(p->tDiffAttCmplt, PDBG->monitoringBhca.tDiffAttCmplt[i]);
        UPDATE_TO_MAX(p->tDiffE1BearerSetup, PDBG->monitoringBhca.tDiffE1BearerSetup[i]);
        UPDATE_TO_MAX(p->tDiffF1UEContextSetup, PDBG->monitoringBhca.tDiffF1UEContextSetup[i]);
        UPDATE_TO_MAX(p->tDiffE1BearerMod, PDBG->monitoringBhca.tDiffE1BearerMod[i]);
        UPDATE_TO_MAX(p->tDiffCallDuration, PDBG->monitoringBhca.tDiffCallDuration[i]);
        PDBG->monitoringBhca.tDiffAttCmplt[i] = 0;
        PDBG->monitoringBhca.tDiffE1BearerSetup[i] = 0;
        PDBG->monitoringBhca.tDiffF1UEContextSetup[i] = 0;
        PDBG->monitoringBhca.tDiffE1BearerMod[i] = 0;
        PDBG->monitoringBhca.tDiffCallDuration[i] = 0;
    }

    return;
}

void calculateDuration(monitoringDurationData_type *data, monitoringDurationResult_type *result)
{
    uint16_t threadNum;
    uint32_t prevCount, count, countDiff;
    uint32_t prevTotalDuration, totalDuration, totalDurationDiff;
    for (threadNum = 0; threadNum < MAX_CALL_THREAD_NUM_ITSCP_VCCB; threadNum++)
    {
        // RRC Setup Duration
        prevCount = data->rRCSetupDurationCount[threadNum];
        prevTotalDuration = data->rRCSetupDurationTotal[threadNum];

        count = PSTAT->localStat.rRCSetupDuration->eventCount;
        totalDuration = (uint32_t)PSTAT->localStat.rRCSetupDuration->totalDuration;

        countDiff = count - prevCount;
        if (prevCount > count) countDiff += 0xFFFFFFFF;
        totalDurationDiff = totalDuration - prevTotalDuration;
        if (prevTotalDuration > totalDuration) totalDurationDiff += 0xFFFFFFFF;

        if (countDiff > 0)
        {
            result->averageRRCSetupDuration[threadNum] = totalDurationDiff / countDiff;
        }
        else
        {
            result->averageRRCSetupDuration[threadNum] = 0;
        }

        data->rRCSetupDurationCount[threadNum] = count;
        data->rRCSetupDurationTotal[threadNum] = totalDuration;

        // RRC Holding Duration
        prevCount = data->rRCHoldingDurationCount[threadNum];
        prevTotalDuration = data->rRCHoldingDurationTotal[threadNum];

        count = PSTAT->localStat.rRCHoldingDuration->eventCount;
        totalDuration = (uint32_t)PSTAT->localStat.rRCHoldingDuration->totalDuration;

        countDiff = count - prevCount;
        if (prevCount > count) countDiff += 0xFFFFFFFF;
        totalDurationDiff = totalDuration - prevTotalDuration;
        if (prevTotalDuration > totalDuration) totalDurationDiff += 0xFFFFFFFF;

        if (countDiff > 0)
        {
            result->averageRRCHoldingDuration[threadNum] = totalDurationDiff / countDiff;
        }
        else
        {
            result->averageRRCHoldingDuration[threadNum] = 0;
        }

        data->rRCHoldingDurationCount[threadNum] = count;
        data->rRCHoldingDurationTotal[threadNum] = totalDuration;
    }

    return;
}

void getTimeStringWithTimezone(time_t time, char* timeStr, size_t timeStrLen)
{
    struct tm localTime;
    struct tm* result = localtime_r(&time, &localTime);
    char tmpStr[48] = {0, };

    if (result != NULL)
    {
        // Example: Thu Jan 25 09:58:59 2024 UTC+0100
        if (strftime(tmpStr, sizeof(tmpStr), "%c UTC%z\n", &localTime) == 0)
        {
            PRINT("strftime failed\n");
        }
        strncpy(timeStr, tmpStr, timeStrLen);
    }
    else
    {
        strncpy(timeStr, "Error: Invalid time", timeStrLen);
    }
}

/**
 *  @brief checkAddrOfPool
 *  @param N/A
 *  @return N/A
 */
int checkAddrOfPool(uint32_t type, void *base, void *ptr)
{
    uint16_t size = 0;
    uint16_t maxNum = 0;
    void *base1 = NULL;
    enumUsage_type usage = CI_no_use;

    if (ptr == NULL)
    {
        return FALSE;
    }

    switch (type)
    {
        case SRB_NODE:
            base1 = ((callInfo_type *)(base))->srbInfo;
            size = sizeof(callSRBInfo_type);
            maxNum = MAX_SRB_PER_CALL;
            break;

        case ERAB_NODE:
            base1 = ((callInfo_type *)(base))->erabInfo;
            size = sizeof(callERABInfo_type);
            maxNum = MAX_ERAB_PER_CALL;
            break;

        case GNB_NODE:
            base1 = ((callInfo_type *)(base))->gnbInfo;
            size = sizeof(callGNBInfo_type);
            maxNum = MAX_GNB_PER_CALL;
            break;

        case PDU_NODE:
            base1 = ((callInfo_type *)(base))->pduSess;
            size = sizeof(callPDUSessInfo_type);
            maxNum = MAX_PDU_SESS_PER_CALL;
            break;

        case DRB_NODE:
            base1 = ((callInfo_type *)(base))->drb;
            size = sizeof(callDRBInfo_type);
            maxNum = MAX_DRB_PER_SA_CALL;
            break;

        case QOSFLOW_NODE:
            base1 = ((callInfo_type *)(base))->qosFlow;
            size = sizeof(qosFlowInfo_type);
            maxNum = MAX_QOS_FLOW_PER_CALL;
            break;

        case COND_CELL_NODE:
            base1 = ((callInfo_type *)(base))->condHoInfo.cellList;
            size = sizeof(conditionalCellInfo_type);
            maxNum = MAX_NUM_COND_CELLS;
            break;

        default:
            PRINT("Unknown Type(%u)\n", type);
            return FALSE;
    }

    if ((long)ptr >= (long)base1 && (long)ptr < ((long)base1 + (long)size * maxNum))
    {
        if (((long)ptr - (long)base1) % size == 0)
        {
            if (type == SRB_NODE)
            {
                usage = static_cast<enumUsage_type>(((callSRBInfo_type *)ptr)->usage);
            }
            else if (type == ERAB_NODE)
            {
                usage = static_cast<enumUsage_type>(((callERABInfo_type *)ptr)->usage);
            }
            else if (type == GNB_NODE)
            {
                usage = ((callGNBInfo_type *)ptr)->usage;
            }
            else if (type == PDU_NODE)
            {
                usage = static_cast<enumUsage_type>(((callPDUSessInfo_type *)ptr)->usage);
            }
            else if (type == DRB_NODE)
            {
                usage = static_cast<enumUsage_type>(((callDRBInfo_type *)ptr)->usage);
            }
            else if (type == QOSFLOW_NODE)
            {
                usage = static_cast<enumUsage_type>(((qosFlowInfo_type *)ptr)->usage);
            }
            else if (type == COND_CELL_NODE)
            {
                usage = static_cast<enumUsage_type>(((conditionalCellInfo_type *)ptr)->usage);
            }

            if (usage == CI_use)
            {
                return TRUE;
            }
        }
        else
        {
            PRINT("Modula is not Zero... \n");
            PRINT("type(%u), base1(%p), ptr(%p), size(%d), num(%d), usage(%d)\n", type, base1, ptr, size, maxNum,
                  usage);
        }
    }
    else
    {
        PRINT("Out of Valid Range... \n");
        PRINT("type(%u), base1(%p), ptr(%p), size(%d), num(%d), usage(%d)\n", type, base1, ptr, size, maxNum, usage);
    }

    return FALSE;
}

/**
 *  @brief Convert String to Hex. This Function is used to ASN decoding.
 *  @param N/A
 *  @return N/A
 */
int convertStr2Hex(char *input, void *ptr, int bufLen)
{
    int i = 0;
    uint8_t *bp = (uint8_t *)ptr;
    int len = 0;

    if (input == NULL) return 0;
    if (ptr == NULL) return 0;
    if (bufLen <= 0) return 0;

    len = (int)(strlen(input) >> 1);

    for (i = 0; (i < len) || (i < bufLen); i++)
    {
        bp[i] = (uint8_t)((getHexaDecimalFromChar(input[i << 1]) << 4) | getHexaDecimalFromChar(input[(i << 1) + 1]));
    }

    return len;
}

/*
 * @brief           Decompress forbiddenTA, copy from ComLibUtility VLIB_Decompress5gForbiddenTA
 *
 * @param[out]      pTgt :          output structure
 * @param[in]       pSrc :          input structure
 * @return          status :        GOOD, ERROR / int16_t
 */
int16_t decompress5gForbiddenTA(forbiddenTA_type *pTgt, const forbidden5gTACompressed_type *pSrc)
{
    uint16_t diffIdx = 0;
    uint16_t tacIdx = 1;

    if (pTgt == NULL)
    {
        PRINT("pTgt(=NULL) in decompress5gForbiddenTA\n");
        return ERROR;
    }
    if (pSrc == NULL)
    {
        PRINT("pSrc(=NULL) in decompress5gForbiddenTA\n");
        return ERROR;
    }

    if ((0 == pSrc->numTac) || (X2_maxnoofForbTACs < pSrc->numTac))
    {
        PRINT("pSrc->numTac is out of range (%d:%d:%d>\n", 0, pSrc->numTac, X2_maxnoofForbTACs);
        return ERROR;
    }

    pTgt->plmn = pSrc->plmn;
    pTgt->numTac = pSrc->numTac;

    memset(pTgt->fiveGTac, 0, sizeof(pTgt->fiveGTac));
    pTgt->fiveGTac[0] = pSrc->firstValue;
    for (diffIdx = 0, tacIdx = 1; ((tacIdx < pSrc->numTac) && (diffIdx < MAX_NUM_FORB_TA_COMPR_VAL_SA)); diffIdx++)
    {
        if (0 == pSrc->diff[diffIdx])
        {
            pTgt->fiveGTac[tacIdx] += 65535;
        }
        else
        {
            pTgt->fiveGTac[tacIdx] += pSrc->diff[diffIdx];
            pTgt->fiveGTac[tacIdx] += pTgt->fiveGTac[tacIdx - 1];
            tacIdx++;
        }
    }

    return GOOD;
}

/*
 * @brief           Decompress forbiddenTA, copy from ComLibUtility VLIB_DecompressForbiddenTA
 *
 * @param[out]      pTgt :          output structure
 * @param[in]       pSrc :          input structure
 * @return          status :        GOOD, ERROR / int16_t
 */
int16_t decompressForbiddenTA(forbiddenTA_type *pTgt, const forbiddenTACompressed_type *pSrc)
{
    uint16_t diffIdx = 0;
    uint16_t tacIdx = 1;

    if (pTgt == NULL)
    {
        PRINT("pTgt(=NULL) in decompressForbiddenTA\n");
        return ERROR;
    }
    if (pSrc == NULL)
    {
        PRINT("pSrc(=NULL) in decompressForbiddenTA\n");
        return ERROR;
    }

    if (0 == pSrc->numTac)
    {
        PRINT("pSrc->numTac is empty\n");
        return ERROR;
    }

    if (X2_maxnoofForbTACs < pSrc->numTac)
    {
        PRINT("pSrc->numTac is out of range (%d:%d:%d)\n", 0, pSrc->numTac, X2_maxnoofForbTACs);
        return ERROR;
    }

    pTgt->plmn = pSrc->plmn;
    pTgt->numTac = pSrc->numTac;

    memset(pTgt->tac, 0, sizeof(pTgt->tac));
    pTgt->tac[0] = pSrc->firstValue;
    for (diffIdx = 0, tacIdx = 1; ((tacIdx < pSrc->numTac) && (diffIdx < MAX_NUM_FORB_TA_COMPR_VAL)); diffIdx++)
    {
        if (0 == pSrc->diff[diffIdx])
        {
            pTgt->tac[tacIdx] = (uint16_t)(pTgt->tac[tacIdx] + 255);
        }
        else
        {
            pTgt->tac[tacIdx] = (uint16_t)(pTgt->tac[tacIdx] + pSrc->diff[diffIdx]);
            pTgt->tac[tacIdx] = (uint16_t)(pTgt->tac[tacIdx] + pTgt->tac[tacIdx - 1]);
            tacIdx++;
        }
    }
    return GOOD;
}

/*
 * @brief           Decompress hoRestrictInfo, copy from ComLibUtility decompressHoRestrictInfo
 *
 * @param[out]      pTgt :          output structure
 * @param[in]       pSrc :          input structure
 * @return          status :        GOOD, ERROR / int16_t
 */
int16_t decompressHoRestrictInfo(hoRestrictInfo_type *pTgt, const hoRestrictInfoCompressed_type *pSrc,
                                 enumCallType_type callType)
{
    int16_t status = GOOD;
    uint16_t loop = 0;

    if (pTgt == NULL)
    {
        PRINT("pTgt(=NULL) in decompressHoRestrictInfo\n");
        return ERROR;
    }
    if (pSrc == NULL)
    {
        PRINT("pSrc(=NULL) in decompressHoRestrictInfo\n");
        return ERROR;
    }

    pTgt->existFlag = pSrc->existFlag;
    if (FALSE == pSrc->existFlag)
    {
        return GOOD;
    }
    pTgt->nrRestrictionType = pSrc->nrRestrictionType;
    pTgt->servedPlmn = pSrc->servedPlmn;
    pTgt->numEplmn = pSrc->numEplmn;
    pTgt->numForbidTaPlmn = pSrc->numForbidTaPlmn;
    pTgt->forbiddenRat = pSrc->forbiddenRat;
    pTgt->lastEutraPlmnPresent = pSrc->lastEutraPlmnPresent;
    pTgt->lastEutraPlmn = pSrc->lastEutraPlmn;
    pTgt->cnTypeRestrictForServingPlmn = pSrc->cnTypeRestrictForServingPlmn;
    pTgt->cnTypeRestrictForEplmn = pSrc->cnTypeRestrictForEplmn;

    pTgt->allowedPlmnList[PrimaryRATRestriction].numNrAllowedPlmn = 0;
    pTgt->allowedPlmnList[PrimaryRATRestriction].numEutraAllowedPlmn = 0;
    pTgt->allowedPlmnList[SecondaryRATRestriction].numNrAllowedPlmn = 0;
    pTgt->allowedPlmnList[SecondaryRATRestriction].numEutraAllowedPlmn = 0;

    for (loop = 0; loop < MIN(pSrc->numEplmn, X2_maxnoofEPLMNs); loop++)
    {
        pTgt->ePlmn[loop] = pSrc->ePlmn[loop];
    }
    for (loop = 0; loop < MIN(pSrc->numForbidTaPlmn, X2_maxnoofEPLMNsPlusOne); loop++)
    {
        if (callType == E_CALLTYPE_SA)
        {
            status = decompress5gForbiddenTA(&pTgt->forbiddenTA[loop], &pSrc->forbidden5gTA[loop]);
        }
        else
        {
            status = decompressForbiddenTA(&pTgt->forbiddenTA[loop], &pSrc->forbiddenTA[loop]);
        }
        if (ERROR == status)
        {
            PRINT("decompressForbiddenTA ERROR!\n");
            return ERROR;
        }
    }

    pTgt->numRatRestriction = pSrc->numRatRestriction;
    for (loop = 0; loop < MIN(pSrc->numRatRestriction, NG_MaxnoofEPLMNsPlusOne); loop++)
    {
        pTgt->ratRestriction[loop] = pSrc->ratRestriction[loop];
    }

    pTgt->numServiceArea = pSrc->numServiceArea;
    for (loop = 0; loop < MIN(pSrc->numServiceArea, NG_MaxnoofEPLMNsPlusOne); loop++)
    {
        pTgt->serviceArea[loop] = pSrc->serviceArea[loop];
    }

    return GOOD;
}

