/**
 * @fn int parseGetBhcaOptions(int argc, char *argv[], log_opt_type *log_opt)
 * @brief   Parse option.val.c_str() of get bhca
 * @param   argc        [in] argument count
 * @param   argv[]      [in] argument values[argc]
 * @param   *log_opt    [in] log options
 * @return  GOOD/ERROR
 */
int parseGetBhcaOptions(int argc, char *argv[], bhca_opt_type *log_opt)
{
    itscpOptionParser itscpOption(argc, argv, "bcdfi:nhswz");
    for(auto &option : itscpOption.option)
    {
        switch (option.key)
        {
            case 'b':
            {
                log_opt->backupInfo = 1;
                break;
            }
            case 'c':  // clear
            {
                log_opt->clearDiffTime = 1;
                break;
            }
            case 'd':  // detail
            {
                log_opt->delayOption = 1;
                PRINT("MonitoringBhcaTimeDiff must be turned on to use the command.\n");
                break;
            }
            case 'f':  //-f
            {
                log_opt->followOption = 1;
                break;
            }
            case 'i':  // interval
            {
                uint8_t itv = StrUtil::itscp_strtoul<uint8_t>(option.val.c_str());
                log_opt->interval = itv;
                break;
            }
            case 'n':  // NSA
            {
                log_opt->nsaCallOnly = 1;
                break;
            }
            case 's':  // SA
            {
                log_opt->saCallOnly = 1;
                break;
            }
            case 'h':  // help
            {
                usageGetBhca();
                return ERROR;
            }
            case 'w':  // write result into file
            {
                log_opt->writeInFile = 1;
                break;
            }
            default:
                break;
        }
    }

    return GOOD;
}

/**
 * @fn int parseGetCfgFooOptions(int argc, char *argv[], log_opt_type *log_opt)
 * @brief   Parse option.val.c_str() of config foo commands
 * @param   argc        [in] argument count
 * @param   argv[]      [in] argument values[argc]
 * @param   *log_opt    [in] log options
 * @return  ERROR in case of -h (help) and number of options otherwise
 */
int parseGetCfgFooOptions(int argc, char *argv[], log_opt_type *log_opt)
{
    log_opt->Color = 0;
    itscpOptionParser itscpOption(argc, argv, "Ch");
    for(auto &option : itscpOption.option)
    {
        switch (option.key)
        {
            case 'C':
            {
                log_opt->Color = 1;
                break;
            }
            case 'h':
            {
                return ERROR;
            }
            default:
                break;
        }
    }

    return static_cast<int>(itscpOption.option.size());
}

/**
 *  @brief Print Memory Usage Information.
 *  @param N/A
 *  @return N/A
 */
void printMemoryUsageInfo(vccbMemoryUsageInfo_type *pMemoryStatInfo)
{
    uint32_t avgBufferSize;

    if (pMemoryStatInfo->allocCount != 0)
        avgBufferSize = (uint32_t)(pMemoryStatInfo->totBufferSize / pMemoryStatInfo->allocCount);
    else
        avgBufferSize = 0.0;

    PRINT("| avg: %20u (%7u / %5u)    min: %5u        max: %15u         |\n", avgBufferSize,
          pMemoryStatInfo->totBufferSize, pMemoryStatInfo->allocCount, pMemoryStatInfo->minBufferSize,
          pMemoryStatInfo->maxBufferSize);
}

