/**
 * @brief Replace Z-IMSI value in X2SgNBAdditionRequest.[experimental function]
 * @param[in] argc
 * @param[in] argv
 * @return GOOD
 * @exception N/A
 */
int replaceImsiAsnX2(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("[Experimental]\n");
        PRINT("USAGE: get asn x2 [hex string] imsi [imsi] (d): This command works only for X2SgNBAdditionRequest. \n");
    };
    AsnxProtocolType protocol = PROT_CP_X2AP;
    char *inArgHexSrcStr = NULL;
    char *inArgHexImsiStr = NULL;
    int pduNum = 1;
    X2_SgNBAdditionRequest_type *ptMsg = NULL;
    msgUnpack_type *ptUnpack = getgMsgBuf();
    int i, ret, imsiLen, dbgPrt = 0;

    optind = 0;

    if (argc < 4)
    {
        SHOW_USAGE();
        return GOOD;
    }

    inArgHexSrcStr = argv[1];
    inArgHexImsiStr = argv[3];

    // print option for debug purpose.
    if (argc >= 5)
    {
        if (!strcasecmp("d", argv[4]))
        {
            dbgPrt = 1;
        }
    }

    OssBuf encodedData;

    if (NULL == inArgHexSrcStr)
    {
        PRINT("No message provided \n");
        return GOOD;
    }

    imsiLen = (int)(strlen(inArgHexImsiStr) >> 1);
    if ((imsiLen > 8) || (imsiLen < 3))
    {
        PRINT("Wrong Imsi range %d. (valid:3 ~ 8)\n", imsiLen);
        return GOOD;
    }

    MACRO_UNPACK_X2_MSG_FROM_ALLOC();

    ptMsg = (X2_SgNBAdditionRequest_type *)ptUnpack->unpack;

    if (dbgPrt)
    {
        PRINT("ptMsg->nRUESecurityCapabilities.m.extended_zImsiPresent : %d\n",
              ptMsg->nRUESecurityCapabilities.m.extended_zImsiPresent);

        if (ptMsg->nRUESecurityCapabilities.m.extended_zImsiPresent)
        {
            PRINT("ptMsg->nRUESecurityCapabilities.extended_zImsi.length: %d\n",
                  ptMsg->nRUESecurityCapabilities.extended_zImsi.length);
            for (i = 0; i < MAX_IMSI_BYTE; i++)
            {
                PRINT("[FROM] zImsi.value[%d] = %02x\n", i, ptMsg->nRUESecurityCapabilities.extended_zImsi.value[i]);
            }
        }
    }

    convertStr2Hex(inArgHexImsiStr, (void *)ptMsg->nRUESecurityCapabilities.extended_zImsi.value, imsiLen);

    if (dbgPrt)
    {
        PRINT("imsiLen : %d\n", imsiLen);
        for (i = 0; i < MAX_IMSI_BYTE; i++)
        {
            PRINT("[TO  ] zImsi.value[%d] = %02x\n", i, ptMsg->nRUESecurityCapabilities.extended_zImsi.value[i]);
        }
    }

    ptMsg->nRUESecurityCapabilities.extended_zImsi.length = (uint16_t)imsiLen;
    ptMsg->nRUESecurityCapabilities.m.extended_zImsiPresent = 1;

    encodedData.value = getEncbuff();
    encodedData.length = encbuffSize;

    ret = PackX2_SgNBAdditionRequest((X2_SgNBAdditionRequest_type *)&ptUnpack->unpack,
                                     (unsigned char *)encodedData.value, (int *)&encodedData.length);
    if (ASN_OK != ret)
    {
        PRINT("PackX2_SgNBAdditionRequest ERROR!!!\n");
        return GOOD;
    }

    if (dbgPrt)
    {
        PRINT("encodedData.length = %ld\n", encodedData.length);

        PRINT("\n");
        PRINT(
            "+[CONVERT "
            "HEX]======================================================================================================"
            "======+\n");
    }

    PRINT("PRINT CONVERTED MSG : %s\n", FnITSCP_GetStrMsgId(ptUnpack->msgId));
    printHexData(NULL, 0, (uint8_t *)encodedData.value, (uint16_t)encodedData.length, 0);

    if (dbgPrt)
    {
        PRINT(
            "+[CONVERTED MSG "
            "=========================================================================================================="
            "==+\n");
    }
    fnASNX_decodeHex(protocol, pduNum, encodedData);
    PRINT(
        "+============================================================================================================+"
        "\n");

    return GOOD;
}

