    SHOW_VALUE(pCell->pdcchConfig.minBlindDetectionScg);
    SHOW_VALUE(pCell->mfbiConfig.specialBandChangeFlag);

    PRINT("+--[ul Path Parameters]-------------------------------------+\n");
    SHOW_VALUE(pCell->ulPathCongestionBased.ccceFailCongestionInThreshold);
    SHOW_VALUE(pCell->ulPathCongestionBased.ccceFailCongestionOutThreshold);
    SHOW_VALUE(pCell->ulPathCongestionBased.congestionUlPathEnabled);
    SHOW_VALUE(pCell->ulPathCongestionBased.congestionState);
    SHOW_VALUE(pCell->ulPathCongestionBased.congestionStateSliceLoad);
    SHOW_VALUE(pCell->ulPathCongestionBased.prbUsageCongestionInThreshold);
    SHOW_VALUE(pCell->ulPathCongestionBased.prbUsageCongestionOutThreshold);
    SHOW_VALUE(pCell->ulPathCongestionBased.ulDataSplitThresholdForCongestion);
    SHOW_VALUE(pCell->ulPathCongestionBased.ulSliceLoadBasedUlPathSwitchingOnOff);

