int GetCell_reportConfigControl(int32_t argc, char *argv[])  // reportConfigurationExtensionDb_type
{
    uint16_t cellNum;

    if (argc < 2)
    {
        PRINT("Please provide cellNum\n");
        return GOOD;
    }

    CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);

    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return GOOD;

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    reportConfigurationBaseDb_type *pReportConfig = NULL;
    reportConfigurationExtensionDb_type *pReportConfigControl = NULL;
    ueReportConfigurationDb_type *pUeReportConfig = NULL;
    uint16_t index = 0, index2 = 0, index3 = 0, index4 = 0, index5 = 0;

    // Report Configs
    PRINT("+==============================================================+\n");
    PRINT("| CellNum:%3d Report Configs NR Data                           |\n", cellNum);
    PRINT("+--------------------------------------------------------------+\n");
    for (index = 0; index < MAX_NR_OF_REPORT_CONFIG_ID_DB; index++)
    {
        pReportConfig = &pCell->measurementsData.reportConfigurationsDb[index].base;
        pReportConfigControl = &pCell->measurementsData.reportConfigurationsDb[index].extension;

        pUeReportConfig = pCell->measurementsData.ueSpecificReportConfigurations[index];

        if (pReportConfig->usage != CI_use)
        {
            continue;
        }
        PRINT(" ===== ReportConfigIdx = %d =====\n", index);
        // ue-specific-report-config-entries/report-choice/ax-case/ax-report-config
        getCellMeasData_ueSpecificReportConfigurationsNR(cellNum, index, pReportConfig->reportType, pReportConfig->reportPurpose);

        for (index2 = 0; index2 < MAX_NR_UE_SPECIFIC_REPORT_CONFIG_DB; index2++)
        {
            if (pUeReportConfig[index2].base.usage == CI_use)
            {
                PRINT(" index:%d, Usage:%d\n", index2, pUeReportConfig[index2].base.usage);
                for (index3 = 0; index3 < MAX_SVC_GRP_DB_NUM; index3++)
                {
                    if (pUeReportConfig[index2].extension.ueReportConfig.allowedSvcGrpId[index3] == true)
                    {
                        PRINT(" ueReportConfigIdx:%d SvcGrpId:%d\n", index2, index3);
                    }
                }
            }
        }

#define ENDC_SVC_GRP_ALLOWED_STR(_id)                                                                     \
    (pUeReportConfig[index2].extension.ueReportConfigEndc.plmn[index3].svcGrp[_id].isAllowed != 0 ? "ALLOWED" \
                                                                                              : "NOT-ALLOWED")
        PRINT("  ===== UE-SPECIFIC-REPORT ALLOWED-ENDC-SVC-GRP =====\n");
        // UE-SPECIFIC-INDEX
        for (index2 = 0; index2 < MAX_NR_UE_SPECIFIC_REPORT_CONFIG_DB; index2++)
        {
            if (CI_use != pUeReportConfig[index2].base.usage)
            {
                continue;
            }
            // PLMN
            for (index3 = 0; index3 < MAX_PLMN_INDEX; index3++)
            {
                // SVC-GRP-ID
                PRINT("  ue-id(%u)/plmn(%u): 0:%s, 1:%s, 2:%s, 3:%s, 4:%s\n", index2, index3,
                      ENDC_SVC_GRP_ALLOWED_STR(0), ENDC_SVC_GRP_ALLOWED_STR(1), ENDC_SVC_GRP_ALLOWED_STR(2),
                      ENDC_SVC_GRP_ALLOWED_STR(3), ENDC_SVC_GRP_ALLOWED_STR(4));
            }
        }
        PRINT("  ===== END  =====\n");
#undef ENDC_SVC_GRP_ALLOWED_STR

        PRINT(" plmnBasedControl: notMatchedPlmnOption:%d\n",
              pReportConfigControl->plmnBasedControl.notMatchedPlmnOption);

        for (index4 = 0; index4 < MAX_PLMN_INDEX; index4++)
        {
            const auto &plmnSupportEntry = pReportConfigControl->plmnBasedControl.plmn[index4];
            if (CI_use != plmnSupportEntry.usage)
            {
                continue;
            }
            PRINT(" plmnBasedControl: plmnIndex:%d option:%d\n", plmnSupportEntry.plmnIndex, plmnSupportEntry.option);

            for (index5 = 0; index5 < MAX_ENDC_SVCGRP_ID; ++index5)
            {
                const auto &endcServiceGroupEntry = plmnSupportEntry.endcServiceGroupEntries[index5];
                if (CI_use != endcServiceGroupEntry.usage)
                {
                    continue;
                }
                PRINT(" plmnBasedControl:  endcSvcGrpId:%d option:%d\n", endcServiceGroupEntry.svcGrpId, endcServiceGroupEntry.option);
            }
        }
        for (index5 = 0; index5 < MAX_SVC_GRP_DB_NUM; ++index5)
        {
            const auto &serviceGroupEntry = pReportConfigControl->plmnBasedControl.serviceGroupEntries[index5];
            if (CI_use == serviceGroupEntry.usage)
            {
                PRINT(" plmnBasedControl:             svcGrpId:%d option:%d\n", serviceGroupEntry.svcGrpId, serviceGroupEntry.option);
            }
        }
    }
    return GOOD;
}

