    SHOW_VALUE(pCell->fpMobilityControl.dlCapacityThreshold);
    SHOW_VALUE(pCell->fpMobilityControl.ulCapacityThreshold);
    SHOW_VALUE(pCell->fpMobilityControl.availableUeThreshold);

    // ODF_HO_21B
