    SHOW_VALUE(pCell->onDemandHoInfo.operationMode);
    SHOW_VALUE(pCell->onDemandHoInfo.preferRatForVoiceCall);
    SHOW_VALUE(pCell->onDemandHoInfo.preferRatForDataCall);
    SHOW_VALUE(pCell->onDemandHoInfo.timerForCallRelease);
    SHOW_VALUE(pCell->onDemandHoInfo.includeEmergHpaOnOff);  // ODF_HO_22C2_DISH
    SHOW_VALUE(pCell->onDemandHoInfo.includeMpsCall);        // ODF_HO_26B
    SHOW_VALUE(pCell->onDemandHoInfo.emergHpaMode);          // ODF_HO_25A

    // FOLLOW A2
    SHOW_VALUE(pCell->mobilityConfig.eutraHandoverFollowA2);
