    SHOW_VALUE(pCell->mobilityConfig.followA2WithMultipleTriggerQuantitySupportNr);
    SHOW_VALUE(pCell->mobilityConfig.followA2WithMultipleTriggerQuantitySupportEutra);
    SHOW_VALUE(pCell->mobilityConfig.multipleA1WithFollowA2Support);

    SHOW_VALUE(pCell->mobilityConfig.plmnBasedDedicatedPrioritySupport);
    SHOW_VALUE(pCell->mobilityConfig.handoverPrepFailedTimer);

    PRINT("+-----------------------------------------------+\n");
    PRINT("+===============================================+\n");

    return GOOD;
