int GetCellAnr(int32_t argc, char *argv[])
{
    uint16_t cellNum = MAX_CELL_NUM_ITSCP_VCCB;
    uint16_t gnbNum, plmnIndex;

    if (argc > 1)
    {
        CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);
    }

    if (cellNum < MAX_CELL_NUM_ITSCP_VCCB)
    {
        // Print specific cell only
        const VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
        gnbNum = pCell->gnbNum;

        if (gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
        {
            PRINT("Invalid CellNum:%d, GnbNum:%d\n", cellNum, gnbNum);
            return BAD;
        }

        const VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];

        PRINT("+========================================================================+\n");
        PRINT("| ANR Cell Information (cellNum:%5d, gnbNum:%5d)                     |\n", cellNum, gnbNum);
        PRINT("+------------------------------------------------------------------------+\n");
        PRINT("| anrSwitch[%d] mnsSwitch[%d] rreSwitch[%d] ueBasedSwitch[%d]\n", pCell->anrInfo.anrSwitch,
              pCell->anrInfo.mnsSwitch, pCell->anrInfo.rreSwitch, pCell->anrInfo.ueBasedAnrSwitch);
        PRINT("| invalidNcrDeleteSwitch[%d] autoGapsSwitch[%d]\n", pCell->anrInfo.invalidNcrDeleteSwitch,
              pCell->anrInfo.autonomousGapsSwitch);
        PRINT("| reportCgiSwitch [NR:%d/ENDC:%d/NRDC:%d/NEDC:%d]\n", pCell->anrInfo.reportCgiSwitch,
              pCell->anrInfo.reportCgiEndcSwitch, pCell->anrInfo.reportCgiNrdcSwitch, pCell->anrInfo.reportCgiNedcSwitch);
        PRINT("| MrSwitch        [Mobility:%d/NRDCAddition:%d/CA:%d]\n", pCell->anrInfo.mobilityMrSwitch,
              pCell->anrInfo.nrdcAdditionMrSwitch, pCell->anrInfo.caMrSwitch);
        PRINT("| longDrxCycle    [FR1:%2d/FR2:%2d]\n", pCell->anrInfo.longDrxCycleFr1, pCell->anrInfo.longDrxCycleFr2);
        // SVR24B FGS-SF0502 FR192, FR193
        PRINT("| longDrxCycleGbr [FR1:%2d/FR2:%2d]\n", pCell->anrInfo.longDrxCycleFr1Gbr, pCell->anrInfo.longDrxCycleFr2Gbr);
        PRINT("| reportCgiGbrSwitch [%d]\n", pCell->anrInfo.reportCgiGbrSwitch);
        PRINT("| ncrAddSchedUsageSwitch [%d]\n", pCell->anrInfo.ncrAddSchedUsageSwitch); // SVR25A FGS-SF0502 FR55
        PRINT("+------------------------------------------------------------------------+\n");
        PRINT("| plmnTranslationSwitch[%d]\n", pGnb->anrPlmnInfo.plmnTranslationSwitch);
        PRINT("| actPlmn.mcc : %03X       actPlmn.mnc : %03X       actPlmn.longId : %d\n", pGnb->anrPlmnInfo.actPlmn.s2.mcc,
              pGnb->anrPlmnInfo.actPlmn.s2.mnc, pGnb->anrPlmnInfo.actPlmn.longId);
        for (plmnIndex = 0; plmnIndex < MAX_PLMN_INDEX; ++plmnIndex)
        {
            PRINT("| rcvPlmn[%d].mcc : %03X    rcvPlmn[%d].mnc : %03X    rcvPlmn[%d].longId : %d\n", plmnIndex,
                  pGnb->anrPlmnInfo.rcvPlmn[plmnIndex].s2.mcc, plmnIndex, pGnb->anrPlmnInfo.rcvPlmn[plmnIndex].s2.mnc,
                  plmnIndex, pGnb->anrPlmnInfo.rcvPlmn[plmnIndex].longId);
        }

        MACRO_PRINT_MNS_SCHEDULE_INFO();
        PRINT("+========================================================================+\n");

        return GOOD;
    }
    else
    {
        // Print all cells in table format
        PRINT("+========================================================================================================================================================================+\n");
        PRINT("| ANR Cell Information (All Cells)                                                                                                                                     |\n");
        PRINT("+------------------------------------------------------------------------------------------------------------------------------------------------------------------------+\n");
        PRINT("| cell |anrS|mnsS|rreS|ueBS|invNcrDelS|autoGapS|rptCgiS_NR|rptCgiS_ENDC|rptCgiS_NRDC|rptCgiS_NEDC|MrS_Mob|MrS_NRDCAdd|MrS_CA|lDrxCy_FR1|lDrxCy_FR2|lDrxCyGbr_FR1|lDrxCyGbr_FR2|rptCgiGbrS|ncrAddSchUS|\n");
        PRINT("+------------------------------------------------------------------------------------------------------------------------------------------------------------------------+\n");

        for (cellNum = 0; cellNum < MAX_CELL_NUM_ITSCP_VCCB; ++cellNum)
        {
            const VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
            if (pCell->status != EQUIP) continue;

            gnbNum = pCell->gnbNum;
            if (gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
            {
                PRINT("| %4d |Invalid GnbNum:%d                                                                                                                                    |\n",
                    cellNum, gnbNum);
                continue;
            }

            PRINT("| %4d |%3d |%3d |%3d |%3d |%9d |%7d |%9d | %10d | %10d | %10d |%6d |%10d | %4d |%9d |%9d |%12d |%12d |%9d |%10d |\n",
                  cellNum,
                  pCell->anrInfo.anrSwitch,
                  pCell->anrInfo.mnsSwitch,
                  pCell->anrInfo.rreSwitch,
                  pCell->anrInfo.ueBasedAnrSwitch,
                  pCell->anrInfo.invalidNcrDeleteSwitch,
                  pCell->anrInfo.autonomousGapsSwitch,
                  pCell->anrInfo.reportCgiSwitch,
                  pCell->anrInfo.reportCgiEndcSwitch,
                  pCell->anrInfo.reportCgiNrdcSwitch,
                  pCell->anrInfo.reportCgiNedcSwitch,
                  pCell->anrInfo.mobilityMrSwitch,
                  pCell->anrInfo.nrdcAdditionMrSwitch,
                  pCell->anrInfo.caMrSwitch,
                  pCell->anrInfo.longDrxCycleFr1,
                  pCell->anrInfo.longDrxCycleFr2,
                  pCell->anrInfo.longDrxCycleFr1Gbr,
                  pCell->anrInfo.longDrxCycleFr2Gbr,
                  pCell->anrInfo.reportCgiGbrSwitch,
                  pCell->anrInfo.ncrAddSchedUsageSwitch);
        }

        PRINT("+========================================================================================================================================================================+\n");

        return GOOD;
    }
}

int GetCellMeasColoc(int32_t argc, char *argv[])
{
    uint16_t cellNum = MAX_CELL_PER_VNF;

    CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    measColocCellInfo_type *pMeasColocCellInfo = &pCell->measColocInfo;

    auto getIMLBThresholdTypeStr = [](uint8_t type)
    {
        switch (type)
        {
            case enumMeasThresholdTypeLb_rsrp:
                return "rsrp";
            case enumMeasThresholdTypeLb_rsrq:
                return "rsrq";
            case enumMeasThresholdTypeLb_both:
                return "both";
            case enumMeasThresholdTypeLb_disable:
            default:
                return "disable";
        }
    };

    auto getSetupDcTypeStr = [](uint8_t measUeTypeSetupDc)
    {
        switch (measUeTypeSetupDc)
        {
            case UMFS_SETUP_DC_OFF:
                return "off";
            case UMFS_SETUP_DC_BOTH:
                return "both";
            case UMFS_SETUP_DC_ENDC:
                return "endc";
            case UMFS_SETUP_DC_NRDC:
                return "nrdc";
            default:
                break;
        }

        return "<invalid>";
    };

    PRINT("+===============================================================================================+\n");
    PRINT("| Cell SON meas-coloc-info (cellNum:%5d)                                                      |\n", cellNum);
    PRINT("+-----------------------------------------------------------------------------------------------+\n");
    PRINT("| ueMeasSchedule : %d, measHistogram : %s, measHistogramEutra : %d\n", pMeasColocCellInfo->ueMeasSchedule,
          getTwoBitValueAsBinaryString(pMeasColocCellInfo->measHistogram), pMeasColocCellInfo->measHistogramEutra);
    PRINT("| measUeType - SetupRRC: %s, SetupDC : %s, SetupDC-LBM : %s, ChangePSCell : %d, HandIn : %d\n",
          getTwoBitValueAsBinaryString(pMeasColocCellInfo->measUeTypeSetupRrc),
          getSetupDcTypeStr(pMeasColocCellInfo->measUeTypeSetupDc[NR_LBM_DISABLE]),
          getSetupDcTypeStr(pMeasColocCellInfo->measUeTypeSetupDc[NR_LBM_WINDOW0_UPDATE]),
          pMeasColocCellInfo->measUeTypeChangePscell, pMeasColocCellInfo->measUeTypeHandIn);
    PRINT(
        "| ueMeasTriggerThreshold : %3d, ueMeasRateNr : %3d, ueMeasRateNrLbm : %3d, ueMeasRateCbrs : %3d, "
        "ueMeasRateEutra : %3d\n",
        pMeasColocCellInfo->ueMeasTriggerThreshold, pMeasColocCellInfo->ueMeasRateNr[NR_LBM_DISABLE],
        pMeasColocCellInfo->ueMeasRateNr[NR_LBM_WINDOW0_UPDATE], pMeasColocCellInfo->ueMeasRateCbrs,
        pMeasColocCellInfo->ueMeasRateEutra);
    PRINT("| maxNrMeasHourly : %4d, maxCbrsMeasHourly : %4d, maxEutraMeasHourly : %4d\n",
          pMeasColocCellInfo->maxNrMeasHourly, pMeasColocCellInfo->maxCbrsMeasHourly,
          pMeasColocCellInfo->maxEutraMeasHourly);
    PRINT("| measThresholdType - ANR : %d, CA : %d, RsrpCA: %d, CBRS : %d, FAC : %d, IratANR : %d, IratEutraES: %d\n",
          pMeasColocCellInfo->measThresholdTypeAnr,  //
          pMeasColocCellInfo->measThresholdTypeCa, pMeasColocCellInfo->measRsrpThresholdTypeCa,
          pMeasColocCellInfo->measThresholdTypeCbrs, pMeasColocCellInfo->measThresholdTypeFac,
          pMeasColocCellInfo->measThresholdTypeIratAnr, pMeasColocCellInfo->measThresholdTypeIratEutraEs);
    PRINT("| RsrpOffsetAnr: %d, RsrqOffsetAnr: %d\n", pMeasColocCellInfo->measRsrpOffsetAnr,
          pMeasColocCellInfo->measRsrqOffsetAnr);
    PRINT("| IMLB Threshold : type:%s, level:%s, rsrp:%u, rsrq:%u\n",
          getIMLBThresholdTypeStr(pMeasColocCellInfo->measThresholdTypeLb),
          pMeasColocCellInfo->measThresholdLevelLb == 0 ? "cell" : "cell-freq", pMeasColocCellInfo->measRsrpThresholdLb,
          pMeasColocCellInfo->measRsrqThresholdLb);
    PRINT("| RsrpThAnr: %d, RsrqThAnr: %d, RsrpThIratAnr: %d, RsrqThIratAnr: %d\n",
          pMeasColocCellInfo->measRsrpThresholdAnr, pMeasColocCellInfo->measRsrqThresholdAnr,
          pMeasColocCellInfo->measRsrpThresholdIratAnr, pMeasColocCellInfo->measRsrqThresholdIratAnr);
    PRINT("| RsrpThIratEutraES: %d, RsrqThIratEutraES: %d\n", pMeasColocCellInfo->measRsrpThresholdTypeIratEutraEs,
          pMeasColocCellInfo->measRsrqThresholdTypeIratEutraEs);
    PRINT("| measFaAutoUpdateSwitch : %d\n", pMeasColocCellInfo->measFaAutoUpdateSwitch);
    if (pCell->gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB)
    {
        const VccbGnbInfo_type *const pGnb = &PGNBINFO[pCell->gnbNum];

        MACRO_PRINT_MNS_SCHEDULE_INFO();
    }
    PRINT("+===============================================================================================+\n");

    return GOOD;
}

