void GetCellLbInfo_PscellChangeLbInfo(const PscellChangeLbInfo_type &pscellChangeLbInfo)
{
    const auto GetLoadEvaluateModeStr = [](const uint8_t mode) -> const char * {
        switch (mode)
        {
            case loadEvalMode_resource:
                return "resource";
            case loadEvalMode_ue:
                return "ue";
            case loadEvalMode_effective_resource:
                return "effective-resource";
            default:
                return "unknown";
        }
    };
    const auto GetResourceModeOptionStr = [](const uint8_t option) -> const char * {
        switch (option)
        {
            case LB_RESOURCE_MODE_OPTION_MIN_DL_UL:
                return "min-dl-ul";
            case LB_RESOURCE_MODE_OPTION_DL:
                return "dl";
            case LB_RESOURCE_MODE_OPTION_UL:
                return "ul";
            default:
                return "unknown";
        }
    };

    PRINT("+----------------------------------------------------------------------+\n");
    PRINT("| PSCell Change Load Balancing Info                                    |\n");
    PRINT("+----------------------------------------------------------------------+\n");
    PRINT("| pscellChangeLbSwitch: %s\n", (pscellChangeLbInfo.pscellChangeLbSwitch ? "enable" : "disable"));
    PRINT("| pdcchCceBasedLoadEvaluateSupport: %s, loadEvaluateMode: %u(%s)\n",
        (pscellChangeLbInfo.pdcchCceBasedLoadEvaluateSupport ? "enable" : "disable"),
        pscellChangeLbInfo.loadEvaluateMode, GetLoadEvaluateModeStr(pscellChangeLbInfo.loadEvaluateMode));
    PRINT("| mrWaitTimer: %u, rscDelta: %d, ueDelta: %d, effRscDelta: %d\n",
        pscellChangeLbInfo.mrWaitTimer, pscellChangeLbInfo.rscDelta, pscellChangeLbInfo.ueDelta, pscellChangeLbInfo.effRscDelta);
    PRINT("| resourceModeOption: %u(%s), skipAvailableUeThreshold: %d\n",
        pscellChangeLbInfo.resourceModeOption, GetResourceModeOptionStr(pscellChangeLbInfo.resourceModeOption),
        pscellChangeLbInfo.skipAvailableUeThreshold);
    PRINT("| targetCellSelectionStrongestOnly: %s\n",
        (pscellChangeLbInfo.targetCellSelectionStrongestOnly ? "true" : "false"));
    PRINT("| availRscThreshold[0-3]: %d %d %d %d\n",
        pscellChangeLbInfo.availRscThreshold[0], pscellChangeLbInfo.availRscThreshold[1],
        pscellChangeLbInfo.availRscThreshold[2], pscellChangeLbInfo.availRscThreshold[3]);
    PRINT("| availUeThreshold[0-3]: %d %d %d %d\n",
        pscellChangeLbInfo.availUeThreshold[0], pscellChangeLbInfo.availUeThreshold[1],
        pscellChangeLbInfo.availUeThreshold[2], pscellChangeLbInfo.availUeThreshold[3]);
    PRINT("| effAvailRscThreshold[0-3]: %d %d %d %d\n",
        pscellChangeLbInfo.effAvailRscThreshold[0], pscellChangeLbInfo.effAvailRscThreshold[1],
        pscellChangeLbInfo.effAvailRscThreshold[2], pscellChangeLbInfo.effAvailRscThreshold[3]);
    PRINT("| ulCceFailureRateThreshold: %d, pdcchCceUsageThreshold: %d\n",
        pscellChangeLbInfo.ulCceFailureRateThreshold, pscellChangeLbInfo.pdcchCceUsageThreshold);
    PRINT("| targetUlCceFailureRateThresh: %d, targetPdcchCceUsageThresh: %d\n",
        pscellChangeLbInfo.targetUlCceFailureRateThreshold, pscellChangeLbInfo.targetPdcchCceUsageThreshold);
    PRINT("+----------------------------------------------------------------------+\n");
}

int GetCellLbInfo(int32_t argc, char *argv[])
{
    const auto GetLoadEvaluateModeStr = [](const uint8_t mode) -> const char * {
        switch (mode)
        {
            case loadEvalMode_resource:
                return "resource";
            case loadEvalMode_ue:
                return "ue";
            case loadEvalMode_effective_resource:
                return "effective-resource";
            default:
                return "unknown";
        }
    };
    const auto GetResourceModeOptionStr = [](const uint8_t option) -> const char * {
        switch (option)
        {
            case LB_RESOURCE_MODE_OPTION_MIN_DL_UL:
                return "min-dl-ul";
            case LB_RESOURCE_MODE_OPTION_DL:
                return "dl";
            case LB_RESOURCE_MODE_OPTION_UL:
                return "ul";
            default:
                return "unknown";
        }
    };

    uint16_t cellNum;

    CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);

    const VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];

    PRINT("+===========================================================================+\n");
    PRINT("| Connected Mode Cell Load Balancing Information (cellNum:%5d)              |\n", cellNum);
    PRINT("+---------------------------------------------------------------------------+\n");
    PRINT("| usage : %3d                                                                \n",
          pCell->lbCfg.connModeLbInfo.usage);
    PRINT("| loadEvaluateMode : %3d (%s)                                                \n",
          pCell->lbCfg.connModeLbInfo.loadEvaluateMode,
          GetLoadEvaluateModeStr(pCell->lbCfg.connModeLbInfo.loadEvaluateMode));
    PRINT("| mrWaitTimer : %u                                                           \n",
          pCell->lbCfg.connModeLbInfo.mrWaitTimer);
    PRINT("+---------------------------------------------------------------------------+\n");
    PRINT("| resourceModeOption : %3d (%s)                                              \n",
          pCell->lbCfg.connModeLbInfo.resourceModeOption,
          GetResourceModeOptionStr(pCell->lbCfg.connModeLbInfo.resourceModeOption));
    PRINT("| availRscThreshold  : %3d, availUeThreshold  : %3d, availEffectRscTh  : %3d \n",
          pCell->lbCfg.connModeLbInfo.availRscThreshold,
          pCell->lbCfg.connModeLbInfo.availUeThreshold,
          pCell->lbCfg.connModeLbInfo.availEffRscThreshold);
    PRINT("| availRscThreshold1 : %3d, availUeThreshold1 : %3d, availEffectRscTh1  : %3d\n",
          pCell->lbCfg.connModeLbInfo.availRscThreshold1,
          pCell->lbCfg.connModeLbInfo.availUeThreshold1,
          pCell->lbCfg.connModeLbInfo.availEffRscThreshold1);
    PRINT("| availRscThreshold2 : %3d, availUeThreshold2 : %3d, availEffectRscTh2  : %3d\n",
          pCell->lbCfg.connModeLbInfo.availRscThreshold2,
          pCell->lbCfg.connModeLbInfo.availUeThreshold2,
          pCell->lbCfg.connModeLbInfo.availEffRscThreshold2);
    PRINT("| availRscThreshold3 : %3d, availUeThreshold3 : %3d, availEffectRscTh3  : %3d\n",
          pCell->lbCfg.connModeLbInfo.availRscThreshold3,
          pCell->lbCfg.connModeLbInfo.availUeThreshold3,
          pCell->lbCfg.connModeLbInfo.availEffRscThreshold3);
    PRINT("| rscDelta : %3d, ueDelta : %3d, effRscDelta : %3d,                          \n",
          pCell->lbCfg.connModeLbInfo.rscDelta,
          pCell->lbCfg.connModeLbInfo.ueDelta, pCell->lbCfg.connModeLbInfo.effRscDelta);
    PRINT("+---------------------------------------------------------------------------+\n");
    PRINT("| pdcchCceBasedLoadEvaluateSupport : %3d                                     \n",
          pCell->lbCfg.connModeLbInfo.pdcchCceBasedLoadEvaluateSupport);
    PRINT("| ulCceFailureRateThreshold : %3d                                            \n",
          pCell->lbCfg.connModeLbInfo.ulCceFailureRateThreshold);
    PRINT("| pdcchCceUsageThreshold : %3d                                               \n",
          pCell->lbCfg.connModeLbInfo.pdcchCceUsageThreshold);
    PRINT("| targetUlCceFailureRateThreshold : %3d                                      \n",
          pCell->lbCfg.connModeLbInfo.targetUlCceFailureRateThreshold);
    PRINT("| targetPdcchCceUsageThreshold : %3d                                         \n",
          pCell->lbCfg.connModeLbInfo.targetPdcchCceUsageThreshold);
    PRINT("| periodicLbSwitch : %3d                                                     \n",
          pCell->lbCfg.connModeLbInfo.periodicLbSwitch);
    PRINT("| skipAvailableUeThreshold : %3d, targetCellSelectionStrongestOnly : %s      \n",
          pCell->lbCfg.connModeLbInfo.skipAvailableUeThreshold, pCell->lbCfg.connModeLbInfo.targetCellSelectionStrongestOnly ? "true" : "false");
    PRINT("+---------------------------------------------------------------------------+\n");
    PRINT("| Cell SPID Load Balancing Support                                          |\n");
    PRINT("+---------------------------------------------------------------------------+\n");
    for (int spidIdx = 0; spidIdx < MAX_SPID_VALUE; ++spidIdx)
    {
        if (CI_no_use == pCell->lbCfg.spidLbSupport.spidLbSupportEntries[spidIdx].usage)
        {
            continue;
        }
    PRINT("| SPID(%3d): supportLbPscellChange(%u)\n",
        (spidIdx + 1), pCell->lbCfg.spidLbSupport.spidLbSupportEntries[spidIdx].supportLbPscellChange);
    }

    GetCellLbInfo_PscellChangeLbInfo(pCell->lbCfg.pscellChangeLbInfo);
    GetRedCapLbInfo(cellNum);

    return GOOD;
}

