int GetCellRscInfo(int32_t argc, char *argv[])
{
    uint16_t cellNum;
    sonCellPrbRsc_type *pCellPrbSrc = NULL;
    sonNbrPrbRsc_type *pNbrPrbRsc = NULL;
    int nbrCellIdx = 0;
    int totalCount = 0;

    CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    pCellPrbSrc = &pCell->cellRscInfo;
    pNbrPrbRsc = pCellPrbSrc->nbrPrb;

    PRINT("+======================================================================+\n");
    PRINT("| Cell Resource Information (cellNum:%5d)                            |\n", cellNum);
    PRINT("+----------------------------------------------------------------------+\n");
    PRINT("+ gnbId(%d) NCGI (%03X-%03X-%lu) gnbNum(%d)\n", pCellPrbSrc->gnbId, pCellPrbSrc->nrCgi.plmn.s2.mcc,
          pCellPrbSrc->nrCgi.plmn.s2.mnc, pCellPrbSrc->nrCgi.ci, pCellPrbSrc->gnbNum);
    PRINT("| dlCapacityValue : %3d  | ulCapacityValue : %3d  | numAvailUe : %3d    \n", pCellPrbSrc->dlCapacityValue,
          pCellPrbSrc->ulCapacityValue, pCellPrbSrc->numAvailUe);
    PRINT("| ulCceFailRate   : %3d  | dlCceUsage : %3d       | ulCceUsage : %3d    \n",
          pCellPrbSrc->ulCceFailRate, pCellPrbSrc->dlCceUsage, pCellPrbSrc->ulCceUsage);
    PRINT("+----------------------------------------------------------------------+\n");
    PRINT("|  Nbr Cell Resource Information                                       |\n");
    PRINT("+----------------------------------------------------------------------+\n");
    for (nbrCellIdx = 0; nbrCellIdx < MAX_NBR_RELATION_TABLE_PER_CELL; nbrCellIdx++)
    {
        if (N_EQUIP == pNbrPrbRsc[nbrCellIdx].usage)
        {
            continue;
        }
        totalCount++;
        sonNbrPrbRsc_type *pSonNbr = &pNbrPrbRsc[nbrCellIdx];
        uint32_t availRscDL = 0, availRscUL=0;

        PRINT("|------ nbrCellIdx : %3d ------\n", nbrCellIdx);
        PRINT("| isRsUpdate : %3d                       \n", pSonNbr->isRsUpdate);
        PRINT("| dlCapacityValue(%3d) ulCapacityValue(%3d) numAvailUe(%3d)\n", pSonNbr->dlCapacityValue, pSonNbr->ulCapacityValue, pSonNbr->numAvailUe);
        PRINT("| ulCceFailRate(%3d) dlCceUsage(%3d) ulCceUsage(%3d)\n", pSonNbr->ulCceFailRate, pSonNbr->dlCceUsage, pSonNbr->ulCceUsage);
        PRINT("| dlTotalBandwidth(%5u) dlCCV(%3u) ulCCV(%3u)\n", pSonNbr->dlTotalBandwidth, pSonNbr->dlCCCV, pSonNbr->ulCCCV);

        if (pSonNbr->ulCCCV > 0 && pSonNbr->dlCCCV > 0)
        {
            availRscDL = (uint32_t)(pSonNbr->dlCapacityValue * pSonNbr->dlTotalBandwidth * ((double)pSonNbr->dlCCCV) / (pSonNbr->ulCCCV + pSonNbr->dlCCCV));
            availRscUL = (uint32_t)(pSonNbr->ulCapacityValue * pSonNbr->dlTotalBandwidth * ((double)pSonNbr->ulCCCV) / (pSonNbr->ulCCCV + pSonNbr->dlCCCV));
        }
        PRINT("| availableResourceDL(%8u) availableResourceUL(%8u)\n", availRscDL, availRscUL);
    }
    PRINT("|------ totalNbrCount : %3d ------ \n", totalCount);
    PRINT("+======================================================================+\n");

    return GOOD;
}

int GetCellSliceCacInfo(int32_t argc, char *argv[])
{
    uint16_t cellNum;
    sonCellSliceCac_type   *pCellSliceCac = NULL;
    sliceCacInfo_type      *pSliceCac = NULL;
    uint16_t sliceCacCount = 0, sliceCacIdx = 0;

    CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    pCellSliceCac = &pCell->cellCacInfo;

    PRINT("+======================================================================+\n");
    PRINT("| Cell Slice CAC Information (cellNum:%5d)                        |\n", cellNum);
    PRINT("+----------------------------------------------------------------------+\n");
    PRINT("+ gnbId(%d) NCGI (%03X-%03X-%u)\n", pCellSliceCac->gnbId, pCellSliceCac->gnbPlmn.s2.mcc,
          pCellSliceCac->gnbPlmn.s2.mnc, pCellSliceCac->cellIdentity);
    PRINT("+----------------------------------------------------------------------+\n");
    PRINT("|  Slice CAC Information                                               |\n");
    PRINT("+----------------------------------------------------------------------+\n");

    sliceCacCount = MIN(pCellSliceCac->sliceCount, MAX_ACTIVE_SLICE_NUM);

    for (sliceCacIdx = 0; sliceCacIdx < sliceCacCount; sliceCacIdx++)
    {
        pSliceCac = &pCellSliceCac->sliceCac[sliceCacIdx];

        PRINT("|------ sliceCac [%3d] ------\n", sliceCacIdx);
        PRINT("| sliceIndex      : %3d \n", pSliceCac->sliceIndex);
        PRINT("| dlSliceCapacity : %3d       | ulSliceCapacity : %3d \n",
            pSliceCac->dlSliceCapacity, pSliceCac->ulSliceCapacity);
        PRINT("| dlUeTputViolationRate : %3d | ulUeTputViolationRate : %3d \n",
            pSliceCac->dlUeTputViolationRate, pSliceCac->ulUeTputViolationRate);
    }
    PRINT("|                   - totalNbrCount : %3d -                             \n", sliceCacCount);
    PRINT("+======================================================================+\n");

    return GOOD;
}

