    PRINT_CPFAIL_STAT(pStatFail, StatEndcSpCellSelFail_UeNotSupCellFreqBand);
    PRINT_CPFAIL_STAT(pStatFail, StatEndcSpCellSelFail_UeNotSupChannelBw);
    PRINT_CPFAIL_STAT(pStatFail, StatEndcSpCellSelFail_UeNotSupBandCombination);
