int GetCfgGnbEmergencyArpInfo(int32_t argc, char *argv[])
{
    uint16_t gnbNum = 0;
    uint8_t plmnIndex;
    char printFlag = 0;
    switch (argc)
    {
        // Print Equip state ARP info
        case 1:
            break;
        // Print all state ARP info
        case 2:
            printFlag = *argv[1];
            break;
        default:
            break;
    }

    PRINT("+========================================================================================+\n");
    PRINT("|                              Emergency ARP Information                                 |\n");
    PRINT("------------------------------------------------------------------------------------------\n");

    PRINT("|GNB_NUM|GNB_ID|PLMN_IDX|shmStatus| emerArpOption|emerArpValue|fiveqiValue|fiveQiArpValue|\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("------------------------------------------------------------------------------------------\n");
    for (plmnIndex = 0; plmnIndex < MAX_PLMN_INDEX; plmnIndex++)
    {
        if (pGnb->emerArpInfo[plmnIndex].shmStatus != EQUIP && !(printFlag == 'a' || printFlag == 'A')) continue;
        PRINT("|%7u|%6u|%8u|", gnbNum, pGnb->globalGnbId.gnbId.id, plmnIndex);
        if (pGnb->emerArpInfo[plmnIndex].shmStatus == EQUIP)
            PRINT("  EQUIP  ");
        else
            PRINT(" N_EQUIP ");
        if (pGnb->emerArpInfo[plmnIndex].emerArpOption == 0)
            PRINT("|   ARP-ONLY   ");
        else
            PRINT("|  FIVEQI-ARP  ");
        PRINT("|%12d|%11d|%14d|\n", pGnb->emerArpInfo[plmnIndex].emerArpValue, pGnb->emerArpInfo[plmnIndex].fiveqiArp[0].fiveqiValue,
              pGnb->emerArpInfo[plmnIndex].fiveqiArp[0].fiveqiArpValue);
    }

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+========================================================================================+\n");
    return GOOD;
}

