int GetCfgGnbServiceSaConfig(int32_t argc, char *argv[])
{
    auto ShowUsage = []() {
        PRINT("USAGE: itscp_vccb get cfg gnb serviceSaConfig [gnbNum]\n");
    };

    if (argc > 1)
    {
        ShowUsage();
        return GOOD;
    }

    int32_t optGnbNum = -1;
    if (argc == 1)
    {
        optGnbNum = StrUtil::itscp_strtol<int32_t>(argv[0]);
        if (optGnbNum < 0 || optGnbNum >= (int32_t)MAX_GNB_PER_SYS_ITSCP_VCCB)
        {
            ShowUsage();
            return GOOD;
        }
        if (PGNBINFO[optGnbNum].status != EQUIP)
        {
            PRINT("gnb[%d] is not equipped!!\n", optGnbNum);
            ShowUsage();
            return GOOD;
        }
    }

    PRINT("+================================================================================+\n");
    PRINT("| gNB service-configuration / service-sa-entries (svcCfgSaEntries)               |\n");
    PRINT("+--------------------------------------------------------------------------------+\n");

    for (uint16_t gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (optGnbNum >= 0 && (uint16_t)optGnbNum != gnbNum) continue;
        VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
        if (pGnb->status != EQUIP) continue;

        PRINT("===================== GNB_NUM[%u] GNB_ID[%10u] ==============================\n", gnbNum,
              pGnb->globalGnbId.gnbId.id);

        for (int slot = 0; slot < MAX_SVC_SA_ENTRIES; slot++)
        {
            const svcCfgSa_type *p = &pGnb->cfg.svcCfgSaEntries[slot];
            if (itscpSvcCfgSaSlotEmpty(p)) continue;

            PRINT("-- slot[%2d] plmn_index=%u service_sa_index=%u service_sa_usage=%u\n", slot, p->plmn_index,
                  p->service_sa_index, p->service_sa_usage);
            PRINT("   numSlice=%u numQos5qi=%u numArp=%u numRfsp=%u numUeType=%u\n", p->numSlice, p->numQos5qi,
                  p->numArp, p->numRfsp, p->numUeType);
            PRINT("   slice (sstSd hex): ");
            for (uint8_t i = 0; i < p->numSlice && i < MAX_SVC_CONFIG_8; i++)
            {
                PRINT("0x%08X ", p->slice[i].sstSd);
            }
            PRINT("\n   qos_5qi: ");
            for (uint8_t i = 0; i < p->numQos5qi && i < MAX_SVC_CONFIG_16; i++) PRINT("%u ", p->qos_5qi[i]);
            PRINT("\n   arp: ");
            for (uint8_t i = 0; i < p->numArp && i < MAX_SVC_CONFIG_8; i++) PRINT("%u ", p->arp[i]);
            PRINT("\n   rfsp: ");
            for (uint8_t i = 0; i < p->numRfsp && i < MAX_SVC_CONFIG_8; i++) PRINT("%u ", p->rfsp[i]);
            PRINT("\n   ue_type: ");
            for (uint8_t i = 0; i < p->numUeType && i < MAX_SVC_CONFIG_UE_TYPE; i++)
                PRINT("%s(%u) ", itscpSvcCfgUeTypeStr(p->ue_type[i]), p->ue_type[i]);
            PRINT("\n\n");
        }
    }

    PRINT("+================================================================================+\n");
    return GOOD;
}

