int GetCapabilityRequestFilterGnb(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;
    uint16_t gnbNum, noofBandNR = 0, noofBandEUTRA = 0;
    int loop = 0;

    PRINT("+=======================================================+\n");
    PRINT("| Capability Request Filter Information\n");
    PRINT("---------------------------------------------------------\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    noofBandNR = 0, noofBandEUTRA = 0;

    PRINT("+--- bandNR Information\n");
    for (loop = 0; loop < MAX_REQUEST_FILTER_NR_BAND; loop++)
    {
        if (pGnb->capabilityRequestFilter.bandNR[loop].usage != CI_use) continue;
        PRINT("|  band[%5d]\n", pGnb->capabilityRequestFilter.bandNR[loop].band);
        PRINT("|  maxBandwidthRequestedDl : %5d \n",
              pGnb->capabilityRequestFilter.bandNR[loop].nrBandReqLimitInfo.maxBandwidthRequestedDl);
        PRINT("|  maxBandwidthRequestedUl : %5d \n",
              pGnb->capabilityRequestFilter.bandNR[loop].nrBandReqLimitInfo.maxBandwidthRequestedUl);
        PRINT("|  maxCarriersRequestedDl  : %5d \n",
              pGnb->capabilityRequestFilter.bandNR[loop].nrBandReqLimitInfo.maxCarriersRequestedDl);
        PRINT("|  maxCarriersRequestedUl  : %5d \n",
              pGnb->capabilityRequestFilter.bandNR[loop].nrBandReqLimitInfo.maxCarriersRequestedUl);
        noofBandNR++;
    }
    SHOW_VALUE(noofBandNR);
    PRINT("+--- bandEUTRA Information\n");
    for (loop = 0; loop < MAX_REQUEST_FILTER_EUTRA_BAND; loop++)
    {
        if (pGnb->capabilityRequestFilter.bandEUTRA[loop].usage != CI_use) continue;
        PRINT("|  band[%5d] (band-block-flag: %d) \n", pGnb->capabilityRequestFilter.bandEUTRA[loop].band,
              pGnb->capabilityRequestFilter.bandEUTRA[loop].bandBlockFlag);
        PRINT("|  caBandwidthClassDlEutra :  %5d \n",
              pGnb->capabilityRequestFilter.bandEUTRA[loop].eutraBandReqLimitInfo.caBandwidthClassDlEutra);
        PRINT("|  caBandwidthClassUlEutra :  %5d \n",
              pGnb->capabilityRequestFilter.bandEUTRA[loop].eutraBandReqLimitInfo.caBandwidthClassUlEutra);
        noofBandEUTRA++;
    }
    SHOW_VALUE(noofBandEUTRA);

    PRINT("+--- Eutra Req Limit Information\n");
    PRINT("|  requestSkipFallbackComb      :  %5d \n",
          pGnb->capabilityRequestFilter.eutraReqLimitInfo.requestSkipFallbackComb);
    PRINT("|  requestReducedIntNonContComb :  %5d \n",
          pGnb->capabilityRequestFilter.eutraReqLimitInfo.requestReducedIntNonContComb);
    PRINT("|  requestedMaxccsDl            :  %5d \n",
          pGnb->capabilityRequestFilter.eutraReqLimitInfo.requestedMaxccsDl);
    PRINT("|  requestedMaxccsUl            :  %5d \n",
          pGnb->capabilityRequestFilter.eutraReqLimitInfo.requestedMaxccsUl);
    PRINT("+--- UCE options  \n");
    PRINT("|  srsSwitchingTimeRequest      :  %5d \n", pGnb->capabilityRequestFilter.uceOptionInfo.srsSwitchingTimeRequest);
    PRINT("|  fallbackGroupFiveRequest_r17 :  %5d \n", pGnb->capabilityRequestFilter.uceOptionInfo.fallbackGroupFiveRequest_r17);
    PRINT("|  ueCapabilityRatRequest(0: All RAT, 1: NR only,  2: NR and EUTRA) :  %5d \n", pGnb->capabilityRequestFilter.uceOptionInfo.uceRatRequestType);
    PRINT("+--- Device Identification Request Filter  \n");
    PRINT("|  usage :  %5d \n", pGnb->capabilityRequestFilter.deviceIdentifyFilter.usage);
    PRINT("|  band :  %5d \n", pGnb->capabilityRequestFilter.deviceIdentifyFilter.band);
    PRINT("|  caBandwidthClassDlEutra: %d, caBandwidthClassUlEutra: %d\n",
        pGnb->capabilityRequestFilter.deviceIdentifyFilter.eutraBandReqLimitInfo.caBandwidthClassDlEutra,
        pGnb->capabilityRequestFilter.deviceIdentifyFilter.eutraBandReqLimitInfo.caBandwidthClassUlEutra);
    PRINT("\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+=======================================================+\n");

    return GOOD;
}

