const char* getBearerType(int bearerType, uint8_t snTermSplitFlag)
{
    (void)snTermSplitFlag; // unused

    const char *bType = "";
    switch (bearerType)
    {
        case MN_Term_MCG_Bearer:
            bType = "MN_MCG";
            break;
        case SN_Term_SCG_Bearer:
            bType = "SN_SCG";
            break;
        case SN_Term_SPLIT_Bearer:
            bType = "SN_SPLIT";
            break;
        case MN_Term_SPLIT_Bearer:
            bType = "MN_SPLIT";
            break;
        case SN_Term_MCG_Bearer:
            bType = "SN_MCG";
            break;
        case MN_Term_SCG_Bearer:
            bType = "MN_SCG";
            break;
        case SN_Term_Undetermined:
            bType = "SN_Undetm";
            break;
        case MN_Term_Undetermined:
            bType = "MN_Undetm";
            break;
        default:
            break;
    }

    return bType;
}

