int GetQosInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;
    callInfo_type *ptCi = NULL;
    uint32_t callId = 0;
    uint32_t pidx = 0, didx = 0, qidx = 0, drbIdxInCall = 0;
    bool representativeQosFlow = false;
    callPDUSessInfo_type *ptPi = NULL;
    callDRBInfo_type *ptDi = NULL;
    qosFlowInfo_type *ptQi = NULL;

    if (1 >= argc)  // callId is not included
    {
        PRINT("Usage : itscp_vccb get call qosinfo [callId] \n");
        return GOOD;
    }

    callId = StrUtil::itscp_strtoul<uint32_t>(argv[1]);

    uint32_t maxUeNum = (uint32_t)MAX_UE_NUM_ITSCP_VCCB;
    if (callId >= maxUeNum)
    {
        PRINT("Error! Missing input argument (range over, max:%d, cur:%u)\n", maxUeNum, callId);
        PRINT("Usage : itscp_vccb get call qosinfo [callId] \n");
        return GOOD;
    }

    const char *prefix[4] = {"+-", "| ", "  "};

    PRINT("+=====================================================================+\n");
    PRINT(" PDU Session | DRB | QOS | Information                              (ID)\n");
    PRINT("-----------------------------------------------------------------------\n");

    ptCi = &PENVCALL[callId];
    if (CI_use != ptCi->usage) return GOOD;
    PRINT("Call%d \n", callId);

    for (pidx = 0; pidx < MAX_PDU_SESS_PER_CALL; pidx++)
    {
        if (CI_no_use == ptCi->pduSess[pidx].usage) continue;
        ptPi = &ptCi->pduSess[pidx];

        PRINT("%sPdu%d(%s) \n", prefix[0], ptPi->pduSessId, getQosInfoStatus(static_cast<enumSABearerStatus_type>(ptPi->pduSessStatus)));
        PRINT("%snGuUlInfo %08X \n", prefix[0], ptPi->nGuUlInfo.TEID);
        PRINT("%snGuDlInfo %08X \n", prefix[0], ptPi->nGuDlInfo.TEID);
        PRINT("%ssnNGuUlInfo %08X \n", prefix[0], ptPi->snNGuUlInfo.TEID);
        PRINT("%ssnNGuDlInfo %08X \n", prefix[0], ptPi->snNGuDlInfo.TEID);

        for (didx = 0; didx < MAX_DRB_PER_SA_CALL; didx++)
        {
            drbIdxInCall = ptPi->drbIndex[didx];

            ptDi = &ptCi->drb[drbIdxInCall];
            if (CI_no_use == ptDi->usage) continue;

            PRINT("%s%sDrb%d(%s)(%s) \n", prefix[1], prefix[0], ptDi->dRBId, getBearerType((int)ptDi->bearerType.val, 0), getQosInfoStatus(static_cast<enumSABearerStatus_type>(ptDi->drbStatus)));
            PRINT("%s%sf1uUlInfo %08X \n", prefix[1], prefix[0], ptDi->f1uUlInfo.TEID);
            PRINT("%s%sf1uDlInfo %08X \n", prefix[1], prefix[0], ptDi->f1uDlInfo.TEID);

            PRINT("%s%sxNuUlInfo %08X \n", prefix[1], prefix[0], ptDi->xNuUlInfo.TEID);
            PRINT("%s%sxNuDlInfo %08X \n", prefix[1], prefix[0], ptDi->xNuDlInfo.TEID);
            if(ptDi->drbQosMonitoring < QOS_MONITORING_REQUEST_NOT_PRESENT)
            {
                PRINT("%s%sDrbQosMonitoring: %s\n", prefix[1], prefix[0], getQosMonitoringVal(ptDi->drbQosMonitoring));
            }
            if(ptDi->termPointBasedDrbQos.qosMonitoringRequestPresent)
                PRINT("%s%stermPointQosMonitoring : %s \n", prefix[1], prefix[0], getQosMonitoringVal(ptDi->termPointBasedDrbQos.qosMonitoringRequest));

            for (qidx = 0; qidx < MAX_QOS_FLOW_PER_PDU_SESS; qidx++)
            {
                representativeQosFlow = false;
                if (ptPi->qosFlowIndex[qidx] >= MAX_QOS_FLOW_PER_CALL) continue;
                ptQi = &ptCi->qosFlow[ptPi->qosFlowIndex[qidx]];
                if (CI_no_use == ptQi->usage) continue;
                if (ptQi->drbIdxInCall != drbIdxInCall) continue;
                if (ptPi->qosFlowIndex[qidx] == ptDi->drbQosIdxInCall)
                {
                    representativeQosFlow = true;
                }

                PRINT("%s%s%sQos%d(%s)%s \n", prefix[1], prefix[1], prefix[0], ptQi->flowId,getQosInfoStatus(static_cast<enumSABearerStatus_type>(ptQi->qosFlowStatus)), representativeQosFlow?"(***)":"");
                PRINT("%s%s%s%s5QI%d \n", prefix[1], prefix[1], prefix[1], prefix[0], ptQi->qosParam.nonDyna.fiveQi);
                PRINT("%s%s%s%sARP%d \n", prefix[1], prefix[1], prefix[1], prefix[0],
                      ptQi->qosParam.allocAndRetent.priorityLevel);
                if(ptQi->qosParam.qosMonitoringRequestPresent)
                {
                    PRINT("%s%s%s%sQosMonitoring: %s\n", prefix[1], prefix[1], prefix[1], prefix[0],
                        getQosMonitoringVal(ptQi->qosParam.qosMonitoringRequest));
                }
            }
        }
    }

    PRINT("+=====================================================================+\n");

    return GOOD;
}

int GetCellIRatAnr(int32_t argc, char *argv[])
{
    uint16_t cellNum, gnbNum;

    (void)argc;
    (void)argv;

    PRINT("+========================================================================================================================================================================+\n");
    PRINT("| Inter RAT ANR Cell Information (All Cells)                                                                                                                                     |\n");
    PRINT("+------------------------------------------------------------------------------------------------------------------------------------------------------------------------+\n");
    PRINT("| cell |anrS|ueBS|autoGapS|lDrxCy|lDrxCyGbr|rptCgiS_EUTRA|rptCgiS_NRDC|rptCgiS_NEDC|rptCgiS_GBR|mrS_Mob|mrS_NEDCAdd|mrS_epsFb|eutraNcrAddSchUS|\n");
    PRINT("+------------------------------------------------------------------------------------------------------------------------------------------------------------------------+\n");

    for (cellNum = 0; cellNum < MAX_CELL_NUM_ITSCP_VCCB; ++cellNum)
    {
        VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
        if (pCell->status != EQUIP) continue;

        gnbNum = pCell->gnbNum;

        if (gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
        {
            PRINT("| %4d |Invalid GnbNum:%d                                                                                                                                    |\n", cellNum, gnbNum);
            continue;
        }

        iratAnrCellInfo_type *pAnrInfo = &pCell->irat_anrInfo;
        PRINT("| %4d |%3d |%3d |%7d | %4d |%8d |%12d |%11d |%11d |%10d |%6d |%10d |%8d |%15d |\n",
              cellNum,
              pAnrInfo->anrSwitch,
              pAnrInfo->ueBasedAnrSwitch,
              pAnrInfo->eutraAutonomousGapsSwitch,
              pAnrInfo->longDrxCycle,
              pAnrInfo->longDrxCycleGbr,
              pAnrInfo->eutraReportCgiSwitch,
              pAnrInfo->eutraReportCgiNrdcSwitch,
              pAnrInfo->eutraReportCgiNedcSwitch,
              pAnrInfo->eutraReportCgiGbrSwitch,
              pAnrInfo->eutraMobilityMrSwitch,
              pAnrInfo->nedcAdditionMrSwitch,
              pAnrInfo->epsFallbackMrSwitch,
              pAnrInfo->eutraNcrAddSchedUsageSwitch);
    }

    PRINT("+========================================================================================================================================================================+\n");

    return GOOD;
}

