#ifndef __NVGNB__
int GetCallChecksum(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint32_t maxUeNum = MAX_UE_NUM_ITSCP_VCCB;
    uint32_t callId = (uint32_t)-1;
    bool isAllSearch = false;

    if (argc != 1 && argc != 2)
    {
        PRINT("Usage : Get CallChecksum [callId] \n");
        return GOOD;
    }

    PRINT("\n");
    PRINT("+==============================================================================+\n");
    PRINT("|                   CALL Checksum Info                                         |\n");
    PRINT("+==============================================================================+\n");

    if (argc == 1)
    {
        isAllSearch = true;
    }
    else if (argc == 2)
    {
        callId = StrUtil::itscp_strtoul<uint32_t>(argv[1]);
    }

    if (callId >= maxUeNum && isAllSearch == false)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }

    unsigned char c[MD5_DIGEST_LENGTH];
    uint32_t i;
    uint32_t callIdx;
    MD5_CTX mdContext;
    unsigned long bytes = 0;
    unsigned long forbiddenTASize = 0;
    unsigned long dynamicSize = 0;
    unsigned char *data = NULL;
    callInfo_type *ptCi = NULL;

    for (callIdx = 0; callIdx < maxUeNum; callIdx++)
    {
        if (isAllSearch == false && PENVCALL[callId].usage != CI_use)  // call id input
        {
            PRINT("CallId(%d) not used !! \n", callId);
            return GOOD;
        }

        if (isAllSearch == true)  // call id input x
        {
            callId = callIdx;
            if (PENVCALL[callId].usage != CI_use)
            {
                continue;
            }
        }

        ptCi = &(PENVCALL[callId]);

        MD5_Init(&mdContext);
        data = (unsigned char *)ptCi;
        bytes = (unsigned char *)(&ptCi->hoRestrict.forbiddenTA) - (unsigned char *)ptCi;

        // variable : hoRestrict.forbiddenTA (union)
        if (E_CALLTYPE_SA == ptCi->callType)
        {
            forbiddenTASize = sizeof(forbidden5gTACompressed_type);
        }
        else
        {
            forbiddenTASize = sizeof(forbiddenTACompressed_type);
        }
        dynamicSize = MIN(ptCi->hoRestrict.numForbidTaPlmn, X2_maxnoofEPLMNsPlusOne) * forbiddenTASize;
        bytes += dynamicSize;

        MD5_Update(&mdContext, data, bytes);
        // **** STEP 1. RANGE - 'usage' ~ 'hoRestrict' **** end//
        // fixed : 'usage' ~ 'hoRestrict.encoded'

        data = (unsigned char *)(&ptCi->backupSeqNum_last);
        bytes = (unsigned char *)(&ptCi->locRpt.areaofInterest.aoI[0]) - (unsigned char *)(&ptCi->backupSeqNum_last);

        // variable : locRpt.areaofInterest.noofAoI (union)
        dynamicSize = MIN(ptCi->locRpt.areaofInterest.noofAoI, NG_MaxnoofAoI) * sizeof(locRptAoIItem_type);
        bytes += dynamicSize;

        MD5_Update(&mdContext, data, bytes);
        // **** STEP 2. RANGE - 'backupSeqNum_last' ~ 'locRpt' ****  end//
        // fixed : 'backupSeqNum_last' ~ 'locRpt.areaofInterest.aol[0]'

        MD5_Final(c, &mdContext);

        PRINT("| #%06d ", ptCi->callId);
        for (i = 0; i < MD5_DIGEST_LENGTH; i++)
        {
            PRINT("%02x", c[i]);
        }
        PRINT("\n");

        if (isAllSearch == false)
        {
            break;
        }
    }
    PRINT("+==============================================================================+\n");

    return GOOD;
}
#endif

void GetCallHex_log(const char *pDbName, unsigned char *pData, uint32_t bytes)
{
    uint32_t dbIndex = 0;

    PRINT(" %s (length: %d) \n", pDbName, bytes);
    PRINT("================================================================================\n");
    PRINT("%06d | ", 0);
    for (dbIndex = 0; dbIndex < bytes; dbIndex++)
    {
        PRINT("%02x ", *pData);
        pData++;

        if (dbIndex % 16 == 0)
        {
            PRINT("\n");
            PRINT("%06d | ", dbIndex);
        }
    }
    PRINT("\n");
}

/**
 *  @brief Get Call Hex
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetCallHex(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint32_t callId = (uint32_t)-1;

    if (argc != 2)
    {
        PRINT("Usage : Get CallHex [callId] \n");
        return GOOD;
    }
    callId = StrUtil::itscp_strtoul<uint32_t>(argv[1]);

    PRINT("\n");
    PRINT("+==============================================================================+\n");
    PRINT("|                   CALL Hex Info                                              |\n");
    PRINT("+==============================================================================+\n");

    if (callId >= MAX_UE_NUM_ITSCP_VCCB)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }

    if (PENVCALL[callId].usage != CI_use)
    {
        PRINT("CallId(%d) not used !! \n", callId);
        return GOOD;
    }

    uint32_t bytes = 0;
    long forbiddenTASize = 0;
    unsigned char *pData = NULL;
    callInfo_type *ptCi = NULL;

    ptCi = &(PENVCALL[callId]);

    pData = (unsigned char *)ptCi;
    bytes = (unsigned char *)(&ptCi->hoRestrict.forbiddenTA) - (unsigned char *)ptCi;

    GetCallHex_log("ptCi ~ ptCi->hoRestrict.forbiddenTA static range", pData, bytes);
    PRINT("+------------------------------------------------------------------------------+\n");

    // variable : hoRestrict.forbiddenTA (union)
    forbiddenTASize =
        (E_CALLTYPE_SA == ptCi->callType ? sizeof(forbidden5gTACompressed_type) : sizeof(forbiddenTACompressed_type));
    pData = (unsigned char *)&ptCi->hoRestrict.forbiddenTA;
    bytes = (uint32_t)(MIN(ptCi->hoRestrict.numForbidTaPlmn, X2_maxnoofEPLMNsPlusOne) * forbiddenTASize);

    GetCallHex_log("hoRestrict.forbiddenTA (union) dynamic range", pData, bytes);
    PRINT("+------------------------------------------------------------------------------+\n");

    pData = (unsigned char *)(&ptCi->backupSeqNum_last);
    bytes = (unsigned char *)(&ptCi->locRpt.areaofInterest.aoI[0]) - (unsigned char *)(&ptCi->backupSeqNum_last);

    GetCallHex_log("backupSeqNum_last ~ locRpt.areaofInterest.aoI static range", pData, bytes);
    PRINT("+------------------------------------------------------------------------------+\n");

    // variable : locRpt.areaofInterest.noofAoI (union)
    pData = (unsigned char *)(&ptCi->locRpt.areaofInterest.aoI[0]);
    bytes = (uint32_t)(MIN(ptCi->locRpt.areaofInterest.noofAoI, NG_MaxnoofAoI) * sizeof(locRptAoIItem_type));

    GetCallHex_log("locRpt.areaofInterest.noofAoI (union) dynamic range", pData, bytes);
    PRINT("+==============================================================================+\n");

    return GOOD;
}

