/**
 *  @brief Get CSL Config Information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */

std::string_view  getCslOptionStr(int32_t cslOption)
{
    switch (cslOption)
    {
        case YANG_NS_PREFIX(type_csl_disable):
            return "csl-disable";
        case YANG_NS_PREFIX(type_abnormal_call_only):
            return "abnormal-call-only";
        case YANG_NS_PREFIX(type_normal_and_abnormal_and_intra_ho_call):
            return "normal-and-abnormal-and-intra-ho-call";
        case YANG_NS_PREFIX(type_normal_and_abnormal_and_intra_ho_and_rre_call):
            return "normal-and-abnormal-and-intra-ho-and-rre-call";
        default:
            return "Unknown";
    }
}

