/**
 * @brief     Get time duration from prevTime to current time, unit is minutes
 */
static uint16_t getTimeDifferenceMins(struct timespec prevTime)
{
    AUTO_TRACE_FUNC;
    int32_t diffTime;
    struct timespec curTime = {0,0};
    clock_gettime(CLOCK_MONOTONIC, &curTime);
    diffTime = (int32_t)((curTime.tv_sec - prevTime.tv_sec)/60);
    if (diffTime <= 0)
    {
        return 0;
    }
    return (uint16_t)diffTime;
}

int GetCfgTimerInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+===============================================+\n");
    PRINT("| Timer Info                                    +\n");
    PRINT("+-----------------------------------------------+\n");
    PRINT("+ Used in combination with Gnb Yang TimerInfo.  +\n");
    PRINT("+ Please check together when checking the data. +\n");
    PRINT("+-----------------------------------------------+\n");

    uint16_t loop = 0;
    for (loop = 0; loop < VCCB_X2AP_Timerid - VCCB_NRRRC_Timerid; loop++)
    {
        if (PCFG->timer.value[loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[0][loop], PCFG->timer.value[loop]);
    }

    for (loop = 0; loop < VCCB_Internal_Timerid - VCCB_X2AP_Timerid; loop++)
    {
        if (PCFG->timer.value[VCCB_X2AP_Timerid - VCCB_NRRRC_Timerid + loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[1][loop],
              PCFG->timer.value[VCCB_X2AP_Timerid - VCCB_NRRRC_Timerid + loop]);
    }

    for (loop = 0; loop < VCCB_Bearer_Timerid - VCCB_Internal_Timerid; loop++)
    {
        if (PCFG->timer.value[VCCB_Internal_Timerid - VCCB_NRRRC_Timerid + loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[2][loop],
              PCFG->timer.value[VCCB_Internal_Timerid - VCCB_NRRRC_Timerid + loop]);
    }

    for (loop = 0; loop < VCCB_UeContext_Timerid - VCCB_Bearer_Timerid; loop++)
    {
        if (PCFG->timer.value[VCCB_Bearer_Timerid - VCCB_NRRRC_Timerid + loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[3][loop],
              PCFG->timer.value[VCCB_Bearer_Timerid - VCCB_NRRRC_Timerid + loop]);
    }

    for (loop = 0; loop < VCCB_NGAP_Timerid - VCCB_UeContext_Timerid; loop++)
    {
        if (PCFG->timer.value[VCCB_UeContext_Timerid - VCCB_NRRRC_Timerid + loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[4][loop],
              PCFG->timer.value[VCCB_UeContext_Timerid - VCCB_NRRRC_Timerid + loop]);
    }

    for (loop = 0; loop < VCCB_XNAP_Timerid - VCCB_NGAP_Timerid; loop++)
    {
        if (PCFG->timer.value[VCCB_NGAP_Timerid - VCCB_NRRRC_Timerid + loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[5][loop],
              PCFG->timer.value[VCCB_NGAP_Timerid - VCCB_NRRRC_Timerid + loop]);
    }

    for (loop = 0; loop < MAX_VCCB_XNAP_Timerid - VCCB_XNAP_Timerid; loop++)
    {
        if (PCFG->timer.value[VCCB_XNAP_Timerid - VCCB_NRRRC_Timerid + loop] == 0) continue;
        PRINT("| %-54s- timer value = %7d\n", TIMER_STRING[6][loop],
              PCFG->timer.value[VCCB_XNAP_Timerid - VCCB_NRRRC_Timerid + loop]);
    }
    PRINT("+===============================================+\n");

    return GOOD;
}

