int GetCfgTraceCfgInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;
    GlobalTraceInfo_type *traceInfo = NULL;
    traceInfo = &PCFG->globalTraceInfo;
    int32_t index = 0;
    char date[20];


    PRINT("+==============================+\n");
    PRINT("| Trace Configuration Info     |\n");
    PRINT("+------------------------------+\n");
    PRINT("| CellTraceOnOff           :%4d|\n", traceInfo->cellTraceOnOff);
    PRINT("| OvrldOnOff               :%4d|\n", traceInfo->overloadOnOff);
    PRINT("| StopThrshd               :%4d|\n", traceInfo->stopThreshold);
    PRINT("| ResmThrshd               :%4d|\n", traceInfo->resumeThreshold);
    PRINT("| TceReplacementOnOff      :%4d|\n", traceInfo->signaling.trace.tceReplacementOnOff);
    PRINT("| NsaSignalingTraceOnOff   :%4d|\n", traceInfo->signaling.trace.nsaSignalingTraceOnOff);
    PRINT("| uex2TraceOnOff           :%4d|\n", traceInfo->signaling.trace.endcX2TraceOnOff);
    PRINT("| nrdcSignalingTraceOnOff  :%4d|\n", traceInfo->signaling.trace.nrdcSignalingTraceOnOff);
    PRINT("| nrdcSnXnTraceOnOff       :%4d|\n", traceInfo->signaling.trace.nrdcSnXnTraceOnOff);
    PRINT("| [SIG]thrptAndRfTraceOnOff:%4d|\n", traceInfo->signaling.trace.throughputAndRfTraceOnOff);
    PRINT("| [MGT]thrptAndRfTraceOnOff:%4d|\n", traceInfo->management.throughputAndRfTraceOnOff);
    PRINT("| [MGT]rfspSpidFilterOnOff :%4d|\n", traceInfo->management.rfspSpidFiltering.filteringOnOff);
    PRINT("| acpfTraceAllowedFlag     :%4d|\n", traceInfo->acpfTraceAllowedFlag);
    PRINT("| [MGT]ueTraceCountCpc     :%4d|\n", traceInfo->management.cellTraceUeCountCpc);
    PRINT("| [MGT]totalUeCountCpc     :%4d|\n", traceInfo->management.totalMgtUeCountCpc);
    PRINT("| pldLimitCheck            :%4d|\n", traceInfo->pldLimitCheck);
    PRINT("| sigTraceAllowedFlag      :%4d|\n", traceInfo->signaling.sigTraceAllowedFlag);
    PRINT("| [SIG]totalUeCountCpc     :%4d|\n", traceInfo->signaling.totalSigUeCountCpc);
    PRINT("| [SIG]traceUeCountCpc     :%4d|\n", traceInfo->signaling.trace.traceUeCountCpc);
    PRINT("| deactTimer               :%4d|\n", traceInfo->deactTimer);
    PRINT("| [MGT]auditTimer          :%4d|\n", traceInfo->management.auditTimer);
    PRINT("| reportingType            :%4d|\n", traceInfo->reportingType);
    PRINT("| procedureCheckOnoff      :%4d|\n", traceInfo->procedureCodeCheckCfg.procedureCheckOnoff);
    PRINT("| msgId                    :%4d|\n", traceInfo->procedureCodeCheckCfg.msgId);
    PRINT("| procedureCode            :%4d|\n", traceInfo->procedureCodeCheckCfg.procedureCode);
    PRINT("| [MGT]auditHist                |\n");

    for (index=0; index<TRACE_AUDIT_HIST_SIZE; ++index)
    {
        struct tm timeInfo;
        gmtime_r(&traceInfo->management.traceAuditHist.entry[index].tv_sec, &timeInfo);
        (void)strftime (date, 20,"%x %X", &timeInfo);
        PRINT("||  %s : %6u (cN:%4u)||\n", date, traceInfo->management.traceAuditHist.entry[index].rmCnt,
                                            traceInfo->management.traceAuditHist.entry[index].cellNum);
    }
    PRINT("+------------------------------------------------------------------------------------------+\n");
    PRINT("| Predefined Tce-servers                                                                   |\n");
    PRINT("+------------------------------------------------------------------------------------------+\n");
    PRINT("| Idx | ipVer |                    Tce Address                                  | Tce-port |\n");
    PRINT("+------------------------------------------------------------------------------------------+\n");
    char addrbuf[INET6_ADDRSTRLEN];
    for (index = 0; index < TCE_MAX_NUMBER; index++)
    {
        PredefinedTceServers_type *server = &traceInfo->predefinedTceServers[index];

        if (EQUIP == server->status)
        {
            PRINT("| %3d | %5d | %63s | %8d |\n", index,
                  server->server.ip.MdsIp.IpVer,
                  (server->server.ip.MdsIp.IpVer == TCE_FQDN) ? server->server.fqdn : MdsIpToStr(&server->server.ip.MdsIp, addrbuf),
                  server->server.ip.MdsPort);
        }
    }

    PRINT(
        "+-------------------------------------------------------------------------------------------------------------"
        "---------------------------------------------+\n");
    PRINT(
        "|G|gnbId     |cellId|pld  |trace-reference |ON |dep|    interface    |CPC  |Allow|tce1Id|tce2Id|   0       1  "
        "targetPlmns  3       4       5   | MDT | LA  |\n");
    PRINT(
        "|n|          |      |index|mcc|mnc|trace Id|OFF|th |E1|F1|Uu|XN|NG|X2|UEnum|Flag |      |      "
        "|mcc-mnc|mcc-mnc|mcc-mnc|mcc-mnc|mcc-mnc|mcc-mnc|immed| min |\n");
    PRINT(
        "+-------------------------------------------------------------------------------------------------------------"
        "---------------------------------------------+\n");

    uint16_t loop = 0;
    index = 0;
    for (loop = 0; loop < MAX_CELL_NUM_ITSCP_VCCB; loop++)
    {
        VccbCellInfo_type *const pCell = &PCELLINFO[loop];

        if (pCell->gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
        {
            continue;
        }

        VccbGnbInfo_type *const pGnb = &PGNBINFO[pCell->gnbNum];

        if (!pCell->status)
        {
            continue;
        }

        // show only Active
        if ((argc < 2) && (VCCB_FLAG_OFF == pCell->traceSession.traceSessJobOnOff))
        {
            continue;
        }

        uint32_t gnbId = pGnb->globalGnbId.gnbId.id;
        uint32_t cellId = pCell->cellIdentity;
        ManagementTraceSessionPerCell_type *traceSession = &pCell->traceSession;
        uint16_t diffTime = getTimeDifferenceMins(traceSession->lastAuditTime);

        PRINT(
            "|%1d|%10d|%6d|%5d|%3X|%3X|%8d|%3d|%3d|%2d|%2d|%2d|%2d|%2d|%2d|%5d|%5d|%6d|%6d|%3X-%3X|%3X-%3X|%3X-%3X|%3X-"
            "%3X|%3X-%3X|%3X-%3X|%5d|%5d|\n",
            pCell->gnbNum, gnbId, cellId, traceSession->pldCellIndex,

            traceSession->cellTraceReference.plmn.s2.mcc, traceSession->cellTraceReference.plmn.s2.mnc,
            traceSession->cellTraceReference.traceId, traceSession->traceSessJobOnOff, traceSession->trace.traceDepth,

            (traceSession->trace.interfaces & TRACE_BITMASK_E1C) ? 1 : 0,
            (traceSession->trace.interfaces & TRACE_BITMASK_F1C) ? 1 : 0,
            (traceSession->trace.interfaces & TRACE_BITMASK_Uu) ? 1 : 0,
            (traceSession->trace.interfaces & TRACE_BITMASK_XNC) ? 1 : 0,
            (traceSession->trace.interfaces & TRACE_BITMASK_NGC) ? 1 : 0,
            (traceSession->trace.interfaces & TRACE_BITMASK_X2C) ? 1 : 0,

            traceSession->trace.cellTraceUeCountCpc,
            traceSession->trace.cellTraceAllowedFlag,  // VTMB counts total number of traced UEs and set
                                                       // PLDCellStauts.cellTraceAllowedFlag

            traceSession->trace.tce1Id, traceSession->trace.tce2Id,

            traceSession->targetPlmns.plmn[0].s2.mcc, traceSession->targetPlmns.plmn[0].s2.mnc,
            traceSession->targetPlmns.plmn[1].s2.mcc, traceSession->targetPlmns.plmn[1].s2.mnc,
            traceSession->targetPlmns.plmn[2].s2.mcc, traceSession->targetPlmns.plmn[2].s2.mnc,
            traceSession->targetPlmns.plmn[3].s2.mcc, traceSession->targetPlmns.plmn[3].s2.mnc,
            traceSession->targetPlmns.plmn[4].s2.mcc, traceSession->targetPlmns.plmn[4].s2.mnc,
            traceSession->targetPlmns.plmn[5].s2.mcc, traceSession->targetPlmns.plmn[5].s2.mnc,
            traceSession->mdt.mdtSessionConfiguration.immediate.functionOnOff,
            diffTime);
    }
    PRINT(
        "+-------------------------------------------------------------------------------------------------------------"
        "---------------------------------------------+\n");

    return GOOD;
}

