void printAllowedCaConfigNSA(void)
{
    uint8_t index1, index2, index3, index4, index5;
    PRINT("+-----------------------------------------------+\n");
    PRINT("| Allowed configuration NSA                     |\n");
    PRINT("+-----------------------------------------------+\n");
    for (index1 = 0; index1 < FrequencyRangeCa_MAX; index1++)
    {
        for (index2 = 0; index2 < MAX_DUPLEX_MODE; index2++)
        {
            for (index3 = 0; index3 < FrequencyRangeCa_MAX; index3++)
            {
                for (index4 = 0; index4 < MAX_DUPLEX_MODE; index4++)
                {
                    for (index5 = 0; index5 < BandDependencyCa_MAX; index5++)
                    {
                        if (VCCB_SUPPORTED == PCFG->allowedCaConfigNSA[index1][index2][index3][index4][index5])
                        {
                            MACRO_PRINT_CA_CONFIG_PCELL_SCELL();
                        }
                    }
                }
            }
        }
    }
    PRINT("+-----------------------------------------------+\n");
}

