const char *getUpgradeStatusType(upgradeStatus_type status)
{
    switch (status)
    {
        case CU_UPGRADE_NONE:
            return "CU_UPGRADE_NONE";
        case CU_UPGRADE_SHUTTING_DOWN:
            return "CU_UPGRADE_SHUTTING_DOWN";
        case CU_UPGRADE_RELEASE:
            return "CU_UPGRADE_RELEASE";
        case CU_UPGRADE_RELAY:
            return "CU_UPGRADE_RELAY";
        default:
            return "Unknown";
    }
}

