/**
 *  @brief Get Cfg AMF Information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbAmfInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+===============================================+\n");
    PRINT("| AMF Info                                      +\n");
    PRINT("| - REL_AMF_STATUS_ID    : 0x%08X           +\n", REL_AMF_STATUS_ID);
    PRINT("| - REL_AMF_PLMN_INFO_ID : 0x%08X           +\n", REL_AMF_PLMN_INFO_ID);
    PRINT("| - REL_AMF_TNL_STATUS_ID: 0x%08X           +\n", REL_AMF_TNL_STATUS_ID);
    PRINT("+-----------------------------------------------+\n");
    uint16_t gnbIdx = 0;
    for (gnbIdx = 0; gnbIdx < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbIdx++)
    {
        int loop1;
        for (loop1 = 0; loop1 < MAX_AMF_PER_GNB_CU_CP; loop1++)
        {
            if (PCFG->amf.pldAmfStatus[gnbIdx][loop1].status != EQUIP) continue;

            PRINT(" pldAmfStatus[%d][%d].gNBIdx:%d endPointIdx:%d status:%d serviceState:%d\n", gnbIdx, loop1,
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].gNBIdx, PCFG->amf.pldAmfStatus[gnbIdx][loop1].endPointIdx,
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].status, PCFG->amf.pldAmfStatus[gnbIdx][loop1].serviceState);
            PRINT("                   .gNBId:%u .relativeAmfCapacity:%d .servedGuamiCnt:%d .n26support:%d\n",
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].gNBId,
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].relativeAmfCapacity,
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].servedGuamiCnt, PCFG->amf.amfN26Support[gnbIdx][loop1]);
            PRINT("                   .amfNameInfo:%s\n", PCFG->amf.amfNameInfo[gnbIdx][loop1].amfName);

            uint16_t loop2;
            for (loop2 = 0;
                 (loop2 < PCFG->amf.pldAmfStatus[gnbIdx][loop1].servedGuamiCnt) && (loop2 < MAX_SERVED_GUAMI_PER_AMF);
                 loop2++)
            {
                PRINT(
                    "                       .plmn[%d]:0x%x(%u) .amfInfo[%d](R+S+P):0x%x(%u) (S+P):0x%x(%u) "
                    "(S):0x%x(%u)\n",
                    loop2, PCFG->amf.pldAmfStatus[gnbIdx][loop1].plmn[loop2],
                    PCFG->amf.pldAmfStatus[gnbIdx][loop1].plmn[loop2], loop2,
                    PCFG->amf.pldAmfStatus[gnbIdx][loop1].amfInfo[loop2],
                    PCFG->amf.pldAmfStatus[gnbIdx][loop1].amfInfo[loop2],
                    GET_AMF_SET_POINTER_FROM_AMFI(PCFG->amf.pldAmfStatus[gnbIdx][loop1].amfInfo[loop2]),
                    GET_AMF_SET_POINTER_FROM_AMFI(PCFG->amf.pldAmfStatus[gnbIdx][loop1].amfInfo[loop2]),
                    GET_AMF_SET_FROM_AMFI(PCFG->amf.pldAmfStatus[gnbIdx][loop1].amfInfo[loop2]),
                    GET_AMF_SET_FROM_AMFI(PCFG->amf.pldAmfStatus[gnbIdx][loop1].amfInfo[loop2]));
            }

            PRINT("                       .overloadStatus:%u .overloadResponsePresent:%u .overloadAction:%u\n",
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].overloadStatus,
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].overloadResponsePresent,
                  PCFG->amf.pldAmfStatus[gnbIdx][loop1].overloadAction);

            for (loop2 = 0;
                 (loop2 < PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedPlmnCnt) && (loop2 < MAX_PLMN_PER_AMF);
                 loop2++)
            {
                PRINT("                       .suppPlmn[%d]:0x%x(%u)\n", loop2,
                      PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedPlmn[loop2],
                      PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedPlmn[loop2]);

                uint16_t loop3;
                for (loop3 = 0; (loop3 < PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssaiCntPerPlmn[loop2]) &&
                                (loop3 < MAX_SNSSAI_PER_PLMN_AMF);
                     loop3++)
                {
                    PRINT("                           .suppSnssai[%d]:0x%x(%u) sst:x%02x(%u) sd:x%06x(%u)\n", loop3,
                          PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssai[loop2][loop3],
                          PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssai[loop2][loop3],
                          (PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssai[loop2][loop3] & 0xFF000000) >> 24,
                          (PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssai[loop2][loop3] & 0xFF000000) >> 24,
                          PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssai[loop2][loop3] & 0xFFFFFF,
                          PCFG->amf.pldAmfPlmnInfo[gnbIdx][loop1].supportedSnssai[loop2][loop3] & 0xFFFFFF);
                }
            }

            for (loop2 = 0; loop2 < MAX_TNL_PER_AMF; loop2++)
            {
                if (PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].status != EQUIP) continue;

                PRINT(" pldAmfTnlStatus[%d][%d][%d].gNBIdx:%d endPointIdx:%d tnlIdx:%d status:%d\n", gnbIdx, loop1,
                      loop2, PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].gNBIdx,
                      PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].endPointIdx,
                      PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].tnlIdx,
                      PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].status);
                PRINT("                         .gNBId:%u .weightFactor:%d .tnlUsage:%d .sctpState:%d\n",
                      PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].gNBId,
                      (uint8_t)PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].weightFactor,
                      PCFG->amf.pldAmfTnlStatus[gnbIdx][loop1][loop2].tnlUsage,
                      PCFG->amf.pldAmfTnlSctpState[gnbIdx][loop1][loop2].sctpState);
            }
            PRINT("\n");
        }

        PRINT("+-----------------------------------------------+\n\n");
    }
    PRINT("+===============================================+\n");

    return GOOD;
}

/**
 *  @brief Get Cfg GNB Supported Slice Information per Cell
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetSupportedSliceInfoAupf(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+===============================================+\n");
    PRINT("| AUPF Status                                   +\n");
    PRINT("| - REL_AUPF_STATUS_ID  : 0x%08X           +\n", REL_AUPF_STATUS_ID);
    PRINT("| - REL_AUPF_PLMN_INFOID: 0x%08X           +\n", REL_AUPF_PLMN_INFO_ID);
    PRINT("+-----------------------------------------------+\n");

    AupfStatusInfo_type *pAupf = NULL;
    uint16_t gnbIdx, aupfIdx, plmnIdx, snssaiIdx;
    uint32_t sd = 0, sst = 0, snssai = 0;
    uint32_t sd2 = 0, sst2 = 0, snssai2 = 0;

    for (gnbIdx = 0; gnbIdx < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbIdx++)
    {
        VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbIdx];
        if (pGnb->status != EQUIP) continue;

        for (aupfIdx = 0; aupfIdx < MAX_GNB_CU_UP_PER_GNB_CU_CP; aupfIdx++)
        {
            if (pGnb->aupf.gnbCuUp[aupfIdx].status != EQUIP) continue;

            pAupf = &pGnb->aupf.gnbCuUp[aupfIdx];

            PRINT("+-----------------------------------------------+\n");
            PRINT(" gNBIdx[%d] gNBId:%d AUPFIdx[%d] aupfId:%lu\n", pAupf->gNBIdx, pAupf->gNBId, aupfIdx, pAupf->aupfId);
            PRINT("+-----------------------------------------------+\n");
            for (plmnIdx = 0; plmnIdx < MAX_E1_SUPPORTED_PLMN; plmnIdx++)
            {
                if (pAupf->supportedSnssaiGrpCntPerPlmn[plmnIdx] == 0) continue;
                PRINT("    [PLMN: %x(%d)]\n", pAupf->plmn[plmnIdx], pAupf->plmn[plmnIdx]);
                PRINT("     - supportedSnssai Lists(Grp Cnt: %d)\n", pAupf->supportedSnssaiGrpCntPerPlmn[plmnIdx]);

                for (snssaiIdx = 0; snssaiIdx < MIN(pAupf->supportedSnssaiGrpCntPerPlmn[plmnIdx], MAX_SNSSAI_PER_PLMN);
                     snssaiIdx++)
                {
                    snssai = pAupf->supportedSnssaiGrp[plmnIdx][snssaiIdx];
                    sst = snssai >> 24;       // Trim right 24bits.
                    sd = (snssai << 8) >> 8;  // Trim leftmost 8bits.
                    snssai2 = pAupf->supportedSnssaiGrp[plmnIdx][snssaiIdx] + pAupf->supportedSnssaiGrpLength[plmnIdx][snssaiIdx] - 1;
                    sst2 = snssai2 >> 24;       // Trim right 24bits.
                    sd2 = (snssai2 << 8) >> 8;  // Trim leftmost 8bits.

                    PRINT("       [GrpIdx:%2d] supportedSnssai Range : %8d (sst:%2x, sd:%6x) ~ %8d (sst:%2x, sd:%6x) : GrpLength:%d\n", snssaiIdx,
                        snssai, sst, sd,
                        snssai2, sst2, sd2,
                        pAupf->supportedSnssaiGrpLength[plmnIdx][snssaiIdx] );
                }
            }
        }
    }
    PRINT("+===============================================+\n");
    return GOOD;
}

/**
 *  @brief Get Cfg GNB Supported Slice Information per AUPF
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetSupportedSliceInfoCell(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    if (argc != 2)
    {
        PRINT(
            "Usage : itscp_vccb get cfg gnb supportedSliceInfoCell [cellIdentity] (wrong argument number expected=6, "
            "received=%d)\n",
            argc);
        return GOOD;
    }

    uint16_t plmnIdx = 0, snssaiIdx = 0;
    uint32_t sd = 0, sst = 0, snssai = 0;
    uint32_t sd2 = 0, sst2 = 0, snssai2 = 0;
    uint16_t cellNum = 0, gnbNum = 0;
    uint32_t cellIdentity = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);

    if (cellIdentity >= MAX_CELL_IDENTITY)
    {
        PRINT("Invalid CellIdentity!\n");
        return GOOD;
    }

    PRINT("+===============================================+\n");
    PRINT("| Cell Status                                   +\n");
    PRINT("| - REL_CELL_STATUS_ID      : 0x%08X        +\n", REL_CELL_STATUS_ID);
    PRINT("| - REL_NR_CELL_PLMN_INFO_ID: 0x%08X        +\n", REL_NR_CELL_PLMN_INFO_ID);
    PRINT("+-----------------------------------------------+\n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        cellNum = PGNBINFO[gnbNum].env.cellNum[cellIdentity];

        if (cellNum > MAX_CELL_NUM_ITSCP_VCCB) continue;

        VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
        if (pCell->status != EQUIP) continue;
        if (pCell->cellIdentity != cellIdentity) continue;

        PRINT("+-----------------------------------------------+\n");
        PRINT(" gnbNum:%d cellIdentity:%d tac:%d\n", gnbNum, pCell->cellIdentity, pCell->tac);
        PRINT("+-----------------------------------------------+\n");
        for (plmnIdx = 0; plmnIdx < MIN(pCell->cellPlmn.numOfPLMN, MAX_PLMN_INDEX); plmnIdx++)
        {
            PRINT("    [PLMN: %x(%d)]\n", pCell->cellPlmn.servedPlmn[plmnIdx], pCell->cellPlmn.servedPlmn[plmnIdx]);
            PRINT("     - supportedSnssai Lists(Grp Cnt: %d)\n", pCell->cellPlmn.supportedSnssaiGrpCntPerPlmn[plmnIdx]);

            for (snssaiIdx = 0; snssaiIdx < MIN(pCell->cellPlmn.supportedSnssaiGrpCntPerPlmn[plmnIdx], MAX_SNSSAI_GRP_PER_PLMN_CELL);
                 snssaiIdx++)
            {
                snssai = pCell->cellPlmn.supportedSnssaiGrp[plmnIdx][snssaiIdx],
                sst = snssai >> 24;       // Trim right 24bits.
                sd = (snssai << 8) >> 8;  // Trim leftmost 8bits.
                                          //
                snssai2 = pCell->cellPlmn.supportedSnssaiGrp[plmnIdx][snssaiIdx] + pCell->cellPlmn.supportedSnssaiGrpLength[plmnIdx][snssaiIdx] - 1,
                sst2 = snssai2 >> 24;       // Trim right 24bits.
                sd2 = (snssai2 << 8) >> 8;  // Trim leftmost 8bits.

                PRINT("       [GrpIdx:%2d] supportedSnssai Range : %8d (sst:%2x, sd:%6x) ~ %8d (sst:%2x, sd:%6x) : GrpLength:%d\n", snssaiIdx,
                        snssai, sst, sd,
                        snssai2, sst2, sd2,
                        pCell->cellPlmn.supportedSnssaiGrpLength[plmnIdx][snssaiIdx]);
            }
        }
    }

    PRINT("+===============================================+\n");
    return GOOD;
}

/**
 *  @brief Get Cfg X2 Status Information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetEutraCellInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PLDEutraCellInfo *pEutraCellInfo;
    uint8_t gnbIdx;
    uint32_t endPointX2;
    uint16_t cellId;

    PRINT("+=========================================================================================+\n");
    PRINT("| Eutra Cell Info                                                                         +\n");
    PRINT("| - REL_EUTRA_CELL_INFO_ID: 0x%08X                                                    +\n",
          REL_EUTRA_CELL_INFO_ID);
    PRINT("+-----------------------------------------------------------------------------------------+\n");
    PRINT("|index: [cellId](cellType(F: FDD, T: TDD), earfcnDl, earfcnUl, ebandwidthDl, ebandWidthUl)+\n");
    PRINT("+-----------------------------------------------------------------------------------------+\n");

    for (gnbIdx = 0; gnbIdx < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbIdx++)
    {
        const VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbIdx];

        if (pGnb->status != EQUIP) continue;

        for (endPointX2 = 0; endPointX2 < MAX_ENB_PER_GNB_CU_CP; endPointX2++)
        {
            if (PCFG->pldEutraCellInfo[gnbIdx][endPointX2].status != EQUIP) continue;

            pEutraCellInfo = &PCFG->pldEutraCellInfo[gnbIdx][endPointX2];

            PRINT("pldEutraCellInfo[%d][%d].endPointIdx:%d gnbId: %d status:%d samsungVendorInd:%d\n", gnbIdx,
                  endPointX2, pEutraCellInfo->endPointIdx, pEutraCellInfo->gNBId, pEutraCellInfo->status,
                  pEutraCellInfo->samsungVendorInd);

            for (cellId = 0; cellId < 256; cellId++)
            {
                PRINT("%3d(%s,%d,%d,%d,%d) ", cellId, pEutraCellInfo->cellType[cellId] == ci_DUPLEXTYPE_FDD ? "F" : "T",
                      pEutraCellInfo->earfcnDl[cellId], pEutraCellInfo->earfcnUl[cellId],
                      pEutraCellInfo->ebandwidthDl[cellId], pEutraCellInfo->ebandwidthUl[cellId]);
                if (cellId % EUTRA_CELL_PRINT_16_COL == EUTRA_CELL_PRINT_16_COL - 1)  // print 16 columns in a row
                {
                    PRINT("\n");
                }
            }
            PRINT("+-----------------------------------------------------------------------------------------+\n");
        }
    }
    PRINT("+=========================================================================================+\n");

    return GOOD;
}

/**
 *  @brief Get Carrier Aggregation Information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbCarrierAggregationInfo(int32_t argc, char *argv[])
{
    int idx = 0;
    (void)argc;
    (void)argv;
    PRINT("+===============================================================================================+\n");
    PRINT("| Carrier Aggregation Info                                                                      |\n");
    PRINT("+===============================================================================================+\n");
    PRINT("| Operation Mode per nr-band :                                                                  |\n");
    PRINT("+===============================================+===============================================+\n");
    // Multi-gNB
    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    for (idx = 0; idx < MAX_NUM_NR_BAND; idx++)
    {
        if (0 == (idx % 16)) PRINT("| %04d..", idx + 1);
        {
            // Multi-gNB
            PRINT(" %d", pGnb->carrierAggregationInfo.bandOperationMode[idx].caOperationMode);
        }
        if (15 == (idx % 16)) PRINT(" ..%04d ", idx + 1);
        if (31 == (idx % 32)) PRINT("|\n");
    }
    // Multi-gNB
    PRINT("+-----------------------------------------------------------------------------------------------+\n");
    PRINT(" PlmnInfoCheck : %s \n", pGnb->carrierAggregationInfo.plmnInfoCheck ? "true" : "false");
    PRINT(" AllowDssFreqScell : %s \n", pGnb->carrierAggregationInfo.allowDssFreqScell ? "true" : "false");
    PRINT(" A6UeTxpowerEnhancement : %s \n", pGnb->carrierAggregationInfo.a6UeTxpowerEnhancement ? "true" : "false");
    PRINT(" saCellCheckFlag : %s \n", pGnb->carrierAggregationInfo.saCellCheckFlag ? "true" : "false");
    PRINT(" interGnbCaSupportFlag : %s \n", pGnb->carrierAggregationInfo.interGnbCaSupportFlag ? "true" : "false");
    PRINT(" releaseCaA4ForVoNR : %s \n", pGnb->carrierAggregationInfo.releaseCaA4ForVoNR ? "true" : "false");
    PRINT(" noNeedToDetectInvisibleScell : %s \n", pGnb->carrierAggregationInfo.noNeedToDetectInvisibleScell ? "true" : "false");
    PRINT(" caOnLtmUsage : %s \n", pGnb->carrierAggregationInfo.caOnLtmUsage ? "CI_use" : "CI_no_use");

    uint8_t nrCaControlIndex = 0, qosClassIdx = 0, bandIndicatorIdx = 0, sliceIdIdx = 0, allowedScellBandIdx = 0, plmnIndicatorIdx = 0, plmnInd = 0, SpidRfspIndicatorIdx = 0;
    for (nrCaControlIndex = 0; nrCaControlIndex < MAX_NR_CA_CONTROL_ENTRIES; ++nrCaControlIndex)
    {
        nrCaControl_type *ptNrCaControl = &pGnb->carrierAggregationInfo.nrCaControlEntries[nrCaControlIndex];
        if (TRUE != ptNrCaControl->caIndexUsage)
        {
            continue;
        }
        PRINT(" CaControl Idx(%d): caUsage(%d), ulCaUsage(%d), caIndexPriority(%d), ueRatType( %s ), qosClassIndicator( %s )[ ",
                nrCaControlIndex, ptNrCaControl->operation.caUsage, ptNrCaControl->operation.ulCaUsage, ptNrCaControl->caIndexPriority,
                (ueRat_AnyUe == ptNrCaControl->condition.ueRatType ? "any-ue" : (ueRat_NsaUe == ptNrCaControl->condition.ueRatType ? "nsa-ue" : "sa-ue")),
                ptNrCaControl->condition.qosClassIndicatorUsage ? "used" : "not-used");
        for (qosClassIdx = 0;
             qosClassIdx < MIN(ptNrCaControl->condition.noOfQosClassIndicator, VCCB_ARRAY_COUNT(ptNrCaControl->condition.qosClassIndicator));
             ++qosClassIdx)        {
            PRINT("%d ",ptNrCaControl->condition.qosClassIndicator[qosClassIdx]);
        }
        PRINT("], BandIndicatorNr( %s )[ ", ptNrCaControl->condition.bandIndicatorNrUsage ? "used" : "not-used");
        for (bandIndicatorIdx = 0;
             bandIndicatorIdx < MIN(ptNrCaControl->condition.noOfBandIndicatorNr, VCCB_ARRAY_COUNT(ptNrCaControl->condition.bandIndicatorNr));
             ++bandIndicatorIdx)
        {
            PRINT("%d ",ptNrCaControl->condition.bandIndicatorNr[bandIndicatorIdx]);
        }
        PRINT("], AllowedScellBand( %s )[ ", ptNrCaControl->operation.allowedScellBandListUsage ? "used" : "not-used");
        for (allowedScellBandIdx = 0;
             allowedScellBandIdx < MIN(ptNrCaControl->operation.noOfAllowedBandList, VCCB_ARRAY_COUNT(ptNrCaControl->operation.allowedScellBandList));
             ++allowedScellBandIdx)
        {
            PRINT("%d ",ptNrCaControl->operation.allowedScellBandList[allowedScellBandIdx]);
        }
        PRINT("] PlmnIndicator( %s )[ ", ptNrCaControl->condition.plmnIndicatorUsage ? "used" : "not-used");
        for (plmnIndicatorIdx = 0;
             plmnIndicatorIdx < MAX_PLMN_INDEX;
             ++plmnIndicatorIdx)
        {
            plmnInd = GETBIT_U8(ptNrCaControl->condition.plmnIndicatorList, plmnIndicatorIdx);
            if (plmnInd)
            {
                PRINT("%d ",plmnIndicatorIdx);
            }
        }
        PRINT("]\n");
        PRINT(" SliceIdEntries( %s )[\n", ptNrCaControl->condition.sliceIdIndicatorUsage ? "used" : "not-used");
        for (sliceIdIdx = 0; sliceIdIdx < MAX_CA_NUM_SLICES; ++sliceIdIdx)
        {
            const SliceSupportedInfo_type *sliceId = &ptNrCaControl->condition.sliceIdEntries[sliceIdIdx];
            if (CI_no_use == sliceId->status) continue;

            PRINT("    idx(%2d) : sst(%d), sd(%d)\n", sliceIdIdx, sliceId->sst, sliceId->sd);
        }
        PRINT("]\n");
        PRINT(" SpidRfspIndicator( %s )[\n", ptNrCaControl->condition.spidRfspIndicatorUsage ? "used" : "not-used");
        for (SpidRfspIndicatorIdx = 0; SpidRfspIndicatorIdx < MIN(ptNrCaControl->condition.noOfSpidRfspIndicator, MAX_CA_CONTROL_SPID_RFSP_INDICATORS); ++SpidRfspIndicatorIdx)
        {
            PRINT("%d ",ptNrCaControl->condition.spidRfspIndicator[SpidRfspIndicatorIdx]);
        }
        PRINT("]\n");
    }

    for (idx = 0; idx < MAX_NUM_NR_BAND; idx++)
    {
        operationMode_type *ptOperationMode = &pGnb->carrierAggregationInfo.bandOperationMode[idx];
        if (0 == ptOperationMode->noOfBlockBandsSa && 0 == ptOperationMode->noOfBlockBandsNsa)
        {
            continue;
        }
        PRINT(" Pcell band(%d) blocked bands: SA[ ", idx + 1);
        for (bandIndicatorIdx = 0;
             bandIndicatorIdx < MIN(ptOperationMode->noOfBlockBandsSa, VCCB_ARRAY_COUNT(ptOperationMode->blockBandsSa));
             ++bandIndicatorIdx)
        {
            PRINT("%u ", ptOperationMode->blockBandsSa[bandIndicatorIdx]);
        }
        PRINT("] NSA[ ");
        for (bandIndicatorIdx = 0;
             bandIndicatorIdx < MIN(ptOperationMode->noOfBlockBandsNsa, VCCB_ARRAY_COUNT(ptOperationMode->blockBandsNsa));
             ++bandIndicatorIdx)
        {
            PRINT("%u ", ptOperationMode->blockBandsNsa[bandIndicatorIdx]);
        }
        PRINT("]\n");
    }

    PRINT("+-----------------------------------------------------------------------------------------------+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+===============================================+===============================================+\n");

    return GOOD;
}

/**
 *  @brief Get NR CA Control Sort Index
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbNrCaControlSortIndex(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("< USAGE > get cfg gnb nrCaControlSortIdx [gnbNum]\n");
    };
    if (argv == NULL || argc != 2)
    {
        SHOW_USAGE();
        return GOOD;
    }

    uint16_t gnbNum = StrUtil::itscp_strtoul<uint16_t>(argv[1]);
    if (gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
    {
        PRINT("Invalid gnb number\n");
        SHOW_USAGE();
        return GOOD;
    }

    VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];

    PRINT("+========================================+\n");
    PRINT("| NR CA Control Sort Index (gNBNum = %2d) |\n", gnbNum);
    PRINT("+========================================+\n");
    PRINT("| SortIdx | NrCaControlIndex |   usage   |\n");
    PRINT("+----------------------------------------+\n");

    for (uint8_t idx = 0; idx < MAX_NR_CA_CONTROL_ENTRIES; idx++)
    {
        uint8_t nrCaControlIdx = pGnb->carrierAggregationInfo.nrCaControlSortIdx[idx];

        if (nrCaControlIdx >= MAX_NR_CA_CONTROL_ENTRIES) continue;

        PRINT("|   %2d    |        %2d        |     %d     |\n", idx, nrCaControlIdx, pGnb->carrierAggregationInfo.nrCaControlEntries[nrCaControlIdx].caIndexUsage);
    }
    PRINT("+========================================+\n");

    return GOOD;
}

/**
 *  @brief Print all fields from VccbGnbInfo_type::multiCarrierOperation_s
 *  @param[in] rGnb
 *  @return GOOD
 *  @exception N/A
 */
void PrintMultiCarrierOperationInfo(const VccbGnbInfo_type &rGnb)
{
    PRINT(" Capability Aware Carrier Change:\n     PCC: %s\n     SCC: %s\n",
        (rGnb.multiCarrierOperation.capabilityAwareCarrierChange ? "enabled" : "disabled"),
        (rGnb.multiCarrierOperation.sccChange ? "enabled" : "disabled"));
    PRINT(" Full Measure Based Pcc Change: %s\n", (rGnb.multiCarrierOperation.fullMeasureBasedPccChange ? "enabled" : "disabled"));
    PRINT(" Mr gathering timer: %dms\n", rGnb.multiCarrierOperation.mrGatheringTimer);
    PRINT(" SCC mr gathering timer: %dms\n", rGnb.multiCarrierOperation.sccMrGatheringTimer);
    PRINT(" SCC mr reactivation timer: %dms\n", rGnb.multiCarrierOperation.sccMeasReactivationTimer);
    PRINT(" Meas reactivation timer: %dms\n", rGnb.multiCarrierOperation.measReactivationTimer);
    PRINT(" Effective BW option: %s\n",
        (rGnb.multiCarrierOperation.effectiveBandwidthOption == EffectiveBWOpt_disabled
            ? "disabled"
            : (rGnb.multiCarrierOperation.effectiveBandwidthOption == EffectiveBWOpt_PrbUsage ? "PrbUsage"
                                                                                                : ("unknown"))));
    PRINT(" Multiple Channel BW Usage: %s\n", (rGnb.multiCarrierOperation.multipleChannelBwUsage ? "enabled" : "disabled"));
    PRINT(" Inter-RAT PCC change: %s\n", (rGnb.multiCarrierOperation.interRatPccChange ? "enabled" : "disabled"));
    PRINT(" Inter-RAT PCC timer: %dms\n", rGnb.multiCarrierOperation.interRatPccChangeTimer);
    PRINT(" MultiRatCarrierChange: %s\n", (rGnb.multiCarrierOperation.multiRatCarrierChange ? "enabled" : "disabled"));
    PRINT(" Traffic Check Inter RAT Pcc Change: %s\n", (rGnb.multiCarrierOperation.trafficCheckInterRatPccChange ? "enabled" : "disabled"));
    PRINT(" MFBI Check: %s\n", (rGnb.multiCarrierOperation.mfbiCheck ? "enabled" : "disabled"));
    PRINT(" Traffic Check Multi Rat Carrier Change: %s\n", (rGnb.multiCarrierOperation.mrsTrafficCheckFlag ? "enabled" : "disabled"));
    PRINT(" Uplink Traffic Check Inter Rat Pcc Change: %s\n", (rGnb.multiCarrierOperation.ulTrafficCheckInterRatPccChange ? "enabled" : "disabled"));
    PRINT(" Multi Rat Carrier Change MrGathering Timer: %dms\n", rGnb.multiCarrierOperation.mrsMrGatheringTimer);
    PRINT(" Effective Bandwidth Offset Lte: %d\n", rGnb.multiCarrierOperation.effectiveBandwidthOffsetLte);
    PRINT(" Effective Bandwidth Offset Endc: %d\n", rGnb.multiCarrierOperation.effectiveBandwidthOffsetEndc);
    PRINT(" Effective Bandwidth Offset PCC: %d\n", rGnb.multiCarrierOperation.effectiveBandwidthOffsetPcc);
    PRINT(" Slice Based Inter RAT PCC Change: %s\n", rGnb.multiCarrierOperation.sliceIdCheckInterRatPccChange ? "enabled" : "disabled");
    PRINT(" Slice Id Entries: ");
    uint8_t index = 0;
    size_t sliceIdEntriesLength = VCCB_ARRAY_COUNT(rGnb.multiCarrierOperation.sliceIdEntries);
    for(; index < sliceIdEntriesLength; ++index)
    {
        if (rGnb.multiCarrierOperation.sliceIdEntries[index].status == CI_use)
        {
            PRINT("[Idx: %d, SST: %u, SD: %u, Status: %u] ",
                    index, rGnb.multiCarrierOperation.sliceIdEntries[index].sst,
                    rGnb.multiCarrierOperation.sliceIdEntries[index].sd,
                    rGnb.multiCarrierOperation.sliceIdEntries[index].status);
        }
    }
    PRINT("\n");
    PRINT(" PSCell Selection Method:\n    ENDC: %u\n    NRDC: %u\n",
        rGnb.cfg.pscellSelectionMethod, rGnb.cfg.nrdc.pscellSelectionMethod);

    for (auto &profile: rGnb.multiCarrierOperationConfig.profileEntry)
    {
        if (!profile.usage)
        {
            continue;
        }
        PRINT(" Profile %s\n", profile.name);
        for (auto &config: profile.configEntry)
        {
            if (!config.configUsage)
            {
                continue;
            }
            PRINT(" Config Priority: %d\n", config.configPriority);
            PRINT(" Config RFSP Usage: %d\n", config.condition.rfspUsage);
            if (config.condition.rfspUsage)
            {
                PRINT(" No of RFSP: %d\n", config.condition.noOfRfsp);
                for (uint8_t idx = 0; idx < config.condition.noOfRfsp; idx++)
                {
                    PRINT(" [%d] = %d", idx, config.condition.rfsp[idx]);
                    if ((idx + 1) < config.condition.noOfRfsp)
                    {
                        PRINT(",");
                    }
                }
                PRINT("\n");
            }

            PRINT(" Config Service Group Usage: %d\n", config.condition.serviceGroupUsage);
            if (config.condition.serviceGroupUsage)
            {
                PRINT(" No of Service Group Index: %d\n", config.condition.noOfServiceGroupIndex);
                for (uint8_t idx = 0; idx < config.condition.noOfServiceGroupIndex; idx++)
                {
                    PRINT(" [%d] = %d", idx, config.condition.serviceGroupIndex[idx]);
                    if ((idx + 1) < config.condition.noOfServiceGroupIndex)
                    {
                        PRINT(",");
                    }
                }
                PRINT("\n");
            }

            PRINT("  Irat Pcc Chg Usage: %d\n", config.operation.iratPccChgUsage);
            PRINT("  Ul Aware Threshold Usg For Irat Pcc Chg: %d\n", config.operation.ulAwareThresholdUsageForIratPccChg);
            PRINT("  Ul Traffic Threshold For Irat Pcc Chg: %d\n", config.operation.ulTrafficThresholdForIratPccChg);
            PRINT("  Ul Bw Threshold For Irat Pcc Chg: %d\n", config.operation.ulBwThresholdForIratPccChg);
            PRINT("  Dl Aware Threshold Usg For Irat Pcc Chg: %d\n", config.operation.dlAwareThresholdUsageForIratPccChg);
            PRINT("  Dl Traffic Threshold For Irat Pcc Chg: %d\n", config.operation.dlTrafficThresholdForIratPccChg);
            PRINT("  Dl Bw Threshold For Irat Pcc Chg: %d\n", config.operation.dlBwThresholdForIratPccChg);
        }
    }
}

/**
 *  @brief Get Multi Carrier Operation Information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbMultiCarrierOperationInfo(int32_t argc, char *argv[])
{
    PRINT("+===============================================================================================+\n");
    PRINT("| Multi Carrier Operation Info                                                                  |\n");
    PRINT("+===============================================================================================+\n");
    // Multi-gNB
    uint16_t startIdx = 0;
    uint16_t endIdx = MAX_GNB_PER_SYS_ITSCP_VCCB;
    if(argc > 1)
    {
        uint16_t chosenNum = StrUtil::itscp_strtoul<uint16_t>(argv[1]);
        startIdx = chosenNum;
        endIdx = static_cast<uint16_t>(chosenNum + 1);
        if (endIdx > MAX_GNB_PER_SYS_ITSCP_VCCB) 
        {
            PRINT("Input gnbNum is out of range (0..%u)!\n",MAX_GNB_PER_SYS_ITSCP_VCCB - 1);
            return GOOD;
        }
    }
                                                              
    for(; startIdx < endIdx; startIdx++)
    {
        const VccbGnbInfo_type &rGnb = PGNBINFO[startIdx];
        if (rGnb.status != EQUIP) continue;
        PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", startIdx, rGnb.globalGnbId.gnbId.id);
        PrintMultiCarrierOperationInfo(rGnb);
        PRINT("+===============================================+===============================================+\n");
    }
    return GOOD;
}

/**
 *  @brief Get Dynamic Spectrum Sharing Information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbDynamicSpectrumSharingInfo(int32_t argc, char *argv[])
{
    int idx = 0;
    (void)argc;
    (void)argv;
    PRINT("+===============================================================================================+\n");
    PRINT("| Dynamic Spectrum Sharing Info                                                                 |\n");
    PRINT("+===============================================================================================+\n");
    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("+============================== GNB_NUM[%4d] GNB_ID[%10u] ===============================+\n", gnbNum,
          pGnb->globalGnbId.gnbId.id);
    const char *dssConfiguration[] = {"DISABLED", "ENABLED"};
    int numDssBands = 0;
    for (idx = 0; idx < MAX_DSS_BANDS_ARR_SIZE; idx++)
    {
        uint8_t bandsBitArr = pGnb->dssConfiguration.dssBands[idx];
        while (bandsBitArr)
        {
            numDssBands += (bandsBitArr & 0x01);
            bandsBitArr = static_cast<uint8_t>(bandsBitArr >> 1);
        }
    }
    PRINT("| DSS configuration: %10s, bands used: %4d                                               |\n",
          dssConfiguration[pGnb->dssConfiguration.dssUESupportControl ? 1 : 0], numDssBands);
    PRINT("| Bands: ");
    const int lineBegin = 8;
    const int lineEnd = 95;
    int lineLen = lineBegin;
    char formatBuff[20];
    for (idx = 0; idx < MAX_DSS_BANDS_ARR_SIZE; idx++)
    {
        // (((dssBands[bandNumber-1) / 8] >> ((bandNumber-1) % 8)) & 0xFE)
        int bitIdx = 0;
        int bandNumber;
        int curBandIdx = -1;
        for (bitIdx = 0; bitIdx < 8; bitIdx++)
        {
            if ((pGnb->dssConfiguration.dssBands[idx] >> bitIdx) & 0x01)
            {
                ++curBandIdx;
                // DSS band is set
                if (lineLen > lineBegin)
                {
                    PRINT(", ");
                    lineLen += 2;
                }
                bandNumber = idx * 8 + bitIdx + 1;
                // just for nice line formatting calculate number length as string
                int tmp = bandNumber;
                int numLen = 1;
                while (tmp / 10)
                {
                    ++numLen;
                    tmp /= 10;
                }
                if (lineLen + numLen + ((curBandIdx + 1) < numDssBands ? 2 : 0) >= lineEnd)
                {
                    snprintf(formatBuff, sizeof(formatBuff), "%%%ds|\n|%%%ds", lineEnd - lineLen, lineBegin);
                    PRINT(formatBuff, "", "");
                    lineLen = lineBegin;
                }
                PRINT("%d", bandNumber);
                lineLen += numLen;
            }
        }
    }
    snprintf(formatBuff, sizeof(formatBuff), "%%%ds|\n", lineEnd - lineLen);
    PRINT(formatBuff, " ");

    PRINT("+-----------------------------------------------------------------------------------------------+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+===============================================+===============================================+\n");

    return GOOD;
}

