/**
 *  @brief Get GnbCuUpInfo
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbGnbCuUpInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint16_t loop, loop2, loop3;
    AupfStatusInfo_type *pGnbCuUp = NULL;
    uint16_t gnbNum = 0;
    uint32_t sd = 0, sst = 0, snssai = 0;
    uint32_t sd2 = 0, sst2 = 0, snssai2 = 0;

    PRINT("+========================================================================+\n");
    PRINT("| gnbCuUpInfo                                                            |\n");
    PRINT("+------------------------------------------------------------------------+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("====================  GNB_NUM[%d] GNB_ID[%10u] ======================\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    PRINT("AUPF selection algorithm:\n\tNSA - %s\n\tSA - %s\n\tNRDC-SN - %s\n",
          getAUPFSelection(pGnb->aupf.aupfSelectionModeENDC), getAUPFSelection(pGnb->aupf.aupfSelectionModeSA),
          getAUPFSelection(pGnb->aupf.aupfSelectionModeNRDCSN));
    PRINT("AMBR distribution among serving AUPFs:\n\tNSA - %s\n\tSA - %s\n",
          getENDcAUPFDistribution(pGnb->aupf.ambrAupfDistributionENDC),
          getAUPFDistribution(pGnb->aupf.ambrAupfDistributionSA));
    PRINT("allowOverloadedUpForHpaMpsBearers: %u\n\n", pGnb->aupf.allowOverloadedUpForHpaMpsBearers);
    PRINT(" endPoint |        gnbCuUpId | overload | capa | CN      | service | sw\n");
    PRINT("      Idx |                  | Status   | city | support | State   | ver\n");
    PRINT("+------------------------------------------------------------------------+\n");
    for (loop = 0; loop < MAX_GNB_CU_UP_PER_GNB_CU_CP; loop++)
    {
        pGnbCuUp = &pGnb->aupf.gnbCuUp[loop];
        if (!pGnbCuUp->status)
        {
            continue;
        }

        PRINT(" %8u | %16lu | %8u | %4u | %7s | %7d | %s\n", loop, pGnbCuUp->aupfId, pGnbCuUp->overloadStatus,
              pGnbCuUp->capacity, getCNSupportType(pGnbCuUp->cnSupport), pGnbCuUp->serviceState, pGnbCuUp->swVersion.raw.text);
        PRINT("Supported PLMNs:");
        for (loop2 = 0; loop2 < pGnbCuUp->plmnCnt; loop2++)
        {
            PRINT("\nPLMN #%d id:%06x", loop2, pGnbCuUp->plmn[loop2]);
            if (pGnbCuUp->eutranQciPerPlmnCnt[loop2] > 0)
            {
                PRINT(", Supported QCIs:");
                for (loop3 = 0; loop3 < pGnbCuUp->eutranQciPerPlmnCnt[loop2]; loop3++)
                {
                    PRINT(" %d", pGnbCuUp->eutranQci[loop2][loop3]);
                }
            }
            if (pGnbCuUp->supportedSnssaiGrpCntPerPlmn[loop2] > 0)
            {
                PRINT(", Supported NSSAI(Grp Cnt: %d) : \n", pGnbCuUp->supportedSnssaiGrpCntPerPlmn[loop2]);
                for (loop3 = 0; loop3 < MIN(pGnbCuUp->supportedSnssaiGrpCntPerPlmn[loop2], MAX_SNSSAI_GRP_PER_PLMN_AUPF); loop3++)
                {
                    snssai = pGnbCuUp->supportedSnssaiGrp[loop2][loop3];
                    sst = snssai >> 24;       // Trim right 24bits.
                    sd = (snssai << 8) >> 8;  // Trim leftmost 8bits.
                                            //
                    snssai2 = pGnbCuUp->supportedSnssaiGrp[loop2][loop3] + pGnbCuUp->supportedSnssaiGrpLength[loop2][loop3] - 1,
                    sst2 = snssai2 >> 24;       // Trim right 24bits.
                    sd2 = (snssai2 << 8) >> 8;  // Trim leftmost 8bits.


                    PRINT("   - [%2d] %8d(sst: %3d, sd: %8d) ~ %8d(sst: %3d, sd: %9d) - Length : %d\n", loop3,
                            snssai, sst, sd,
                            snssai2, sst2, sd2,
                            pGnbCuUp->supportedSnssaiGrpLength[loop2][loop3] );
                }
            }
        }
        PRINT("\n+------------------------------------------------------------------------+\n");
    }

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("\n+========================================================================+\n");

    return GOOD;
}

/**
 *  @brief get IMSI trace target UE information
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetImsiTraceUeInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint16_t loop, loop2;
    int32_t strLen = 0;
    char imsiPrintBuf[16];
    char zimsiPrintBuf[40];
    imsiPrintBuf[0] = '\0';
    zimsiPrintBuf[0] = '\0';

    uint32_t buffSize = 0;
#define IMSI_PRINT_BUF  imsiPrintBuf + strLen
#define ZIMSI_PRINT_BUF zimsiPrintBuf + strLen

    PRINT("+==========================================================================+\n");
    PRINT("| ImsiTraceUeInfo                                                          |\n");
    PRINT("+--------------------------------------------------------------------------+\n");
    PRINT("+======== PLDImsiTrace ====================================================+\n");
    PRINT(" imsi | IMSI | IMSI               | ZIMSI| ZIMSI                           |\n");
    PRINT("  Idx | Len  |                    | Len  |                                 |\n");
    PRINT("+--------------------------------------------------------------------------+\n");

    for (loop = 0; loop < MIN(MAX_TRACE_IMSI, PDBG->imsiTraceInfo.numOfImsi); loop++)
    {
        memset(imsiPrintBuf, 0x00, sizeof(imsiPrintBuf));
        memset(zimsiPrintBuf, 0x00, sizeof(zimsiPrintBuf));
        imsiPrintBuf[0] = '\0';
        zimsiPrintBuf[0] = '\0';
        strLen = 0;

        // IMSI
        buffSize = sizeof(imsiPrintBuf);
        for (loop2 = 0; loop2 < MIN(MAX_IMSI_DIGIT, PDBG->imsiTraceInfo.IMSILen[loop]); loop2++)
        {
            strLen += snprintf(IMSI_PRINT_BUF, buffSize - (uint32_t)strLen, "%X", PDBG->imsiTraceInfo.IMSI[loop][loop2]);
        }

        // ZIMSI
        buffSize = sizeof(zimsiPrintBuf);
        strLen = 0;
        for (loop2 = 0; loop2 < MIN(MAX_IMSI_BYTE, PDBG->imsiTraceInfo.ZIMSILen[loop]); loop2++)
        {
            strLen += snprintf(ZIMSI_PRINT_BUF, buffSize - (uint32_t)strLen, "[%02X]", PDBG->imsiTraceInfo.ZIMSI[loop][loop2]);
        }

        PRINT(" %4u | %4d | %18s | %4d | %24s ", PDBG->imsiTraceInfo.imsiIdx[loop], PDBG->imsiTraceInfo.IMSILen[loop],
              imsiPrintBuf, PDBG->imsiTraceInfo.ZIMSILen[loop], zimsiPrintBuf);
        PRINT("\n");
    }
    PRINT("+--------------------------------------------------------------------------+\n");
    PRINT("+==========================================================================+\n");

    return GOOD;
}

