/**
 *  @brief get cell status history
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetDbgLogCellStatusHist(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("< USAGE > get dbg getCellStatusHist [cellNum]\n");
    };
    if (argv == NULL || argc != 2)
    {
        SHOW_USAGE();
        return GOOD;
    }

    int32_t startIdx = 0;
    const uint16_t cellNum = StrUtil::itscp_strtoul<uint16_t>(argv[1]);

    const VccbDbgCellStatusHistory_type *pHist = GetStatusHistDB(cellNum);
    if (pHist == NULL) return GOOD;

    if (pHist->curIdx == -1) return GOOD;  // no history

    if (pHist->curIdx == MAX_HISTORY_NUM - 1)
    {
        startIdx = 0;
    }
    else if (pHist->cycleFlag)  // not the first cycle, start from the middle
    {
        startIdx = pHist->curIdx + 1;
    }

    int32_t i = 0, count = 0;

    PRINT(
        "+========================================================================================================="
        "===============================================+\n");
    PRINT(
        "| Cell Status History Info (cellNum[%5d])                                                                 "
        "                                             |\n",
        cellNum);
    PRINT(
        "+---------------------------------------------------------------------------------------------------------"
        "-----------------------------------------------+\n");
    PRINT(
        " [idx] pldIdx | status |  pld  |         cause          |   gNBId    | gnbNum | cellId |  serviceState  | "
        "epF1 | cell |        updateTime                |\n");
    PRINT(
        "              |        | State |                        |            |        |        | pldCell/pldGnb | "
        "     | InDu |                                  |\n");
    PRINT(
        "+---------------------------------------------------------------------------------------------------------"
        "-----------------------------------------------+\n");

    for (i = startIdx, count = 1; count <= MAX_HISTORY_NUM; i++, count++)
    {
        if (i == MAX_HISTORY_NUM) i = 0;

        if (0 == pHist->update[i].updateTime) continue;

        const VccbDbgUpdateCellStatusHistory_type *pUpdate = &pHist->update[i];

        char updateTime[64] = {0, };
        getTimeStringWithTimezone(pUpdate->updateTime, updateTime, sizeof(updateTime));

        PRINT(" [%3d] %6d | %6s | %5s | %22s | %10u | %6d | %6d | %7s/%6s | %4d | %4s | %s", count, pUpdate->pldCellIdx,
              pUpdate->status == EQUIP ? "EQ" : "NEQ", pUpdate->pldState == EQUIP ? "EQ" : "NEQ",
              getCellStatusHistoryCauseType(static_cast<enumCellStatusHistoryCause_type>(pUpdate->cause)), pUpdate->gNBId, pUpdate->gnbNum, pUpdate->cellId,
              pUpdate->pldCellSrvState == CELL_INS ? "INS" : "OOS", pUpdate->pldGnbSrvState == EQUIP ? "EQ" : "NEQ",
              pUpdate->endPointF1Index, pUpdate->cellInDuStatus == EQUIP ? "EQ" : "NEQ", updateTime);
    }
    PRINT(
        "+========================================================================================================="
        "===============================================+\n");
    return GOOD;
}

int GetDbgLogHasDumpHist(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    VccbDbgHasDumpHistory_type *pHist = NULL;
    VccbDbgUpdateHasDumpHistory_type *pUpdate = NULL;

    int32_t i;
    uint16_t count;
    int32_t startIdx = 0;
    char timeString[128] = {
        0,
    };

    PRINT("+================================================================+\n");
    PRINT("| HAS Dump History                                               |\n");
    PRINT("+----------------------------------------------------------------+\n");
    PRINT(" [idx|     updateTime      | callId | dumpSize(byte)\n");
    PRINT("+----------------------------------------------------------------+\n");

    pHist = &PDBG->hasDumpHist;

    if (pHist->curIdx == -1)  // no history
    {
        PRINT("+================================================================+\n");
        return GOOD;
    }
    else if (pHist->curIdx == MAX_HISTORY_NUM - 1)
        startIdx = 0;
    else if (pHist->cycleFlag)
        startIdx = pHist->curIdx + 1;  // not the first cycle, start from the middle

    for (i = startIdx, count = 1; count <= MAX_HISTORY_NUM; i++, count++)
    {
        if (i == MAX_HISTORY_NUM) i = 0;

        if (0 == PDBG->hasDumpHist.update[i].updateTime.tv_sec) continue;

        pUpdate = &pHist->update[i];

        struct tm sTime;
        localtime_r((time_t *)&pUpdate->updateTime.tv_sec, &sTime);
        snprintf(timeString, 128, "%02d%02d%02d %02d:%02d:%02d.%03u", sTime.tm_year % 100, sTime.tm_mon + 1,
                 sTime.tm_mday, sTime.tm_hour, sTime.tm_min, sTime.tm_sec,
                 (unsigned int)pUpdate->updateTime.tv_usec / 1000);

        if (pUpdate->callId >= 0)
        {
            PRINT(" [%3d| %s | %6u | %lu\n", count, timeString, pUpdate->callId, pUpdate->dumpSize);
        }
        else
        {
            if (pUpdate->dumpSize > 0)
            {
                PRINT(" [%3d| %s |    -   | %lu(No Call Backup because all call not use)\n", count, timeString,
                      pUpdate->dumpSize);
            }
            else
            {
                PRINT(" [%3d| %s |    -   | Partial Dump ERROR\n", count, timeString);
            }
        }
    }

    PRINT("+================================================================+\n");
    return GOOD;
}

