int GetDbgLogMsgQueueFullHist(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint8_t threadId;
    VccbDbgMsgQueueMapHistory_type *pHist = NULL;

    PRINT("+===============================================================================================================+\n");
    PRINT("| Message Queue Full History                                                                                    |\n");
    PRINT("+---------------------------------------------------------------------------------------------------------------+\n");

    for (threadId = 0; threadId < MAX_CALL_THREAD_NUM_ITSCP_VCCB; threadId++)
    {
        pHist = &PDBG->msgQueueMapHist[threadId];

        if (pHist->numOfHistoryOfUeQueueFull > 0)
        {
            uint16_t maxUeQueueFullHistory = MIN(pHist->numOfHistoryOfUeQueueFull, MAX_LOG_HIST_UE_MSG_QUEUEING_INFO);
            for (uint16_t histIdx = 0; histIdx < maxUeQueueFullHistory; histIdx++)
            {
                struct tm sTime;
                localtime_r((time_t *)&pHist->ueMsgHistInfo[histIdx].loggingTime.tv_sec, &sTime);
                PRINT(" Thread[%02d][%u]: [%02d%02d%02d %02d:%02d:%02d.%06d] callId=%u,callType=%u,stateCmd=%u/%s,state=%u/%s,reqMsgId=%u\n",
                    threadId, histIdx,
                    sTime.tm_year % 100, sTime.tm_mon + 1, sTime.tm_mday,
                    sTime.tm_hour, sTime.tm_min, sTime.tm_sec, (unsigned int)pHist->ueMsgHistInfo[histIdx].loggingTime.tv_usec,
                    pHist->ueMsgHistInfo[histIdx].callId, pHist->ueMsgHistInfo[histIdx].callType,
                    pHist->ueMsgHistInfo[histIdx].stateCmd, getStateCmdName(pHist->ueMsgHistInfo[histIdx].stateCmd),
                    pHist->ueMsgHistInfo[histIdx].callState, GET_STATE_NAME(pHist->ueMsgHistInfo[histIdx].callState),
                    pHist->ueMsgHistInfo[histIdx].requestMessageId);


                uint16_t maxMsgQueueingCnt = MIN(pHist->ueMsgHistInfo[histIdx].numQueueingMsg, MAX_MSG_QUEUEING_COUNT_PER_UE);
                for (uint16_t queueIdx = 0; queueIdx < maxMsgQueueingCnt; queueIdx++)
                {
                    PRINT("            - QueueingMsg[%u]: msgId=%u/%s, action=%u/%s\n",
                    queueIdx,
                    pHist->ueMsgHistInfo[histIdx].queueingMsgId[queueIdx],
                    FnITSCP_GetStrMsgId(pHist->ueMsgHistInfo[histIdx].queueingMsgId[queueIdx]),
                    pHist->ueMsgHistInfo[histIdx].queueingAction[queueIdx],
                    getQueueingActionStr(enqueuedAction(pHist->ueMsgHistInfo[histIdx].queueingAction[queueIdx])));
                }
            }
        }
        else
        {
            PRINT(" UE Queue Full History does not exist for thread #%u.\n", threadId);
        }
    }
    PRINT("+===============================================================================================================+\n");

    return GOOD;
}

const char *getPldRelationName(int relId)
{
    switch (relId)
    {
        case 0x0077F006:
            return "REL_DU_STATUS_ID";
        case 0x0077F005:
            return "REL_AUPF_STATUS_ID";
        case 0x0077F008:
            return "REL_AMF_STATUS_ID";
        case 0x0077F004:
            return "REL_AMF_TNL_STATUS_ID";
        case 0x0072F00D:
            return "REL_AMF_TNL_SCTP_STATE_ID";
        case 0x0077F007:
            return "REL_CELL_STATUS_ID";
        case 0x0077F00E:
            return "REL_GNB_BARRING_INFO_ID";
        case 0x0072F006:
            return "REL_IMSI_TRACE_ID";
        case 0x007AE004: // VNF/PNF
        case 0x007AF004: // CNF
            return "REL_CPU_UTIL_ID";
        case 0x007AE001: // VNF/PNF
        case 0x007AF001: // CNF
            return "REL_CPU_UTIL_EXT_ID";
        case 0x0077F00A:
            return "REL_TRACE_STATUS_ID";
        case 0x0077F002:
            return "REL_CPC_USAGE_STATE_ID";
        case 0x0077F00B:
            return "REL_CELL_TRACE_STATUS_ID";
        case 0x0077F00C:
            return "REL_EUTRA_CELL_INFO_ID";
        case 0x0072F005:
            return "REL_XN_GNB_STATUS_ID";
        case 0x0077F00F:
            return "REL_GNB_XN_TAI_INFO_ID";
        case 0x0077F00D:
            return "REL_GNB_CALL_STATE_ID";
        case 0x0077F01D:
            return "REL_CBRS_CELL_CARRIER_INFO_ID";
        case 0x0072F017:
            return "REL_NR_CELL_PLMN_INFO_ID";
        case 0x0072F018:
            return "REL_AUPF_PLMN_INFO_ID";
        case 0x0072F019:
            return "REL_AMF_PLMN_INFO_ID";
        default:
            return "Unknown";
    }
}

int GetDbgLogPldAuditHist(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    VccbDbgPldAuditHistory_type *pHist = NULL;
    VccbDbgUpdatePldAuditHistory_type *pUpdate = NULL;

    int32_t i;
    uint16_t count;
    int32_t startIdx = 0;

    PRINT("+====================================================================================================+\n");
    PRINT("| PLD Audit History                                                                                  |\n");
    PRINT("+----------------------------------------------------------------------------------------------------+\n");
    PRINT(" [idx] relationId | relationName                  | PldReadResult | updateTime \n");
    PRINT("+----------------------------------------------------------------------------------------------------+\n");

    pHist = &PDBG->pldAuditHist;

    if (pHist->curIdx == -1)  // no history
    {
        PRINT("+====================================================================================================+\n");
        return GOOD;
    }
    else if (pHist->curIdx == MAX_HISTORY_NUM - 1)
        startIdx = 0;
    else if (pHist->cycleFlag)
        startIdx = pHist->curIdx + 1;  // not the first cycle, start from the middle

    for (i = startIdx, count = 1; count <= MAX_HISTORY_NUM; i++, count++)
    {
        if (i == MAX_HISTORY_NUM) i = 0;

        if (0 == PDBG->pldAuditHist.update[i].updateTime) continue;

        pUpdate = &pHist->update[i];

        char updateTime[64] = {0, };
        getTimeStringWithTimezone(pUpdate->updateTime, updateTime, sizeof(updateTime));

        PRINT(" [%3d]  %9X | %29s | %13s | %s", count, pUpdate->relId, getPldRelationName(pUpdate->relId),
              pUpdate->readResult == GOOD ? "GOOD" : "ERROR", updateTime);
    }

    PRINT("+====================================================================================================+\n");
    return GOOD;
}

int GetDbgLogGnbAuditHist(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    VccbDbgGnbAuditHistoryInfo_type *pHist = &PDBG->gnbAuditHist;
    VccbGnbAuditInfo_type *pAudit = NULL;

    int32_t startIdx = 0;

    PRINT("+==================================================================+\n");
    PRINT("| gNB Audit History                                                |\n");
    PRINT("+------------------------------------------------------------------+\n");
    PRINT(" internalAuditStbGnbNumInfoCount : %u\n", pHist->internalAuditStbGnbNumInfoCount);
    if (pHist->curIdx == -1) // no history
    {
        PRINT("+==================================================================+\n");
        return GOOD;
    }
    else if (pHist->curIdx == MAX_HISTORY_NUM - 1)
    {
        startIdx = 0;
    }
    else if (pHist->cycleFlag)
    {
        startIdx = pHist->curIdx + 1;  // not the first cycle, start from the middle
    }

    int32_t i;
    uint16_t count;
    for (i = startIdx, count = 1; count <= MAX_HISTORY_NUM; i++, count++)
    {
        if (i == MAX_HISTORY_NUM) i = 0;
        if (0 == pHist->auditHistory[i].auditTime) continue;

        PRINT("+------------------------------------------------------------------+\n");

        pAudit = &pHist->auditHistory[i];

        char auditTime[64] = {0, };
        getTimeStringWithTimezone(pAudit->auditTime, auditTime, sizeof(auditTime));
        PRINT(" [%3d]  %s", count, auditTime);

        if (0 == pAudit->count)
        {
            PRINT(" \tEmpty gnbAuditInfo; Nothing to audit.\n");
        }
        else
        {
            const uint32_t maxAuditCnt = MIN(pAudit->count, MAX_GNB_PER_SYS_ITSCP_VCCB);
            for (uint32_t auditIdx = 0; auditIdx < maxAuditCnt; auditIdx++)
            {
                PRINT(" \tgnbId=%u : gnbNum[%u] -> gnbNum[%u]\n",
                    pAudit->targetGnbId[auditIdx], pAudit->srcGnb[auditIdx], pAudit->dstGnb[auditIdx]);
            }
        }
    }

    PRINT("+==================================================================+\n");
    return GOOD;
}

int GetDbgLogMrdcBuffInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    int loop, loop2;
    long long attempt = 0, success = 0;

    const char *buffName[MAX_BUFF_TYPE_FOR_STATS] = {"buffType1024", "buffType2048", "buffType4096", "buffType9216",
                                                     "Invalid     "};

    VccbDbgMrdcBuffStats_type *pStats = &PDBG->mrdcBuffCtrlStats;
    PRINT(
        "+============================================================================================================="
        "=========================+\n");
    PRINT(
        "+Expected number of elem : %10u "
        "=================================================================================================+\n",
        (unsigned int)MIN(PENV->deploymentFlavorInfo.vccbMaxCallNum, MAX_CALL_COUNT_PER_CPC) / 10);

    PRINT(
        "|%12s|%16s| attempt | succ    | NO_AVAIL_RESRC | INVALID_REQ    | INVALID_CALLID | "
        "ALREADY_FREE   | OTHER_FAILURE  |\n",
        "type", "");
    for (loop = 0; loop < MAX_BUFF_TYPE_FOR_STATS; loop++)
    {
        attempt = 0, success = 0;
        for (loop2 = 0; loop2 < VCCB_CALL_THREAD_NUM; loop2++)
        {
            attempt += pStats->allocStats[loop].attempt[loop2];
            success += pStats->allocStats[loop].success[loop2];
        }
        PRINT("|%s| allocStats     |%9llu|%9llu|", buffName[loop], attempt, success);
        for (loop2 = MRDC_BUFF_CAUSE_NO_AVAIL_RESOURCE; loop2 < MRDC_BUFF_CAUSE_END; loop2++)
        {
            PRINT(" %14u |", pStats->allocStats[loop].fail[loop2]);
        }
        PRINT("\n");

        attempt = 0, success = 0;
        for (loop2 = 0; loop2 < VCCB_CALL_THREAD_NUM; loop2++)
        {
            attempt += pStats->freeStats[loop].attempt[loop2];
            success += pStats->freeStats[loop].success[loop2];
        }
        PRINT("|%s| freeStats      |%9llu|%9llu|", buffName[loop], attempt, success);
        for (loop2 = MRDC_BUFF_CAUSE_NO_AVAIL_RESOURCE; loop2 < MRDC_BUFF_CAUSE_END; loop2++)
        {
            PRINT(" %14u |", pStats->allocStats[loop].fail[loop2]);
        }
        PRINT("\n");

        PRINT("|%s| freeStatsAudit |%9u|%9u|", buffName[loop], pStats->freeStatsAudit[loop].attempt,
              pStats->freeStatsAudit[loop].success);
        for (loop2 = MRDC_BUFF_CAUSE_NO_AVAIL_RESOURCE; loop2 < MRDC_BUFF_CAUSE_END; loop2++)
        {
            PRINT(" %14u |", pStats->freeStatsAudit[loop].fail[loop2]);
        }
        PRINT("\n");
        PRINT(
            "+========================================================================================================="
            "=============================+\n");
    }
    return GOOD;
}

int GetDbgLogHasEventHist(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    VccbDbgHasEventHistory_type *pHist = NULL;
    VccbHasInfo_type *pHasInfo = NULL;

    int32_t i;
    uint16_t count;
    int32_t startIdx = 0;

    PRINT("+======================================================================================+\n");
    PRINT("| HAS Event History                                                                    |\n");
    PRINT("+--------------------------------------------------------------------------------------+\n");
    PRINT(" [idx] update | vnfc | vnfc |   state   |   Sync   |      updateTime  \n");
    PRINT("        type  | Type |  Id  |           |   Mode   |                  \n");
    PRINT("+--------------------------------------------------------------------------------------+\n");

    pHist = &PDBG->hasEventHist;

    if (pHist->curIdx == -1)  // no history
    {
        PRINT("+======================================================================================+\n");
        return GOOD;
    }
    else if (pHist->curIdx == MAX_HISTORY_NUM - 1)
        startIdx = 0;
    else if (pHist->cycleFlag)
        startIdx = pHist->curIdx + 1;  // not the first cycle, start from the middle

    for (i = startIdx, count = 1; count <= MAX_HISTORY_NUM; i++, count++)
    {
        if (i == MAX_HISTORY_NUM) i = 0;

        pHasInfo = &pHist->hasHist[i];

        if (0 == pHasInfo->updateTime) continue;

        char updateTime[64] = {0, };
        getTimeStringWithTimezone(pHasInfo->updateTime, updateTime, sizeof(updateTime));

        if (pHasInfo->isMainUnit == TRUE)
        {
            PRINT(" [%3d]  %4s  |  CMC | %4d |    ACTIVE |     -    | %s", count,
                  pHasInfo->isInitProc == TRUE ? "INIT" : "NOTI", pHasInfo->cmc.VnfcId, updateTime);
        }
        else
        {
            PRINT(" [%3d]  %4s  |  CPC | %4d | %9s | %8s | %s", count, pHasInfo->isInitProc == TRUE ? "INIT" : "NOTI",
                  PCFG->vm.unitId,
                  pHasInfo->cpc.State == HAS_ACTIVE ? "ACTIVE"
                                                    : (pHasInfo->cpc.State == HAS_STANDBY ? "STANDBY" : "ACT_ALONE"),
                  pHasInfo->cpc.SyncMode == HAS_SYNC_MODE ? "SYNC" : "NON_SYNC", updateTime);
        }
    }

    PRINT("+======================================================================================+\n");
    return GOOD;
}

/**
 *  @brief Get GnbDuInfo
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbGnbDuInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint16_t loop, loop2;
    gnbDuInfo_type *pGnbDu = NULL;
    char printBuf[MAX_LOCAL_STR_BUF_LEN];
    char *outBuf;
    int strLen = 0;
    int buffSize = sizeof(printBuf);
    outBuf = printBuf;
    outBuf[0] = '\0';
    uint16_t gnbNum = 0;
    uint8_t gnbNumOfVclb = 0;

    PRINT("+==============================================================+\n");
    PRINT("| gnbDuInfo                                                    |\n");
    PRINT("+--------------------------------------------------------------+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    PRINT(" endPoint |   gnbDuId | board | ovld  |  rrc   |     sw      |  addtionalTNLState    | nrof  | cell List....\n");
    PRINT(" Idx      |           | Type  | State |  ver   |     ver     | (gnbNumOfVclb/gnbId)  | Cells |              \n");
    PRINT("+--------------------------------------------------------------+\n");
    for (loop = 0; loop < MAX_GNB_DU_PER_GNB_CU_CP; loop++)
    {
        pGnbDu = &pGnb->gnbDu[loop];
        if (!pGnbDu->status)
        {
            continue;
        }

        for (loop2 = 0; loop2 < MAX_CELL_PER_DU; loop2++)
        {
            if (pGnbDu->cellInDu[loop2].status != EQUIP)
            {
                continue;
            }
            PRINT_BUF(strLen, OUTBUF, "[%2d] ", pGnbDu->cellInDu[loop2].cellNum);
        }

        if (PVCLBSTS != nullptr)
        {
            // Get gnbNum of Vclb.
            for (gnbNumOfVclb = 0; gnbNumOfVclb < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNumOfVclb++)
            {
                if (EQUIP != PVCLBSTS->gnb[gnbNumOfVclb].status) continue;

                if (PVCLBSTS->gnb[gnbNumOfVclb].gnbId == pGnb->globalGnbId.gnbId.id) break;
            }

            PRINT(" %8u | %9lu | %5d | %5d | %2d%2d%2d | %11s | %2d (%1u/%14d) | %5d | %s \n", loop, pGnbDu->gnbDuId,
                pGnbDu->boardType, pGnbDu->overloadStatus, pGnbDu->rrcVersion[0], pGnbDu->rrcVersion[1],
                pGnbDu->rrcVersion[2], pGnbDu->swVersion.raw.text,
                (gnbNumOfVclb < MAX_GNB_PER_SYS_ITSCP_VCCB) ? (int)(PVCLBSTS->gnb[gnbNumOfVclb].sctp_state[loop]) : (-1),
                gnbNumOfVclb, (gnbNumOfVclb < MAX_GNB_PER_SYS_ITSCP_VCCB) ? (int)(PVCLBSTS->gnb[gnbNumOfVclb].gnbId) : (-1),
                pGnbDu->nrofCells, outBuf);
        }
        else
        {
            PRINT(" %8u | %9lu | %5d | %5d | %2d%2d%2d | %11s |          n/a          | %5d | %s \n", loop, pGnbDu->gnbDuId,
                pGnbDu->boardType, pGnbDu->overloadStatus, pGnbDu->rrcVersion[0], pGnbDu->rrcVersion[1],
                pGnbDu->rrcVersion[2], pGnbDu->swVersion.raw.text, pGnbDu->nrofCells, outBuf);
        }

        outBuf[0] = '\0';
        strLen = 0;
    }
    PRINT("+--------------------------------------------------------------+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+==============================================================+\n");

    return GOOD;
}

void Get_NSA_UserInactivityInfo(VccbGnbInfo_type *const pGnb)
{
    if (pGnb == NULL) return;

    auto pUserInact = &pGnb->UserInactivity;

    SHOW_VALUE(pUserInact->featureEnabled);
    SHOW_VALUE(pUserInact->signalingTimer);
    SHOW_VALUE(pUserInact->activityNotificationLevel);
    SHOW_VALUE(pUserInact->x2Reporting);
    SHOW_VALUE(pUserInact->x2ReleaseTimer);
    SHOW_VALUE(pUserInact->ueInactivityTimer);
    for (uint16_t qci = 0; qci < MAX_QCI_VALUE; ++qci)
    {
        if (pUserInact->drbInactivityTimerEntries[qci])
            SHOW_VALUE_OF_LIST(*pUserInact, drbInactivityTimerEntries, qci);
    }
    SHOW_VALUE(pUserInact->spidBasedUserInactivity);
    for (uint16_t spid = 1; spid <= MAX_SPID_VALUE; ++spid)
    {
        if (pUserInact->spidBasedUserInactivityEntries[spid].status == N_EQUIP) continue;

        PRINT(" pUserInact->spidBasedUserInactivityEntries[%d].ueInactivityTimer\t= %d\n", spid,
              pUserInact->spidBasedUserInactivityEntries[spid].ueInactivityTimer);

        for (uint16_t qci = 0; qci < MAX_QCI_VALUE; ++qci)
        {
            if (pUserInact->spidBasedUserInactivityEntries[spid].drbInactivityTimerEntries[qci])
            {
                PRINT(" pUserInact->spidBasedUserInactivityEntries[%d].drbInactivityTimerEntries[%d]\t= %d\n", spid,
                      qci, pUserInact->spidBasedUserInactivityEntries[spid].drbInactivityTimerEntries[qci]);
            }
        }
    }

    FreqBasedUserInactivityControl_type *pFreqControlInfo = &pUserInact->freqControlInfo;
    if (PFOO->VF_UserInactivityTimer_FrequencyBasedControl)
    {
        SHOW_VALUE(pFreqControlInfo->featureSwitch);
        for (uint8_t freqGroupIdx = 0; freqGroupIdx < VCCB_MAX_USER_INACT_FREQGROUP; freqGroupIdx++)
        {
            if (TRUE == pFreqControlInfo->freqGroup[freqGroupIdx].usage)
            {
                PRINT(" pFreqControlInfo->freqGroup[%d].priority\t= %d\n", freqGroupIdx,
                      pFreqControlInfo->freqGroup[freqGroupIdx].priority);
                PRINT(" pFreqControlInfo->freqGroup[%d].x2Reporting\t= %d\n", freqGroupIdx,
                      pFreqControlInfo->freqGroup[freqGroupIdx].x2Reporting);
            }
            else
            {
                continue;
            }
        }
        for (uint8_t freqListIdx = 0; freqListIdx < VCCB_MAX_USER_INACT_FREQLIST; freqListIdx++)
        {
            if (TRUE == pFreqControlInfo->freqList[freqListIdx].usage)
            {
                PRINT(" pFreqControlInfo->freqList[%d].frequencyGroupIndex\t= %d\n", freqListIdx,
                      pFreqControlInfo->freqList[freqListIdx].frequencyGroupIndex);
                PRINT(" pFreqControlInfo->freqList[%d].ssbArfcn\t= %d\n", freqListIdx,
                      pFreqControlInfo->freqList[freqListIdx].ssbArfcn);
            }
            else
            {
                continue;
            }
        }
    }
    if (PFOO->VF_UserInactivityTimer_PerCellControl)
    {
        SHOW_VALUE(pUserInact->perCellOnOff);

        for (uint8_t profileIdx = 0; profileIdx < VCCB_MAX_USER_INACT_ENDC_PROFILES; ++profileIdx)
        {
            if (pUserInact->inactivityDataProfileEntries[profileIdx].status == N_EQUIP) continue;

            PRINT(" pUserInact->inactivityDataProfileEntries[%d].ueInactivityTimer\t= %d\n", profileIdx,
                  pUserInact->inactivityDataProfileEntries[profileIdx].ueInactivityTimer);

            for (uint16_t qci = 0; qci < MAX_QCI_VALUE; ++qci)
            {
                if (pUserInact->inactivityDataProfileEntries[profileIdx].drbInactivityTimerEntries[qci])
                {
                    PRINT(" pUserInact->inactivityDataProfileEntries[%d].drbInactivityTimerEntries[%d]\t= %d\n", profileIdx,
                          qci, pUserInact->inactivityDataProfileEntries[profileIdx].drbInactivityTimerEntries[qci]);
                }
            }

            for (uint16_t spid = 1; spid <= MAX_SPID_VALUE; ++spid)
            {
                if (pUserInact->inactivityDataProfileEntries[profileIdx].
                        spidBasedUserInactivityEntries[spid].status == N_EQUIP) continue;

                PRINT(" pUserInact->inactivityDataProfileEntries[%d].spidBasedUserInactivityEntries[%d].ueInactivityTimer\t= %d\n",
                      profileIdx, spid,
                      pUserInact->inactivityDataProfileEntries[profileIdx].spidBasedUserInactivityEntries[spid].ueInactivityTimer);

                for (uint16_t qci = 0; qci < MAX_QCI_VALUE; ++qci)
                {
                    if (pUserInact->inactivityDataProfileEntries[profileIdx].
                            spidBasedUserInactivityEntries[spid].drbInactivityTimerEntries[qci])
                    {
                        PRINT(" pUserInact->inactivityDataProfileEntries[%d].spidBasedUserInactivityEntries[%d]."
                              "drbInactivityTimerEntries[%d]\t= %d\n", profileIdx, spid, qci,
                              pUserInact->inactivityDataProfileEntries[profileIdx].
                                  spidBasedUserInactivityEntries[spid].drbInactivityTimerEntries[qci]);
                    }
                }
            }
        }
    }
}


