void Get_SA_UserInactivityInfo(VccbGnbInfo_type *const pGnb)
{
    if (pGnb == NULL) return;

    auto pUserInactSA = &pGnb->UserInactivitySA;

    SHOW_VALUE(pUserInactSA->featureEnabled);
    SHOW_VALUE(pUserInactSA->signalingTimer);
    SHOW_VALUE(pUserInactSA->activityNotificationLevel);
    SHOW_VALUE(pUserInactSA->nrPpaSignalingTimerEnabled);
    SHOW_VALUE(pUserInactSA->dataInactivityPerCellOnOff);
    SHOW_VALUE(pUserInactSA->ueInactivityTimer);
    for (uint16_t qos5qi = 0; qos5qi < MAX_5QI_VALUE; ++qos5qi)
    {
        if (pUserInactSA->drbInactivityTimerEntries[qos5qi])
            SHOW_VALUE_OF_LIST(*pUserInactSA, drbInactivityTimerEntries, qos5qi);
    }
    for (uint16_t pDUSessionId = 0; pDUSessionId < MAX_PDU_SESS_PER_CALL; ++pDUSessionId)
    {
        if (pUserInactSA->pDUSessionInactivityTimerEntries[pDUSessionId])
            SHOW_VALUE_OF_LIST(*pUserInactSA, pDUSessionInactivityTimerEntries, pDUSessionId);
    }
    SHOW_VALUE(pUserInactSA->rfspControlInfo.featureSwitch);

    rfspBasedInactivityList_type *pRfsp = NULL;
    for (uint16_t rfspIndex = 0; rfspIndex < VCCB_MAX_USER_INACT_RFSP_LIST; ++rfspIndex)
    {
        pRfsp = &pUserInactSA->rfspControlInfo.rfspList[rfspIndex];
        if (CI_use == pRfsp->usage)
        {
            PRINT(" rfspIndex(%d) - rfsp(%3d), ueInactivityTimer(%4d)\n",
                    rfspIndex, pRfsp->rfsp, pRfsp->ueInactivityTimer);
            for (uint16_t qos5qi = 0; qos5qi < MAX_5QI_VALUE; ++qos5qi)
            {
                if (pRfsp->drbInactivityTimerEntries[qos5qi])
                {
                    PRINT("                qos-5qi(%3d), drbInactivityTimer(%4d)\n",
                            qos5qi, pRfsp->drbInactivityTimerEntries[qos5qi]);
                }
            }
        }
    }

    if (PFOO->VF_DataInactivitySA_perCell)
    {
        saDataInactProfile_type *pProfile = NULL;
        for (uint16_t profileIndex = 0; profileIndex < VCCB_MAX_USER_INACT_SA_PROFILES; profileIndex++)
        {
            pProfile = &pUserInactSA->dataProfileInfo[profileIndex];
            if (CI_use == pProfile->usage)
            {
                PRINT(" profileIndex(%d) - ueInactivityTimer(%4d)\n", profileIndex, pProfile->ueInactivityTimer);
                for (uint16_t qos5qi = 0; qos5qi < MAX_5QI_VALUE; ++qos5qi)
                {
                    if (pProfile->drbInactivityTimerEntries[qos5qi])
                    {
                        PRINT("   + drbInactivityTimerEntries[%3d] = %d\n",
                                qos5qi, pProfile->drbInactivityTimerEntries[qos5qi]);
                    }
                }
                for (uint16_t rfspIndex = 0; rfspIndex < VCCB_MAX_USER_INACT_RFSP_LIST; ++rfspIndex)
                {
                    pRfsp = &pProfile->rfspList[rfspIndex];
                    if (CI_use == pRfsp->usage)
                    {
                        PRINT("   + rfspIndex(%d) - rfsp(%3d), ueInactivityTimer(%4d)\n",
                                rfspIndex, pRfsp->rfsp, pRfsp->ueInactivityTimer);
                        for (uint16_t qos5qi = 0; qos5qi < MAX_5QI_VALUE; ++qos5qi)
                        {
                            if (pRfsp->drbInactivityTimerEntries[qos5qi])
                            {
                                PRINT("                    qos-5qi(%3d), drbInactivityTimer(%4d)\n", qos5qi,
                                        pRfsp->drbInactivityTimerEntries[qos5qi]);
                            }
                        }
                    }
                }
            }
        }
    }

    if (PFOO->VF_BasicCallProcedureforRedCapUE)
    {
        PRINT("--------- SA Redcap Information --------\n");
        Get_SA_Redcap_UserInactivityInfo(pGnb);
        PRINT("---------------------------------------------------------\n");
    }

    if (PFOO->VF_ServiceConfigurationInactivity)
    {
        PRINT("--------- SA Service Configuration User Inactivity Information --------\n");
        Get_SA_InactServiceConfigProfile_UserInactivityInfo(pGnb);
        PRINT("---------------------------------------------------------\n");
    }
}

