/**
 *  @brief Get Spid Info
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbSpidInfo(int32_t argc, char *argv[])
{
    if (2 > argc || 3 < argc)
    {
        PRINT(
            "Usage : itscp_vccb get spidInfo plmnIndex {spid} (wrong argument number - expected 2 or 3, received=%d)\n",
            argc);
        return GOOD;
    }

    uint16_t gnbNum = 0;
    uint32_t spid;
    uint16_t iter = 0;
    uint8_t plmnIdx = StrUtil::itscp_strtoul<uint8_t>(argv[1]);
    if (MAX_PLMN_INDEX <= plmnIdx)
    {
        PRINT("PLMN index(%d) over ranged !! \n", plmnIdx);
        return GOOD;
    }

    if (3 == argc)
    {
        spid = StrUtil::itscp_strtoul<uint32_t>(argv[2]);
        if (MAX_SPID_VALUE < spid)
        {
            PRINT("SPID(%d) over ranged !! \n", spid);
            return GOOD;
        }

        MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

        const uint16_t mcc = pGnb->plmnIndexInfo[plmnIdx].s2.mcc;
        const uint16_t mnc = pGnb->plmnIndexInfo[plmnIdx].s2.mnc;
        if (VCCB_FLAG_OFF ==
            pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].spidInUseFlag)
        {
            PRINT("SPID %d not available for PLMN mcc(0x%X) mnc(0x%X)\n", spid, mcc, mnc);
            return GOOD;
        }

        PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);

        PRINT("spid-based-serving-cell-selection-enabled: %d \n", pGnb->cfg.spidBasedServingCellSelectionEnable);
        PRINT("spid-based-serving-cell-selection-plmn-enabled: %d \n",
              pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedForPlmnEnable);
        PRINT("\n");
        PRINT("=================================================\n");
        PRINT("| SPID %d | PLMN mcc(0x%X) mnc(0x%X)            \n", spid, mcc, mnc);
        PRINT("=================================================\n");
        PRINT("| SpCell Arfcn                                  |\n");
        PRINT("-------------------------------------------------\n");
        if (0 == pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].numSpCellArfcn)
        {
            PRINT("| No SPCell Arfcn entries                       |\n");
        }
        else
        {
            for (iter = 0;
                 iter < pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].numSpCellArfcn;
                 iter++)
            {
                PRINT("| %21d: %-21d  |\n", iter,
                      pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].spCellArfcn[iter]);
            }
        }
        PRINT("-------------------------------------------------\n");
        PRINT("| SCell Arfcn                                   |\n");
        PRINT("-------------------------------------------------\n");
        if (0 == pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].numSCellArfcn)
        {
            PRINT("| No SCell Arfcn entries                        |\n");
        }
        else
        {
            for (iter = 0;
                 iter < pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].numSCellArfcn;
                 iter++)
            {
                PRINT("| %21d: %-21d  |\n", iter,
                      pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[spid].sCellArfcn[iter]);
            }
        }
        PRINT("+===============================================+\n");

        MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

        return GOOD;
    }

    PRINT("+===============================================+\n");
    PRINT("| SPID INFORMATION                              +\n");
    PRINT("+-----------------------------------------------+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    const uint16_t mcc = pGnb->plmnIndexInfo[plmnIdx].s2.mcc;
    const uint16_t mnc = pGnb->plmnIndexInfo[plmnIdx].s2.mnc;

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);

    PRINT("spid-based-serving-cell-selection-enabled: %d \n", pGnb->cfg.spidBasedServingCellSelectionEnable);
    PRINT("spid-based-serving-cell-selection-plmn-enabled: %d \n",
          pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedForPlmnEnable);
    PRINT("\n");
    PRINT("=================================================\n");
    PRINT("| SPID Defaults for PLMN mcc(0x%X), mnc(0x%X)      |\n", mcc, mnc);
    PRINT("=================================================\n");
    PRINT("| SpCell Arfcn                                  |\n");
    PRINT("-------------------------------------------------\n");
    if (0 == pGnb->cfg.spidInfoPerPlmn[plmnIdx]
                 .spidBasedServingCellSelectionEntries[SPID_CELL_DEFAULTS_INDEX]
                 .numSpCellArfcn)
    {
        PRINT("| No SPCell Arfcn default entries               |\n");
    }
    else
    {
        for (iter = 0; iter < pGnb->cfg.spidInfoPerPlmn[plmnIdx]
                                  .spidBasedServingCellSelectionEntries[SPID_CELL_DEFAULTS_INDEX]
                                  .numSpCellArfcn;
             iter++)
        {
            PRINT("| %21d: %-21d  |\n", iter,
                  pGnb->cfg.spidInfoPerPlmn[plmnIdx]
                      .spidBasedServingCellSelectionEntries[SPID_CELL_DEFAULTS_INDEX]
                      .spCellArfcn[iter]);
        }
    }
    PRINT("-------------------------------------------------\n");
    PRINT("| SCell Arfcn                                   |\n");
    PRINT("-------------------------------------------------\n");
    if (0 ==
        pGnb->cfg.spidInfoPerPlmn[plmnIdx].spidBasedServingCellSelectionEntries[SPID_CELL_DEFAULTS_INDEX].numSCellArfcn)
    {
        PRINT("| No SCell Arfcn default entries                |\n");
    }
    else
    {
        for (iter = 0; iter < pGnb->cfg.spidInfoPerPlmn[plmnIdx]
                                  .spidBasedServingCellSelectionEntries[SPID_CELL_DEFAULTS_INDEX]
                                  .numSCellArfcn;
             iter++)
        {
            PRINT("| %21d: %-21d  |\n", iter,
                  pGnb->cfg.spidInfoPerPlmn[plmnIdx]
                      .spidBasedServingCellSelectionEntries[SPID_CELL_DEFAULTS_INDEX]
                      .sCellArfcn[iter]);
        }
    }
    PRINT("+===============================================+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    return GOOD;
}

int GetGnbNbrGNBCell(int32_t argc, char *argv[])
{
    uint32_t nbrGnbCellIdx = 0;
    nbrGnbCellInfo_type *ptNbrGnbCellInfo = NULL;

    uint32_t flagPrintSingle = N_EQUIP;
    uint32_t totalCount = 0;

    uint16_t gnbNum = 0;
    CHECK_ARGC_SAVE_ARGV(2, gnbNum, MAX_GNB_PER_SYS_ITSCP_VCCB);
    VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
    ptNbrGnbCellInfo = pGnb->nbrGnbCell;
    nbrGnbCellCgiListExt_type *pNbrGnbCellCgiListExt = pGnb->nbrGnbCellCgiListExt;

    if (argc > 2)
    {
        CHECK_ARGC32_SAVE_ARGV(3, nbrGnbCellIdx, MAX_NBR_GNB_CELL_PER_GNB);
        flagPrintSingle = EQUIP;
    }

    PRINT(
        "+======================================================================================================================"
        "========================================================================================================+\n");
    PRINT(
        "| NbrGNBCellInfo                                                                                                    "
        "                                                                                                           |\n");
    PRINT(
        "+--------------------------------------------------------------------------------------------------------------------"
        "----------------------------------------------------------------------------------------------------------+\n");
    PRINT(
        "|    Idx | gNBId (len) |       NrCgi           | nr   | nrArfcn | nrArfcn | ssb     | fiveGs   | conf  | conf | VoNR "
        "|                         CellPlmnInfo (MCC MNC)                         | smtc |     smtc1      | cellDir|\n");
    PRINT(
        "|        |             |   plmn  | nrCellId    | Pci  | Dl      | Ul      | Arfcn   | Tac      | Tac   | Tac  |      "
        "|                                                                        |Status|dura|peri|offset|        |\n");
    PRINT(
        "|        |             | mcc mnc |             |      |         |         |         |          |       | Ind  |      "
        "|                                                                        |      |tion|odic|      |        |\n");
    PRINT(
        "+----------------------------------------------------------------------------------------------------------------------"
        "--------------------------------------------------------------------------------------------------------+\n");

    if (EQUIP == flagPrintSingle)
    {
        if (N_EQUIP == ptNbrGnbCellInfo[nbrGnbCellIdx].status)
        {
            return GOOD;
        }

        PRINT("| %6d ", nbrGnbCellIdx);

        printSingleNbrGNBCell(&ptNbrGnbCellInfo[nbrGnbCellIdx], &pNbrGnbCellCgiListExt[nbrGnbCellIdx]);
    }
    else
    {
        for (nbrGnbCellIdx = 0; nbrGnbCellIdx < MAX_NBR_GNB_CELL_PER_GNB; nbrGnbCellIdx++)
        {
            if (N_EQUIP == ptNbrGnbCellInfo[nbrGnbCellIdx].status)
            {
                continue;
            }

            PRINT("| %6d ", nbrGnbCellIdx);
            totalCount++;

            printSingleNbrGNBCell(&ptNbrGnbCellInfo[nbrGnbCellIdx], &pNbrGnbCellCgiListExt[nbrGnbCellIdx]);
        }
    }
    PRINT(
        "+----------------------------------------------------------------------------------------------------------------------"
        "--------------------------------------------------------------------------------------------------------+\n");
    PRINT(
        "| NbrGNBCellInfo                  totalCount : %5d                                                                     "
        "                                                                                                      |\n",
        totalCount);
    PRINT(
        "+----------------------------------------------------------------------------------------------------------------------"
        "--------------------------------------------------------------------------------------------------------+\n");

    return GOOD;
}

