/**
 *  @brief Get X2 Neighbor Info
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbNbrX2Info(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint16_t loop;
    x2NbrInfo_type *pX2Nbr = NULL;
    gnbDuInfo_type *pGnbDu = NULL;

    PRINT("+================================================================================+\n");
    PRINT("| x2NbrInfo                                                                      |\n");
    PRINT("+--------------------------------------------------------------------------------+\n");
    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    PRINT(" endPointIdx |    MeNBId | mappingGnbDuId              | x2apState |  mcc  |  mnc \n");
    PRINT("+--------------------------------------------------------------------------------+\n");
    for (loop = 0; loop < MAX_ENB_PER_GNB_CU_CP; loop++)
    {
        pX2Nbr = &pGnb->x2Nbr[loop];
        pGnbDu = &pGnb->gnbDu[pX2Nbr->mappingF1Idx];
        if (!pX2Nbr->status)
        {
            continue;
        }
        if ((pX2Nbr->mappingF1Idx < MAX_GNB_DU_PER_GNB_CU_CP) && (pGnbDu->status))
        {
            PRINT(" %11u | %9u | %9lu (endpointF1:%4d) | %9d | 0x%03X | 0x%03X \n", loop, pX2Nbr->enbId, pGnbDu->gnbDuId,
                  pX2Nbr->mappingF1Idx, pX2Nbr->x2apLinkState, pX2Nbr->enbPlmn.s2.mcc, pX2Nbr->enbPlmn.s2.mnc);
        }
        else
        {
            PRINT(" %11u | %9u | unknownDU (endpointF1:%4d) | %9d | 0x%03X | 0x%03X \n", loop, pX2Nbr->enbId, pX2Nbr->mappingF1Idx,
                  pX2Nbr->x2apLinkState, pX2Nbr->enbPlmn.s2.mcc, pX2Nbr->enbPlmn.s2.mnc);
        }
    }
    PRINT("+--------------------------------------------------------------------------------+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+--------------------------------------------------------------------------------+\n");
    PRINT(" * mappingGnbDuId is used only if SgNB does not receive CandidateCellInfoList from MeNB.\n");
    PRINT("+================================================================================+\n");

    return GOOD;
}

/**
 *  @brief Get Xn Neighbor Info
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbNbrXnInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint16_t xnNbrIdx = 0;
    uint16_t amfIdx = 0;
    xnNbrInfo_type *pXNNbr = NULL;

    // For Diplay
    int32_t prt_gnbNum = -1;
    int32_t prt_xnNbr = -1;

    switch (argc)
    {
        // Print All Gnb
        case 1:
            break;

        // Print Specfic Gnb
        case 2:
            prt_gnbNum = StrUtil::itscp_strtol<int32_t>(argv[1]);
            if(prt_gnbNum < 0 || prt_gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
            {
                PRINT("invalid gnbNum\n");
                return GOOD;
            }
            break;

        // Print Specfic Gnb + xn nbr + amf info
        case 3:
            prt_gnbNum = StrUtil::itscp_strtol<int32_t>(argv[1]);
            if(prt_gnbNum < 0 || prt_gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB)
            {
                PRINT("invalid gnbNum\n");
                return GOOD;
            }
            prt_xnNbr = StrUtil::itscp_strtol<int32_t>(argv[2]);
            if(prt_xnNbr < 0 || prt_xnNbr >= MAX_XN_NBR_PER_GNB)
            {
                PRINT("invalid prt_xnNbr\n");
                return GOOD;
            }
            break;

        default:
            break;
    }

    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    if (prt_gnbNum != -1 && prt_gnbNum != gnbNum) continue;

    PRINT("%s-> GNB_NUM: %d  GNB_ID: %u %s\n", VCCB_C_LGREEN, gnbNum, pGnb->globalGnbId.gnbId.id, VCCB_C_RESET);
    PRINT("+--------------------------------------------------------+\n");
    PRINT(" xnNbr | X | Vendor | Node |     e/gNBId(len) |   PLMN   |\n");
    PRINT("   Idx |   |        | Type |                  |          |\n");
    PRINT("+--------------------------------------------------------+\n");
    for (xnNbrIdx = 0; xnNbrIdx < MAX_XN_NBR_PER_GNB; xnNbrIdx++)
    {
        pXNNbr = &pGnb->xnNbr[xnNbrIdx];
        if (N_EQUIP == pXNNbr->status)
        {
            continue;
        }

        if (prt_xnNbr != -1 && prt_xnNbr != xnNbrIdx) continue;

        // Main Tuplue
        PRINT(" %5u |%s|", xnNbrIdx, (pXNNbr->xnapLinkState == CI_use ? "INS" : "OOS"));
        PRINT("%8s|", (pXNNbr->isSamsungVendor == CI_use ? "Samsung" : "Unknown"));

        uint32_t idLength;

        switch (pXNNbr->ngRanNodeType)
        {
            case ngRanNode_ngEnbType:
                switch (pXNNbr->enbId.idType)
                {
                    case macro_ng_enb_id:
                        idLength = 20;
                        break;
                    case short_macro_ng_enb_id:
                        idLength = 18;
                        break;
                    case long_macro_ng_enb_id:
                        idLength = 21;
                        break;
                    default:
                        idLength = 0;
                }

                if (pXNNbr->present.ngRanNodeId == OPT_PRESENT)
                    PRINT(" %4s | %11u(%3u) ", "ENB", pXNNbr->enbId.id, idLength);
                else
                    PRINT(" %4s | %11s(%3s) ", "ENB", "-", "-");
                break;

            case ngRanNode_GnbType:
                if (pXNNbr->present.ngRanNodeId == OPT_PRESENT)
                    PRINT(" %4s | %11u(%3u) ", "GNB", pXNNbr->gnbId.id, pXNNbr->gnbId.idLength);
                else
                    PRINT(" %4s | %11s(%3s) ", "GNB", "-", "-");
                break;

            default:  // not configured
                PRINT(" %4s | %11s(%3s) ", "-", "-", "-");
        }

        if (pXNNbr->present.plmnMcc == OPT_PRESENT)
        {
            PRINT("| %3X ", pXNNbr->plmn.s2.mcc);
        }
        else
        {
            PRINT("| -   ");
        }

        if (pXNNbr->present.plmnMnc == OPT_PRESENT)
        {
            PRINT(" %3X ", pXNNbr->plmn.s2.mnc);
        }
        else
        {
            PRINT("  -  ");
        }

        PRINT("|\n");

        // Sub Tuple
        if (prt_xnNbr != -1)
        {
            uint32_t cnt = 0;
            for (amfIdx = 0; amfIdx < MAX_AMF_SET_INFO; amfIdx++)
            {
                amfSetInformation_type *pAmf = &pXNNbr->extension.amfSetInfo[amfIdx];
                if (pAmf->status == EQUIP) cnt++;
            }

            if (cnt > 0)
            {
                PRINT("\n\n");

                PRINT("+--(cnt:%2u)-------------------------------------+\n", cnt);
                PRINT("| amfIdx | amfRegionId | AMF PLMN |             |\n");
                PRINT("+-----------------------------------------------+\n");

                for (amfIdx = 0; amfIdx < MAX_AMF_SET_INFO; amfIdx++)
                {
                    amfSetInformation_type *pAmf = &pXNNbr->extension.amfSetInfo[amfIdx];

                    if (pAmf->status != EQUIP) continue;

                    PRINT("| %6u ", amfIdx);

                    if (pAmf->present.amfRegionId == OPT_PRESENT)
                        PRINT("| %11u ", pAmf->amfRegionId);
                    else
                        PRINT("| %11s ", "-");

                    if (pAmf->present.amfPlmnMcc == OPT_PRESENT)
                        PRINT("| %3X ", pAmf->amfPlmn.s2.mcc);
                    else
                        PRINT("| -   ");

                    if (pAmf->present.amfPlmnMnc == OPT_PRESENT)
                        PRINT(" %3X ", pAmf->amfPlmn.s2.mnc);
                    else
                        PRINT("  -  ");

                    PRINT("|             |\n");
                }
            }
        }
    }
    PRINT("\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    return GOOD;
}

