/**
 *  @brief Get PdcpInfo
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbPdcpInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    int loop, profileIdx;
    pdcpInfoQci_type *pPdcpInfo = NULL;

    PRINT(
        "+============================================================================================================="
        "================================================+\n");
    PRINT(
        "| PdcpInfo                                                                                                    "
        "                                                |\n");
    PRINT(
        "+-------------------------------------------------------------------------------------------------------------"
        "------------------------------------------------+\n");
    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);

    for (profileIdx = 0; profileIdx < MAX_PDCP_INFO_PROFILE_PER_GNB; profileIdx++)
    {
        if (pGnb->pdcpProfile[profileIdx].status != EQUIP) continue;

        PRINT("|** PROFILE_INDEX[%d] \n", profileIdx);
        PRINT(
            "                                                     statusReport                           "
            "outOfOrder    "
            "   tReordering       ulDataSplit        ulRoHCEnabled          \n");
        PRINT(
            " qci | rlcMode | discardTimerUl | discardTimerDl |     Required |  snSizeUl |  snSizeDl |   Delivery "
            "|    "
            "   [UL/DL]         | Threshold    |     "
            "enabled/maxSess/Continue/Profile006  \n");
        PRINT(
            "+-----------------------------------------------------------------------------------------------------"
            "----"
            "----------------"
            "--------------------------------------------------+\n");
        for (loop = 0; loop < MAX_QCI_VALUE; loop++)
        {
            pPdcpInfo = &pGnb->pdcpProfile[profileIdx].pdcpInfoQci[loop];
            if (pPdcpInfo->shmStatus != EQUIP) continue;
            PRINT(
                " %3d |   %2s(%d) |  %8s(%2d)  |  %8s(%2d)  | %12d | %6s(%d) | %6s(%d) | %10d | "
                "%6s(%2d)/%6s(%2d) "
                "| %8s(%2d) | %2d/%2d/%2d/%2d\n",
                loop, getRlcModeName(pPdcpInfo->rlcMode), pPdcpInfo->rlcMode,
                getPdcpDiscardTimerUlName((uint8_t)pPdcpInfo->discardTimerUl), pPdcpInfo->discardTimerUl,
                getPdcpDiscardTimerDlName((uint8_t)pPdcpInfo->discardTimerDl), pPdcpInfo->discardTimerDl,
                pPdcpInfo->statusReportRequired, getPdcpSnSizeName(pPdcpInfo->snSizeUl), pPdcpInfo->snSizeUl,
                getPdcpSnSizeName(pPdcpInfo->snSizeDl), pPdcpInfo->snSizeDl, pPdcpInfo->outOfOrderDelivery,
                getTReorderingName(pPdcpInfo->tReorderingUl), pPdcpInfo->tReorderingUl,
                getTReorderingName(pPdcpInfo->tReorderingDl), pPdcpInfo->tReorderingDl,
                getUlDataSplitThreshold(pPdcpInfo->ulDataSplitThreshold), pPdcpInfo->ulDataSplitThreshold,
                pPdcpInfo->roHCConfig.ulRohcEnabled, pPdcpInfo->roHCConfig.ulRohcConfig.ulRohcMaxSession,
                pPdcpInfo->roHCConfig.ulRohcConfig.drbContinueRohc, pPdcpInfo->roHCConfig.ulRohcConfig.useProfile006
            );
        }
    }
    PRINT(
        "+---------------------------------------------------------------------------------------------------------"
        "-----------------------------------------------+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT(
        "+============================================================================================================="
        "===============================================+\n");

    return GOOD;
}

