/**
 *  @brief GetQciSupport
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbQciSupport(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    if ((argc == 3) && (!strcasecmp(argv[1], "plmn")))
    {
        int plmnIdx = StrUtil::itscp_strtol<int32_t>(argv[2]);
        if (MAX_PLMN_INDEX > plmnIdx && 0 <= plmnIdx)
        {
            PRINT(
                "+====================================================================================================="
                "========"
                "======+\n");
            PRINT(
                "| PCFG->perPlmnQciSupport Information                                                                 "
                "               "
                "      |\n");
            PRINT(
                "+----------------------------+----------------------------+----------------------------+--------------"
                "--------"
                "------+\n");
            uint16_t gnbNum = 0;

            MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

            PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
            int qci = 0;
            for (qci = 0; qci < MAX_QCI_VALUE; ++qci)
            {
                PRINT("perPlmnQciSupport[%d][%3d] usage=%d ", plmnIdx, qci,
                      pGnb->perPlmnQciSupport[plmnIdx][qci].usage);
                PRINT("weight-factor=%3d | ", pGnb->perPlmnQciSupport[plmnIdx][qci].qciWeightFactor);
                if (qci % 4 == 3) PRINT("|\n");
            }
            PRINT("\n");

            MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

            PRINT(
                "+----------------------------+----------------------------+----------------------------+--------------"
                "--------"
                "------+\n");
            PRINT(
                "+====================================================================================================="
                "========"
                "======+\n");
        }
        else
        {
            PRINT("Syntax error: \"%d\" is out of range. Please use 0 .. 7.\n", plmnIdx);
        }
    }
    else
    {
        PRINT(
            "+========================================================================================================="
            "===="
            "======+\n");
        PRINT(
            "| PCFG->qciSupport Information                                                                            "
            "    "
            "      |\n");
        PRINT(
            "+----------------------------+----------------------------+----------------------------+------------------"
            "----"
            "------+\n");
        uint16_t gnbNum = 0;

        MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

        PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);

        int loop = 0;
        for (loop = 0; loop < MAX_QCI_VALUE; ++loop)
        {
            PRINT("qciSupport[%3d] usage=%d ", loop, pGnb->qciSupport[loop].usage);
            PRINT("weight-factor=%3d | ", pGnb->qciSupport[loop].qciWeightFactor);
            PRINT("supportLbPscellChange=%3d | ", pGnb->qciSupport[loop].supportLbPscellChange);
            if (loop % 4 == 3) PRINT("|\n");
        }

        MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

        PRINT(
            "+----------------------------+----------------------------+----------------------------+------------------"
            "----"
            "------+\n");
        PRINT(
            "+========================================================================================================="
            "===="
            "======+\n");
    }

    return GOOD;
}

