int GetGnbDrxInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    int loop, profileIdx;
    drxConfigProfile_type *pDrxProfile = NULL;

    PRINT("+==============================================================+\n");
    PRINT("| drx-config-cu information                                    |\n");
    PRINT("| It shows only the list which selectionOrder is valid         |\n");
    PRINT("+--------------------------------------------------------------+\n\n");
    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("+=============== GNB_NUM[%d] GNB_ID[%10u] ================+\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    for (profileIdx = 0; profileIdx < MAX_DRX_PROFILE; profileIdx++)
    {
        if (pGnb->drxConfigProfile[profileIdx].status != EQUIP) continue;
        pDrxProfile = &pGnb->drxConfigProfile[profileIdx];

        PRINT("|***************************************************************\n");
        PRINT("|** PROFILE_NUM[%d] PROFILE_NAME : %20s      ***|\n", profileIdx, pDrxProfile->drxProfileName);
        PRINT("|** drxArp2TypeActivation [%3s]                              **|\n",
              (pDrxProfile->drxArp2TypeActivation) ? "ON" : "OFF");
        PRINT("|+ EUTRAN -----------------------------------------------------+\n");
        PRINT(
            "|qci | drxConfigSetup | longCycle | selectionOrder | shortDrxConfigSetup | shortCycle | shortCycleTimer "
            "|\n");
        PRINT("|--------------------------------------------------------------+\n");
        for (loop = 0; loop < MAX_QCI_VALUE; loop++)
        {
            struct drxConfig_s *pDrxInfo = &pDrxProfile->drxConfigCuQci[loop];
            if (pDrxInfo->status != EQUIP) continue;
            if (pDrxInfo->selectionOrder == UNKNOWN_SELECTION_ORDER) continue;

            PRINT("|%3d |%15d |%10d |%15d |%20d |%11d |%17d |\n", loop, pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                  pDrxInfo->selectionOrder, pDrxInfo->shortDrxConfigSetup, pDrxInfo->shortCycle,
                  pDrxInfo->shortCycleTimer);
        }
        PRINT("|+ NGRAN ------------------------------------------------------+\n");
        PRINT(
            "|5qi | drxConfigSetup | longCycle | selectionOrder | shortDrxConfigSetup | shortCycle | "
            "shortCycleTimer |\n");
        PRINT("|--------------------------------------------------------------+\n");
        for (loop = 0; loop < MAX_5QI_VALUE; loop++)
        {
            struct drxConfig_s *pDrxInfo = &pDrxProfile->drxConfigCu5qi[loop];
            if (pDrxInfo->status != EQUIP) continue;
            if (pDrxInfo->selectionOrder == UNKNOWN_SELECTION_ORDER) continue;

            PRINT("|%3d |%15d |%10d | %15d |%20d |%11d |%17d |\n", loop, pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                  pDrxInfo->selectionOrder, pDrxInfo->shortDrxConfigSetup, pDrxInfo->shortCycle,
                  pDrxInfo->shortCycleTimer);
        }

        if (pGnb->drxConfigProfile[profileIdx].drxConfigFlagPerSpid == TRUE)
        {
            PRINT("|+ Spid -------------------------------------------------------+\n");
            PRINT("|Spid| drxConfigSetup | longCycle | shortDrxConfigSetup | shortCycle | shortCycleTimer |\n");
            PRINT("|--------------------------------------------------------------+\n");
            for (loop = 0; loop < MAX_SPID_VALUE; loop++)
            {
                struct drxConfig_s *pDrxInfo = &pDrxProfile->drxEutranSpid[loop];
                if (pDrxInfo->status != EQUIP) continue;

                PRINT("|%3d |%15d |%10d |%20d |%11d |%17d |\n", loop, pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                      pDrxInfo->shortDrxConfigSetup, pDrxInfo->shortCycle, pDrxInfo->shortCycleTimer);
            }
        }

        if (pGnb->drxConfigProfile[profileIdx].drxConfigFlagPerRfsp == TRUE)
        {
            PRINT("|+ Rfsp -------------------------------------------------------+\n");
            PRINT("|Rfsp| drxConfigSetup | longCycle | shortDrxConfigSetup | shortCycle | shortCycleTimer |\n");
            PRINT("|--------------------------------------------------------------+\n");
            for (loop = 0; loop < MAX_5QI_VALUE; loop++)
            {
                struct drxConfig_s *pDrxInfo = &pDrxProfile->drxNgranRfsp[loop];
                if (pDrxInfo->status != EQUIP) continue;

                PRINT("|%3d |%15d |%10d |%20d |%11d |%17d |\n", loop, pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                      pDrxInfo->shortDrxConfigSetup, pDrxInfo->shortCycle, pDrxInfo->shortCycleTimer);
            }
        }

        if( pGnb->drxConfigProfile[profileIdx].drxConfigFlagPer5qiRedCap == TRUE){
            PRINT("|+ NGRAN RedCap-----------------------------------------------+\n");
            PRINT(
                "|5qi | drxConfigSetup | longCycle | selectionOrder | shortDrxConfigSetup | shortCycle | "
                "shortCycleTimer |\n");
            PRINT("|--------------------------------------------------------------+\n");
            for (loop = 0; loop < MAX_5QI_VALUE; loop++)
            {
                struct drxConfig_s *pDrxInfo = &pDrxProfile->drxConfigCu5qiRedCap[loop];
                if (pDrxInfo->status != EQUIP) continue;
                if (pDrxInfo->selectionOrder == UNKNOWN_SELECTION_ORDER) continue;

                PRINT("|%3d |%15d |%10d | %15d |%20d |%11d |%17d |\n", loop, pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                  pDrxInfo->selectionOrder, pDrxInfo->shortDrxConfigSetup, pDrxInfo->shortCycle,
                  pDrxInfo->shortCycleTimer);
            }
        }

        if (pGnb->drxConfigProfile[profileIdx].drxConfigFlagPerRfspRedCap == TRUE)
        {
            PRINT("|+ Rfsp RedCap--------------------------------------------------+\n");
            PRINT("|Rfsp| drxConfigSetup | longCycle | shortDrxConfigSetup | shortCycle | shortCycleTimer |\n");
            PRINT("|--------------------------------------------------------------+\n");
            for (loop = 0; loop < MAX_5QI_VALUE; loop++)
            {
                struct drxConfig_s *pDrxInfo = &pDrxProfile->drxNgranRfspRedCap[loop];
                if (pDrxInfo->status != EQUIP) continue;

                PRINT("|%3d |%15d |%10d |%20d |%11d |%17d |\n", loop, pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                      pDrxInfo->shortDrxConfigSetup, pDrxInfo->shortCycle, pDrxInfo->shortCycleTimer);
            }
        }
        if (pGnb->drxConfigProfile[profileIdx].drxConfigFlagPerServiceGrp== TRUE)
        {
            PRINT("|+ SA Drx Service Configuration --------------------------------------------------+\n");
            PRINT("| index |service index | drxConfigSetup | longCycle | selectionOrder | shortDrxConfigSetup | shortCycle | shortCycleTimer |\n");
            PRINT("|------------------------------------------------------------------------+\n");
            for (loop = 0; loop < MAX_SVC_GRP_CONFIG_ID; loop++)
            {
                struct drxConfig_s *pDrxInfo = &pDrxProfile->drxConfigCuServiceGrpSA[loop];
                if (pDrxInfo->status != EQUIP) continue;

                PRINT("|%3d |%3d |%15d |%10d | %15d |%20d |%11d |%17d |\n", loop,
                    loop ,pDrxInfo->drxConfigSetup, pDrxInfo->longCycle,
                    pDrxInfo->selectionOrder, pDrxInfo->shortDrxConfigSetup,
                    pDrxInfo->shortCycle, pDrxInfo->shortCycleTimer);
            }

            PRINT("|+ ENDC Drx Service Configuration --------------------------------------------------+\n");
            PRINT("| service index | selectionOrder | drxConfigSetup | longCycle | shortDrxConfigSetup | shortCycle | shortCycleTimer |\n");
            PRINT("|------------------------------------------------------------------------+\n");
            for (loop = 0; loop < MAX_SVC_GRP_CONFIG_ID; loop++)
            {
                struct drxConfig_s *pDrxInfo = &pDrxProfile->drxConfigCuServiceGrpENDC[loop];
                if (pDrxInfo->status != EQUIP) continue;

                PRINT("|%3d |%15d |%15d | %10d |%20d |%11d |%17d |\n",
                    loop ,pDrxInfo->selectionOrder, pDrxInfo->drxConfigSetup, 
                    pDrxInfo->longCycle, pDrxInfo->shortDrxConfigSetup,
                    pDrxInfo->shortCycle, pDrxInfo->shortCycleTimer);
            }
        }

    }
    PRINT("+==============================================================+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    return GOOD;
}

int GetQosDrbMappingInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    int loop;
    int sliceInfoIndex;
    int isSliceSupported;
    int plmnInfoIndex;
    int isPlmnSupported;
    dedicatedQosFlowGroup_type *ptDedicatedQosFlowGroup = NULL;
    mappingRule_type *ptMappingRule = NULL;

    PRINT("+=====================================================+\n");
    PRINT("| qos-drb-mapping-configuration information           |\n");
    PRINT("+-----------------------------------------------------+\n");
    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    isSliceSupported = pGnb->cfg.qosDrbMappingConf.isSliceMappingSupported;
    isPlmnSupported = pGnb->cfg.qosDrbMappingConf.isPlmnMappingSupported;
    PRINT("============ GNB_NUM[%d] GNB_ID[%10u] ============\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    PRINT("----------- [ dedicated-qos-flow-group ] -----------\n");
    PRINT(" idx | 5qi | arp-priority-level\n");
    PRINT("+--------------------------------------------------+\n");
    for (loop = 0; loop < MAX_DEDICATED_QOS_FLOW_GROUP_INDEX; loop++)
    {
        ptDedicatedQosFlowGroup = &pGnb->cfg.qosDrbMappingConf.dedicatedQosFlowGroupInfo[loop];
        if (ptDedicatedQosFlowGroup->status != EQUIP) continue;

        PRINT(" %3d | %3d | %12d\n", loop, ptDedicatedQosFlowGroup->qos5qi, ptDedicatedQosFlowGroup->arpPriorityLevel);
    }
    if (isSliceSupported)
    {
        PRINT("------ [ dedicated-qos-flow-group-slice info ] ------\n");
        PRINT("+--------------------------------------------------+\n");
        for (loop = 0; loop < MAX_DEDICATED_QOS_FLOW_GROUP_INDEX; loop++)
        {
            ptDedicatedQosFlowGroup = &pGnb->cfg.qosDrbMappingConf.dedicatedQosFlowGroupInfo[loop];
            if (ptDedicatedQosFlowGroup->status != EQUIP) continue;

            PRINT("------ [ dedicated-qos-flow-group-index  -  %d ] ------\n", loop);
            PRINT("+--------------------------------------------------+\n");
            PRINT(" Slice index | status | sst | sd \n");
            PRINT("+--------------------------------------------------+\n");
            for (sliceInfoIndex = 0; sliceInfoIndex < MAX_SLICE_INFO_PER_DRB; sliceInfoIndex++)
            {
                if (ptDedicatedQosFlowGroup->sliceInfo[sliceInfoIndex].status != EQUIP) continue;

                PRINT("  %8d   | %5d  | %3d | %2d \n", sliceInfoIndex,
                      ptDedicatedQosFlowGroup->sliceInfo[sliceInfoIndex].status,
                      ptDedicatedQosFlowGroup->sliceInfo[sliceInfoIndex].sst,
                      ptDedicatedQosFlowGroup->sliceInfo[sliceInfoIndex].sd);
            }
        }
    }
    if (isPlmnSupported)
    {
        PRINT("------ [ dedicated-qos-flow-group-plmn info ] ------\n");
        PRINT("+--------------------------------------------------+\n");
        for (loop = 0; loop < MAX_DEDICATED_QOS_FLOW_GROUP_INDEX; loop++)
        {
            ptDedicatedQosFlowGroup = &pGnb->cfg.qosDrbMappingConf.dedicatedQosFlowGroupInfo[loop];
            if (ptDedicatedQosFlowGroup->status != EQUIP) continue;

            PRINT("------ [ dedicated-qos-flow-group-index  -  %d ] ------\n", loop);
            PRINT("+--------------------------------------------------+\n");
            PRINT(" Plmn index | status | mcc | mnc \n");
            PRINT("+--------------------------------------------------+\n");
            for (plmnInfoIndex = 0; plmnInfoIndex < MAX_PLMN_INFO_PER_DRB; plmnInfoIndex++)
            {
                if (ptDedicatedQosFlowGroup->plmnInfo[plmnInfoIndex].status != EQUIP) continue;

                PRINT("  %8d   | %5d | [0x%X] | [0x%0X]  \n", plmnInfoIndex,
                      ptDedicatedQosFlowGroup->plmnInfo[plmnInfoIndex].status,
                      ptDedicatedQosFlowGroup->plmnInfo[plmnInfoIndex].plmn.s2.mcc,
                      ptDedicatedQosFlowGroup->plmnInfo[plmnInfoIndex].plmn.s2.mnc);
            }
        }
    }

    PRINT("+---------------- [ mapping-rule ] ----------------+\n");
    PRINT(" idx | 5qi | arp-priority-level | qos-flow-group-id\n");
    PRINT("+--------------------------------------------------+\n");
    for (loop = 0; loop < MAX_MAPPING_RULE_INDEX; loop++)
    {
        ptMappingRule = &pGnb->cfg.qosDrbMappingConf.mappingRuleInfo[loop];
        if (ptMappingRule->status != EQUIP) continue;

        PRINT(" %3d | %3d | %12d       | %10d\n", loop, ptMappingRule->qos5qi, ptMappingRule->arpPriorityLevel,
              ptMappingRule->qosFlowGroupId);
    }
    if (isSliceSupported)
    {
        PRINT("---------- [ mapping - rule slice info ] ---------\n");
        PRINT("+--------------------------------------------------+\n");
        for (loop = 0; loop < MAX_MAPPING_RULE_INDEX; loop++)
        {
            ptMappingRule = &pGnb->cfg.qosDrbMappingConf.mappingRuleInfo[loop];
            if (ptMappingRule->status != EQUIP) continue;

            PRINT("------ [ mapping rule qos flow index  -  %d ] ------\n", loop);
            PRINT("+--------------------------------------------------+\n");
            PRINT(" Slice index | status | sst | sd \n");
            PRINT("+--------------------------------------------------+\n");
            for (sliceInfoIndex = 0; sliceInfoIndex < MAX_SLICE_INFO_PER_DRB; sliceInfoIndex++)
            {
                if (ptMappingRule->sliceInfo[sliceInfoIndex].status != EQUIP) continue;

                PRINT("  %8d   | %5d  | %3d | %2d \n", sliceInfoIndex, ptMappingRule->sliceInfo[sliceInfoIndex].status,
                      ptMappingRule->sliceInfo[sliceInfoIndex].sst, ptMappingRule->sliceInfo[sliceInfoIndex].sd);
            }
        }
    }
    if (isPlmnSupported)
    {
        PRINT("---------- [ mapping - rule plmn info ] ---------\n");
        PRINT("+--------------------------------------------------+\n");
        for (loop = 0; loop < MAX_MAPPING_RULE_INDEX; loop++)
        {
            ptMappingRule = &pGnb->cfg.qosDrbMappingConf.mappingRuleInfo[loop];
            if (ptMappingRule->status != EQUIP) continue;

            PRINT("------ [ mapping rule qos flow index  -  %d ] ------\n", loop);
            PRINT("+--------------------------------------------------+\n");
            PRINT(" Plmn index | status | mcc | mnc \n");
            PRINT("+--------------------------------------------------+\n");
            for (plmnInfoIndex = 0; plmnInfoIndex < MAX_PLMN_INFO_PER_DRB; plmnInfoIndex++)
            {
                if (ptMappingRule->plmnInfo[plmnInfoIndex].status != EQUIP) continue;

                PRINT("  %8d   |%3d | [0x%X] | [0x%0X]  \n", plmnInfoIndex,
                      ptMappingRule->plmnInfo[plmnInfoIndex].status, ptMappingRule->plmnInfo[plmnInfoIndex].plmn.s2.mcc,
                      ptMappingRule->plmnInfo[plmnInfoIndex].plmn.s2.mnc);
            }
        }
    }

    PRINT("+------------------------------------------------+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+=====================================================+\n");

    return GOOD;
}

