/**
 *  @brief Get CRR Interface Cause
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetDbgCrr(int32_t argc, char *argv[])
{
    if (argc < 2)
    {
        PRINT("Usage : get dbg crr <CRR_ID>\n");
        return GOOD;
    }

    uint16_t crrId = CauseXnapMiscEnd;
    crrId = StrUtil::itscp_strtoul<uint16_t>(argv[1]);
    if (crrId >= CauseXnapMiscEnd)
    {
        PRINT("Invalid crrId. Check it once again.\n");
        return GOOD;
    }

    causeInfo_type cause;
    GetInterfaceCause(crrId, &cause.f1Cause, &cause.e1Cause, &cause.x2Cause, &cause.ngCause, &cause.xnCause);

    PRINT("+===============================================+\n");
    PRINT("| CRR : (0x%4x) %s\n", crrId, getCrrName(crrId));
    PRINT("| \t%s\n", getCrrDescription(crrId));
    PRINT("+===============================================+\n");
    PRINT("| Interface Cause\n");
    PRINT("+-----------------------------------------------+\n");
    PRINT("| E1 : (0x%4x) %s\n", cause.e1Cause, getCrrName(cause.e1Cause));
    PRINT("| \t%s\n", getCrrDescription(cause.e1Cause));
    PRINT("| F1 : (0x%4x) %s\n", cause.f1Cause, getCrrName(cause.f1Cause));
    PRINT("| \t%s\n", getCrrDescription(cause.f1Cause));
    PRINT("| NG : (0x%4x) %s\n", cause.ngCause, getCrrName(cause.ngCause));
    PRINT("| \t%s\n", getCrrDescription(cause.ngCause));
    PRINT("| XN : (0x%4x) %s\n", cause.xnCause, getCrrName(cause.xnCause));
    PRINT("| \t%s\n", getCrrDescription(cause.xnCause));
    PRINT("| X2 : (0x%4x) %s\n", cause.x2Cause, getCrrName(cause.x2Cause));
    PRINT("| \t%s\n", getCrrDescription(cause.x2Cause));
    PRINT("+===============================================+\n");

    return GOOD;
}

