/**
 *  @brief Get RedundancyCall
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetRedundancyCall(int32_t argc, char *argv[])
{
    uint32_t callId = 0xFFFFFFFF;
    uint8_t *pRead = NULL;
    uint8_t *pStop = NULL;
    char *inHex = NULL;
    int32_t inVal = 0;

    if (argc < 2)
    {
        PRINT("Usage : Get redundancy call <callId> [hexToCompare]\n");
        return GOOD;
    }

    if (argc == 3)
    {
        inHex = argv[2];
    }

    callId = StrUtil::itscp_strtoul<uint32_t>(argv[1]);
    if (callId >= MAX_CALL_COUNT_PER_CPC)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }

    pRead = (uint8_t *)&(PENVCALL[callId]);
    pStop = (uint8_t *)&(PENVCALL[callId].hoInfo);

    while (pRead < pStop)
    {
        if (argc == 3)  // Compare received hexData with shm data
        {
            if (*inHex == '\0' || *(inHex + 1) == '\0')
            {
                PRINT("Invalid length of Call Ctx Input HexStr\n");
                //       return GOOD;
            }

            if (*inHex <= '9')
            {
                inVal = *inHex - '0';
            }
            else if (*inHex <= 'f')
            {
                inVal = *inHex - 'a' + 10;
            }
            else if (*inHex <= 'F')
            {
                inVal = *inHex - 'A' + 10;
            }
            inVal = inVal << 4;
            ++inHex;
            if (*inHex <= '9')
            {
                inVal |= *inHex - '0';
            }
            else if (*inHex <= 'f')
            {
                inVal |= *inHex - 'a' + 10;
            }
            else if (*inHex <= 'F')
            {
                inVal |= *inHex - 'A' + 10;
            }

            if (*pRead != inVal)
            {
                PRINT("Not Equlas shm(%d)[%02x] <> inHex(%d)[%c%c] at:%ld pos\n", *pRead, *pRead, inVal, *(inHex - 1),
                      *inHex, pRead - (uint8_t *)&(PENVCALL[callId]));
                return GOOD;
            }
            ++inHex;
        }
        else  // Just retrieve shm data
        {
            printf("%02x", *pRead);
        }
        ++pRead;
    }

    return GOOD;
}

/**
 *  @brief Get Mobility Config
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbMobilityConfig(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    // Optional gnb-num parameter.
    int optGnbNum = -1;
    if (argc >= 2)
    {
        optGnbNum = StrUtil::itscp_strtol<int32_t>(argv[1]);
    }

    PRINT("+===============================================+\n");
    PRINT("| MobilityConfigGnb                             +\n");
    PRINT("+-----------------------------------------------+\n");
    uint16_t gnbNum = 0, plmnIdx = 0, svcGroupIdx = 0, sliceIdx = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    const auto &mobConfGnb = pGnb->cfg.gnbMobilityConfig;

    // Filter by optional gnb-num.
    if ((-1 == optGnbNum) || (gnbNum == optGnbNum))
    {
        PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.endcSnReleaseOnPscellChangeMrIgnored);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.endcSnReleaseOnPscellChangeMrIgnoredUnknownPci);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.endcRejectMcgMobWhileWaitingForMnResponse);
        SHOW_VALUE(pGnb->cfg.endcFr2MeasureableSettings.featureEnabled);
        SHOW_VALUE(pGnb->cfg.endcFr2MeasureableSettings.timer);
        SHOW_VALUE(pGnb->cfg.endcForcedRestriction.featureEnabled);
        SHOW_VALUE(pGnb->cfg.endcForcedRestriction.timer);
        SHOW_VALUE(pGnb->cfg.forcedRestriction.featureEnabled);
        SHOW_VALUE(pGnb->cfg.forcedRestriction.timer);
        SHOW_VALUE(pGnb->cfg.restrictHoToOverloadedGnb.featureEnabled);
        SHOW_VALUE(pGnb->cfg.restrictHoToOverloadedGnb.timer);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.allowIntraSnInterPlmnChange);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.endcRejectRequestNoCellAboveThreshold);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pdcpBufferBasedFr2PSCellChange.featureEnabled);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pdcpBufferBasedFr2PSCellChange.threshold);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.callReleaseTimerByUplinkStatusIndication);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.rfspTransmitIratHoSwitch);
        SHOW_VALUE(pGnb->cfg.onlyNrScgStopResume);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.sliceAware.mobilityMode);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.sliceAware.targetSliceAwareEnabled);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.rsrpThresholdForCaAwareByA2); // SVR24A FGR-MC1022 FR120
        SHOW_VALUE(pGnb->cfg.blindRedirectionMode);
        SHOW_VALUE(pGnb->cfg.targetCellBandwidthMode);
        SHOW_VALUE(pGnb->cfg.trafficBasedHoSupport);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.ueBasedCgiReportingForHandoverGbr); // SVR24B FGR-MC1007 FR161
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.ueBasedCgiReportingForEndcPscellChangeGbr);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.saToNsaBorderMobility.saToNsaBorderMobilitySupport); // SVR24B FGR-MC1007 FR161
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.saToNsaBorderMobility.saToNsaEfemtoMobilitySupport); // SVR25B FGR-MC1028 FR230
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.saToNsaBorderMobility.voNRBorderMobilitySupport); //SVR25A FGR-MC1007 FR382
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.saToNsaBorderMobility.blindRedirectionTimer); // SVR24B FGR-MC1007 FR161
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.partialSuccessForMultipleDrbEnabled); // SVR25A FGR-MC1009 FR199
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.interVendorEndcHandoverSupport); // SVR26A FGR-CC5001 FR242, off/on
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.interVendorIntraNrHandoverAllowed); // SVR26A FGR-CC5001 FR242, off/on
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pingPongAvoidanceConfig.pingPongAvoidanceCause); // SVR26A FGR-CC5001 FR242, off/on
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pingPongAvoidanceConfig.useForOnDemandHO);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pingPongAvoidanceConfig.useForTrafficBasedEutraHO);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pingPongAvoidanceConfig.useForMultiCarrierOperation);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pingPongAvoidanceConfig.useForUlStatusBasedMobility);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.pingPongAvoidanceConfig.restrictionTimer);

        // FGR-CC5001 FR189: per frequency PSCell selection thresholds.
        for (int i = 0; i < MAX_ENDC_PSCELL_SELECTION_THRESHOLD_ENTRIES; ++i)
        {
            const auto &endcPscellSelectionThreshold = pGnb->cfg.gnbMobilityConfig.endcPscellSelectionThreshold[i];
            if (EQUIP == endcPscellSelectionThreshold.usage)
            {
                PRINT(" endcPscellSelectionThreshold[%d]: ssbFreq %u, rsrp %u, rsrq %u, sinr %u\n", i,
                      endcPscellSelectionThreshold.ssbFreq, endcPscellSelectionThreshold.thresholdRsrp,
                      endcPscellSelectionThreshold.thresholdRsrq, endcPscellSelectionThreshold.thresholdSinr);
            }
        }

        PRINT("nsaFreqPrioInterFreq\n");
        PRINT("  freqPrioScellToPScellSwitchFlag: %u\n", mobConfGnb.nsaFreqPrioInterFreq.freqPrioScellToPScellSwitchFlag);
        PRINT("  freqPrioPSCellChangeFlag       : %u\n", mobConfGnb.nsaFreqPrioInterFreq.freqPrioPSCellChangeFlag);
        PRINT("  freqA1ActivationFlag           : %u\n", mobConfGnb.nsaFreqPrioInterFreq.freqA1ActivationFlag);
        PRINT("  spidPrioPSCellChangeFlag       : %u\n", mobConfGnb.nsaFreqPrioInterFreq.spidPrioPSCellChangeFlag);

        for (plmnIdx = 0; plmnIdx < MAX_PLMN_INDEX; ++plmnIdx)
        {
            const auto &plmnEntry = mobConfGnb.plmnSupportEntries[plmnIdx];
            if (not plmnEntry.usage)
            {
                continue;
            }
            PRINT("plmnIdx: %u\n", plmnIdx);

            PRINT("  nsaFreqPrioInterFreq\n");
            PRINT("    freqPrioScellToPScellSwitchFlag: %u\n", plmnEntry.nsaFreqPrioInterFreq.freqPrioScellToPScellSwitchFlag);
            PRINT("    freqPrioPSCellChangeFlag       : %u\n", plmnEntry.nsaFreqPrioInterFreq.freqPrioPSCellChangeFlag);
            PRINT("    freqA1ActivationFlag           : %u\n", plmnEntry.nsaFreqPrioInterFreq.freqA1ActivationFlag);
            PRINT("    spidPrioPSCellChangeFlag       : %u\n", plmnEntry.nsaFreqPrioInterFreq.spidPrioPSCellChangeFlag);
        }

        for (svcGroupIdx = 0; svcGroupIdx < MAX_SVC_GRP_DB_NUM; ++svcGroupIdx)
        {
            SvcGrpBasedCfg_type *ptSvcBasedGrp = &pGnb->cfg.svcGrpBasedCfg[svcGroupIdx];
            if (CI_use == ptSvcBasedGrp->usage)
            {
                PRINT(
                    " serviceGroupId: %d\n"
                    "    numOfChoCandidateCell: %d, trafficBasedNrToEutraHOSupport: %d\n"
                    "    nrToEutraHONotAllowed: %d, svcBasedIdleLbAllowed: %d\n"
                    "    timerBasedMrBasedInterRatRedirectionSupport: %d, mrBasedRedirectionTimer: %u\n"
                    "    preventingRfspSpecificDeltaCfg: %d, pccChangeAllowed: %d\n"
                    "    serviceBasedFreqPrioritySupport: %d restrictTrafficBasedNrToEutraHOPerUe: %d\n",
                    svcGroupIdx, ptSvcBasedGrp->numOfChoCandidateCell, ptSvcBasedGrp->trafficBasedNrToEutraHOSupport,
                    ptSvcBasedGrp->nrToEutraHandoverNotAllowed, ptSvcBasedGrp->imlb.svcBasedIdleLbAllowed,
                    ptSvcBasedGrp->timerBasedMrBasedInterRatRedirectionSupport, ptSvcBasedGrp->mrBasedRedirectionTimer,
                    ptSvcBasedGrp->preventingRfspSpecificDeltaCfg, ptSvcBasedGrp->pccChangeAllowed,
                    ptSvcBasedGrp->serviceBasedFreqPrioritySupport, ptSvcBasedGrp->restrictTrafficBasedNrToEutraHOPerUe);
            }
        }
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.sliceAware.specificSliceConfig.usage);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.sliceAware.specificSliceConfig.modeOption);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.sliceAware.specificSliceConfig.mrWaitTimer);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.sliceAware.specificSliceConfig.nrPriorityTimer);
        for (sliceIdx = 0; sliceIdx < MAX_SPECIFIC_SLICE_INFO_ENTRIES; ++sliceIdx)
        {
            if (CI_use == pGnb->cfg.gnbMobilityConfig.sliceAware.specificSliceConfig.sliceInfo[sliceIdx].usage)
            {
                PRINT("    sliceIdx[%d] ssdSt: %d  \n", sliceIdx,
                    pGnb->cfg.gnbMobilityConfig.sliceAware.specificSliceConfig.sliceInfo[sliceIdx].sstSd);
            }
        }

        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.ltmConfig.ltmBlockedTimer);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.ltmConfig.cellSwitchPreparationTimer);
        SHOW_VALUE(pGnb->cfg.gnbMobilityConfig.ltmConfig.cellSwitchTimer);

        PRINT("\n");
        PRINT("+-----------------------------------------------+\n");
    }
    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+===============================================+\n");

    return GOOD;
}

