/**
 *  @brief Get PLMN Index Info
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbPlmnIndexInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+================================================================+\n");
    PRINT("|                       PlmnIndexInfo                            |\n");
    PRINT("+================================================================+\n");
    uint16_t gnbNum, plmnIndex = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    for (plmnIndex = 0; plmnIndex < MAX_PLMN_INDEX; plmnIndex++)
    {
        if (pGnb->plmnIndexInfo[plmnIndex].shmStatus != EQUIP) continue;
        PRINT("+----------------------------------------------------------------+\n");
        PRINT("+========== GNB_NUM[%d] GNB_ID[%10u] PLMN_INDEX[%d] =========+\n", gnbNum, pGnb->globalGnbId.gnbId.id,
              plmnIndex);
        PRINT("mcc[0x%X] / mnc[0x%X] / reserved[0x%X] / longId[0x%0X] \n", pGnb->plmnIndexInfo[plmnIndex].s2.mcc,
              pGnb->plmnIndexInfo[plmnIndex].s2.mnc, pGnb->plmnIndexInfo[plmnIndex].s2.reserved,
              pGnb->plmnIndexInfo[plmnIndex].longId);
        PRINT("+----------------------------------------------------------------+\n");
    }
    PRINT("+================================================================+\n");
    PRINT("+======================= globalGnbId.plmn =======================+\n");
    PRINT("globalGnbId.plmn.s2.mcc [0x%X] \n", pGnb->globalGnbId.plmn.s2.mcc);
    PRINT("globalGnbId.plmn.s2.mnc [0x%X] \n", pGnb->globalGnbId.plmn.s2.mnc);
    PRINT("+================================================================+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+================================================================+\n");

    return GOOD;
}

