int GetStatHoDebugCount(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;
    VccbHoDebugStat_type *pHoDebug;
    pHoDebug = PSTAT->localStat.hoDebugStatInfo;
    uint32_t ulNasOverWriteCnt = 0;
    uint32_t triggerOnDemandRedirection = 0, triggerOnDemandRedirectionFail = 0;
    uint32_t triggerOnDemandMeasReconfig = 0, triggerOnDemandMeasReconfigFail = 0;
    int i = 0;

    PRINT("+=================================================================================================+\n");
    PRINT("| HO Debug Count Info                                                                             |\n");
    PRINT("+=================================================================================================+\n");
    for (i = 0; i < VCCB_CALL_THREAD_NUM; i++)
    {
        ulNasOverWriteCnt += pHoDebug[i].ulNasOverWriteCnt;
        triggerOnDemandRedirection += pHoDebug[i].triggerOnDemandRedirection;
        triggerOnDemandRedirectionFail += pHoDebug[i].triggerOnDemandRedirectionFail;
        triggerOnDemandMeasReconfig += pHoDebug[i].triggerOnDemandMeasReconfig;
        triggerOnDemandMeasReconfigFail += pHoDebug[i].triggerOnDemandMeasReconfigFail;
    }

    SHOW_VALUE(ulNasOverWriteCnt);
    SHOW_VALUE(triggerOnDemandRedirection);
    SHOW_VALUE(triggerOnDemandRedirectionFail);
    SHOW_VALUE(triggerOnDemandMeasReconfig);
    SHOW_VALUE(triggerOnDemandMeasReconfigFail);
    PRINT("+===============================================+=================================================+\n");

    return GOOD;
}

