int GetGnbSupportFreqBandInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    int bandIdx, filterIdx;
    uint16_t gnbNum = 0, noofBandNR = 0, noofBandEUTRA = 0;

    gnbSupportedBandInfo_type *pBandInfo = NULL;
    capabilityRequestFilter_type *pFilterInfo = NULL;

    int addItem = 0;

    PRINT("+==============================================================+\n");
    PRINT("| gNB Supported Frequency Band information (Local)             |\n");
    PRINT("+--------------------------------------------------------------+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("+=============== GNB_NUM[%d] GNB_ID[%10u] ================+\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    pBandInfo = &pGnb->supportedFreqBandInfo;

    PRINT("|** SupportedFreqBand_NUM : %d                         ***|\n", pBandInfo->num);
    PRINT("|+  Cell Supported Band List -----------------------------+\n");
    for (bandIdx = 0; bandIdx < MAX_FREQBAND_FILTER; bandIdx++)
    {
        if (pBandInfo->nrFreqBand[bandIdx] == 0) continue;

        PRINT("|%3d |", pBandInfo->nrFreqBand[bandIdx]);
        addItem++;

        if ((addItem % 10) == 0)
        {
            PRINT("\n");
        }
    }
    PRINT("\n");
    PRINT("+==============================================================+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("\n+==============================================================+\n");
    PRINT("| gNB Capability Request Filter information (YANG)             |\n");
    PRINT("+--------------------------------------------------------------+\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("+=============== GNB_NUM[%d] GNB_ID[%10u] ================+\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    pFilterInfo = &pGnb->capabilityRequestFilter;

    PRINT("|+ NGRAN ------------------------------------------------------+\n");
    PRINT("|+  YANG Filtered Band List -----------------------------------+\n");
    for (filterIdx = 0; filterIdx < MAX_REQUEST_FILTER_NR_BAND; filterIdx++)
    {
        if (pFilterInfo->bandNR[filterIdx].usage != CI_use) continue;

        PRINT("|%3d |", pFilterInfo->bandNR[filterIdx].band);
        addItem++;
        noofBandNR++;

        if ((addItem % 10) == 0)
        {
            PRINT("\n");
        }
    }
    PRINT("|** YANG capabilityRequestFilter_Num : %d                   ***|\n", noofBandNR);
    PRINT("\n");
    addItem = 0;
    PRINT("|+ EUTRAN -----------------------------------------------------+\n");
    PRINT("|+  YANG Filtered Band List -----------------------------------+\n");
    for (filterIdx = 0; filterIdx < MAX_REQUEST_FILTER_EUTRA_BAND; filterIdx++)
    {
        if (pFilterInfo->bandEUTRA[filterIdx].usage != CI_use) continue;
        PRINT("|%3d |", pFilterInfo->bandEUTRA[filterIdx].band);
        addItem++;
        noofBandEUTRA++;

        if ((addItem % 10) == 0)
        {
            PRINT("\n");
        }
    }
    PRINT("|** YANG capabilityRequestFilter_Num : %d                   ***|\n", noofBandEUTRA);
    PRINT("+==============================================================+\n\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    return GOOD;
}

/**
 *  @brief get Neighbor Segmentation Support Information for RRC Segmentation
 *  @param[in] argc
 *  @param[in] argv
 *  @return GOOD
 *  @exception N/A
 */
int GetGnbNbrSegSupportInfo(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    uint16_t gnbNum = 0;

    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

    PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, pGnb->globalGnbId.gnbId.id);
    auto pNodeSegInfo = &pGnb->nodeSegInfo;
    PRINT("+==========================================+\n");
    PRINT("| x2NbrSegInfo                             |\n");
    PRINT("+------------------------------------------+\n");
    uint32_t endPointX2 = 0;
    uint32_t x2NbrSegNodeCnt = 0;
    for (endPointX2 = 0; endPointX2 < MAX_ENB_PER_GNB_CU_CP; endPointX2++)
    {
        if (pNodeSegInfo->x2NbrSegInfo[endPointX2].status != EQUIP) continue;

        PRINT("========== X2NBR_SEG_NODE_NUM[%d] ==========\n", endPointX2);
        PRINT(" ENB_ID[%7u]   MCC[%3x]   MNC[%3x]======\n", pNodeSegInfo->x2NbrSegInfo[endPointX2].nodeId,
              pNodeSegInfo->x2NbrSegInfo[endPointX2].nodePlmn.s2.mcc,
              ((pNodeSegInfo->x2NbrSegInfo[endPointX2].nodePlmn.s2.mnc & 0x0F) == 0x0F)
                  ? static_cast<uint32_t>(pNodeSegInfo->x2NbrSegInfo[endPointX2].nodePlmn.s2.mnc >> 4)
                  : pNodeSegInfo->x2NbrSegInfo[endPointX2].nodePlmn.s2.mnc);
        PRINT("============================================\n");
        PRINT("|\n");
        x2NbrSegNodeCnt++;
    }
    if (!x2NbrSegNodeCnt)
    {
        PRINT("x2NbrSegInfo Not Exist\n");
    }

    PRINT("+==========================================+\n");
    PRINT("| xnNbrSegInfo                             |\n");
    PRINT("+------------------------------------------+\n");
    uint16_t xnNbrIdx = 0;
    uint32_t xnNbrSegNodeCnt = 0;
    for (xnNbrIdx = 0; xnNbrIdx < MAX_XN_NBR_PER_GNB; xnNbrIdx++)
    {
        if (pNodeSegInfo->xnNbrSegInfo[xnNbrIdx].status != EQUIP) continue;

        PRINT("========== XnNBR_SEG_NODE_NUM[%d] ==========\n", xnNbrIdx);
        PRINT(" GNB_ID[%10u]   MCC[%3x]   MNC[%3x]====\n", pNodeSegInfo->xnNbrSegInfo[xnNbrIdx].nodeId,
              pNodeSegInfo->xnNbrSegInfo[xnNbrIdx].nodePlmn.s2.mcc,
              ((pNodeSegInfo->xnNbrSegInfo[xnNbrIdx].nodePlmn.s2.mnc & 0x0F) == 0x0F)
                  ? static_cast<uint32_t>(pNodeSegInfo->xnNbrSegInfo[xnNbrIdx].nodePlmn.s2.mnc >> 4)
                  : pNodeSegInfo->xnNbrSegInfo[xnNbrIdx].nodePlmn.s2.mnc);
        PRINT("============================================\n");
        PRINT("|\n");
        xnNbrSegNodeCnt++;
    }
    if (!xnNbrSegNodeCnt)
    {
        PRINT("xnNbrSegInfo Not Exist\n");
    }

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    return GOOD;
}

