int8_t checkEndcInterFrequencyMeasurement(reportConfigurationBaseDb_type *p, const MeasObjectDebugFlag *pDbg,
                                          uint16_t cellNum)
{
    if (p == NULL) return ERROR;
    if (pDbg == NULL) return ERROR;
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;

    const VccbCellInfo_type *pCell = &PCELLINFO[cellNum];
    const VccbCellInfo_type *pTargetCell = &PCELLINFO[cellNum];

    // option t
    if (OPT_PRESENT == pDbg->m.targetCellNumPresent)
    {
        if (pDbg->targetCellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;
        pTargetCell = &PCELLINFO[pDbg->targetCellNum];
    }

    uint8_t index = 0;
    bool interFrequencyStatus = false;
    bool hoStatus = false;
    uint8_t nrPSCellChangeEvent = 0;  // A3:0, A5:1, A4:2 (enumNRPSCellChangeEventType)
    uint16_t objIdx = 0;
    PRINT("\n");

    for (objIdx = 0; MAX_NR_OF_OBJECT_ID_DB - 1 > objIdx; objIdx++)
    {
        const measurementObjectNRBaseDb_type *ptMO = &pCell->measurementsData.measurementObjectsNRDb[objIdx].base;
        interFrequencyStatus = false;
        hoStatus = false;

        if (CI_use != ptMO->usage)
        {
            continue;
        }

        // option t (Check only the frequency of target cell)
        if ((OPT_PRESENT == pDbg->m.targetCellNumPresent) && (ptMO->ssbFrequency != pTargetCell->ssbArfcn))
        {
            continue;
        }

        nrPSCellChangeEvent = ptMO->nrPSCellChangeEvent;
        for (index = 0; index < MAX_NR_OF_REPORT_CONFIG_ID_DB; index++)
        {
            const reportConfigurationBaseDb_type *pTarget = &pCell->measurementsData.reportConfigurationsDb[index].base;
            if (pTarget->usage != CI_use) continue;

            switch (pTarget->reportType)
            {
                // A1: Check a1Purpose_deactivateInterFrequency when source is a2Purpose_activateInterFrequency
                // A2: Check a2Purpose_activateInterFrequency when source is a1Purpose_deactivateInterFrequency
                case measReport_A1:
                {
                    if (a1Purpose_deactivateInterFrequency == pTarget->reportPurpose)
                    {
                        if ((measReport_A2 == p->reportType) && (a2Purpose_activateInterFrequency == p->reportPurpose))
                        {
                            interFrequencyStatus = true;
                        }
                    }
                    break;
                }
                case measReport_A2:
                {
                    if (a2Purpose_activateInterFrequency == pTarget->reportPurpose)
                    {
                        if ((measReport_A1 == p->reportType) &&
                            (a1Purpose_deactivateInterFrequency == p->reportPurpose))
                        {
                            interFrequencyStatus = true;
                        }
                    }
                    break;
                }
                // A3, A4, A5 : Check reportPurpose and nrPSCellChangeEvent.
                case measReport_A3:
                {
                    if ((a3Purpose_NRPSCellChange == pTarget->reportPurpose) &&
                        (PSCellChange_EventA3 == nrPSCellChangeEvent))
                    {
                        hoStatus = true;
                    }
                    break;
                }
                case measReport_A4:
                {
                    if ((a4Purpose_NRPSCellChange == pTarget->reportPurpose) &&
                        (PSCellChange_EventA4 == nrPSCellChangeEvent))
                    {
                        hoStatus = true;
                    }
                    break;
                }
                case measReport_A5:
                {
                    if ((a5Purpose_NRPSCellChange == pTarget->reportPurpose) &&
                        (PSCellChange_EventA5 == nrPSCellChangeEvent))
                    {
                        hoStatus = true;
                    }
                    break;
                }
                default:
                    break;
            }
        }

        if ((true == interFrequencyStatus) && (true == hoStatus))
        {
            PRINT("%s[OK] MO(idx:%d, ssbFreq:%d)%s\n", VCCB_C_GREEN, objIdx, ptMO->ssbFrequency, VCCB_C_RESET);
        }
        else if ((true == interFrequencyStatus) && (false == hoStatus))
        {
            PRINT(
                "%s[NOK] MO(idx:%d, ssbFreq:%d) Check: en-dc-nr-pscell-change-purpose and "
                "nr-pscell-change-event-type(%d)%s\n",
                VCCB_C_RED, objIdx, ptMO->ssbFrequency, nrPSCellChangeEvent, VCCB_C_RESET);
        }
        else if ((false == interFrequencyStatus) && (true == hoStatus))
        {
            PRINT("%s[NOK] MO(idx:%d, ssbFreq:%d) Check: a1/a2 de/activateInterFrequency%s\n", VCCB_C_RED, objIdx,
                  ptMO->ssbFrequency, VCCB_C_RESET);
        }
        else  // false, false
        {
            PRINT(
                "%s[NOK] MO(idx:%d, ssbFreq:%d) Check: a1/a2 de/activateInterFrequency, "
                "en-dc-nr-pscell-change-purpose, nr-pscell-change-event-type(%d)%s\n",
                VCCB_C_RED, objIdx, ptMO->ssbFrequency, nrPSCellChangeEvent, VCCB_C_RESET);
        }
    }

    return GOOD;
}

int8_t checkEndcFreqPriorPscellChangeMeasurement(reportConfigurationBaseDb_type *p, const MeasObjectDebugFlag *pDbg,
                                                 uint16_t cellNum)
{
    if (p == NULL) return ERROR;
    if (pDbg == NULL) return ERROR;
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;

    const VccbCellInfo_type *pCell = &PCELLINFO[cellNum];
    const VccbCellInfo_type *pTargetCell = &PCELLINFO[cellNum];

    if (pCell->gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB) return ERROR;
    const VccbGnbInfo_type *pGnb = &PGNBINFO[pCell->gnbNum];

    // option t
    if (OPT_PRESENT == pDbg->m.targetCellNumPresent)
    {
        if (pDbg->targetCellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;
        pTargetCell = &PCELLINFO[pDbg->targetCellNum];
    }

    const auto &mobConfGnb = pGnb->cfg.gnbMobilityConfig;
    bool freqPrioPSCellChangeFlag = mobConfGnb.nsaFreqPrioInterFreq.freqPrioPSCellChangeFlag;

    uint8_t intraFreqPrio = 0, objFreqPrio = 0;
    uint8_t freqPrioPSCellChangeEvent = fpInterFreqPscellChange_EventA4;
    uint8_t reportType = (uint8_t)(p->reportType - 4);  // A4:0, A5:1
    bool plmnStatus = false;
    uint8_t plmnIdx = 0;
    uint16_t objIdx = 0;

    PRINT("\n");

    for (plmnIdx = 0; plmnIdx < MAX_PLMN_INDEX; plmnIdx++)
    {
        const plmnIdInfo_type *pGnbPlmn = &pGnb->plmnIndexInfo[plmnIdx];

        if (pGnbPlmn->shmStatus == EQUIP)
        {
            plmnStatus = true;

            const auto &plmnEntry = mobConfGnb.plmnSupportEntries[plmnIdx];
            if (plmnEntry.usage)
            {
                freqPrioPSCellChangeFlag = plmnEntry.nsaFreqPrioInterFreq.freqPrioPSCellChangeFlag; // mobility-config-gnb/plmn-support-entries
            }

            if (not freqPrioPSCellChangeFlag)
            {
                PRINT("%s[NOK] plmnIdx(%d), Check fp-based-inter-frequency-pscell-change-enabled%s\n", VCCB_C_RED,
                     plmnIdx, VCCB_C_RESET);
                continue;
            }

            if (CI_use == pCell->measurementsData.measurementObjectsNRDb[INTRAFREQ_OBJECT_IDX]
                              .extension.plmnBasedControl.plmn[plmnIdx]
                              .usage)
            {
                intraFreqPrio = pCell->measurementsData.measurementObjectsNRDb[INTRAFREQ_OBJECT_IDX]
                                    .extension.plmnSpecific[plmnIdx]
                                    .freqPriorityForEndc;
            }

            for (objIdx = 0; MAX_NR_OF_OBJECT_ID_DB - 1 > objIdx; objIdx++)
            {
                const measurementObjectNRBaseDb_type *ptMO =
                    &pCell->measurementsData.measurementObjectsNRDb[objIdx].base;
                const measurementObjectNRExtensionDb_type *ptMOControl =
                    &pCell->measurementsData.measurementObjectsNRDb[objIdx].extension;

                if (CI_use != ptMO->usage)
                {
                    continue;
                }

                // option t (Check only the frequency of target cell)
                if ((OPT_PRESENT == pDbg->m.targetCellNumPresent) && (ptMO->ssbFrequency != pTargetCell->ssbArfcn))
                {
                    continue;
                }

                if (CI_use != ptMOControl->plmnBasedControl.plmn[plmnIdx].usage)
                {
                    PRINT("%s[NOK] plmnIdx(%d),MO(idx:%d, ssbFreq:%d), Check plmn-support-entries%s\n", VCCB_C_RED,
                          plmnIdx, objIdx, ptMO->ssbFrequency, VCCB_C_RESET);
                    continue;
                }

                objFreqPrio = ptMOControl->plmnSpecific[plmnIdx].freqPriorityForEndc;
                if (objFreqPrio > intraFreqPrio)
                {
                    freqPrioPSCellChangeEvent = ptMOControl->plmnSpecific[plmnIdx].fpInterFreqPscellChangeEvent;
                    if (reportType == freqPrioPSCellChangeEvent)
                    {
                        PRINT("%s[OK] plmnIdx(%d), MO(idx:%d, ssbFreq:%d): targetFP(%d) > servingFP(%d) %s\n",
                              VCCB_C_GREEN, plmnIdx, objIdx, ptMO->ssbFrequency, objFreqPrio, intraFreqPrio,
                              VCCB_C_RESET);
                    }
                    else
                    {
                        PRINT(
                            "%s[NOK] plmnIdx(%d), MO(idx:%d, ssbFreq:%d): Check "
                            "en-dc-fp-inter-frequency-nr-pscell-change-event-type%s\n",
                            VCCB_C_RED, plmnIdx, objIdx, ptMO->ssbFrequency, VCCB_C_RESET);
                    }
                }
                else
                {
                    PRINT("%s[NOK] plmnIdx(%d), MO(idx:%d, ssbFreq:%d): targetFP(%d) <= servingFP(%d)%s\n", VCCB_C_RED,
                          plmnIdx, objIdx, ptMO->ssbFrequency, objFreqPrio, intraFreqPrio, VCCB_C_RESET);
                }
            }
        }
    }

    if (false == plmnStatus)
    {
        PRINT("%s[NOK] Check plmn-index-info %s\n", VCCB_C_RED, VCCB_C_RESET);
    }

    return GOOD;
}


int8_t checkSaPcellPriorHandoverMeasurement(reportConfigurationBaseDb_type *p, const MeasObjectDebugFlag *pDbg,
                                                 uint16_t cellNum)
{
    if (p == NULL) return ERROR;
    if (pDbg == NULL) return ERROR;
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;

    const VccbCellInfo_type *pCell = &PCELLINFO[cellNum];
    const VccbCellInfo_type *pTargetCell = &PCELLINFO[cellNum];

    if (pCell->gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB) return ERROR;
    const VccbGnbInfo_type *pGnb = &PGNBINFO[pCell->gnbNum];

    // option t
    if (OPT_PRESENT == pDbg->m.targetCellNumPresent)
    {
        if (pDbg->targetCellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;
        pTargetCell = &PCELLINFO[pDbg->targetCellNum];
    }

    uint8_t freqPriMobilitySupport = pCell->fpMobilityControl.freqPriMobilitySupport; // frequency-priority-based-mobility/frequency-priority-based-mobility-control-support
    uint8_t pcellFreqPrioritizationHoSupport = pCell->fpMobilityControl.pcellFreqPrioritizationHoSupport; // frequency-priority-based-mobility/pcell-freq-prioritization-handover-support

    uint8_t intraFreqPrio = 0, objFreqPrio = 0;
    uint8_t pcellFreqPriorityHandoverEvent = pcellFreqPriorityHandover_EventA4;
    uint8_t reportType = (uint8_t)(p->reportType - 4);  // A4:0, A5:1
    bool plmnStatus = false;
    uint8_t plmnIdx = 0;
    uint16_t objIdx = 0;

    PRINT("\n");

    for (plmnIdx = 0; plmnIdx < MAX_PLMN_INDEX; plmnIdx++)
    {
        const plmnIdInfo_type *pGnbPlmn = &pGnb->plmnIndexInfo[plmnIdx];

        if (pGnbPlmn->shmStatus == EQUIP)
        {
            plmnStatus = true;

            if (FALSE == freqPriMobilitySupport)
            {
                PRINT("%s[NOK] plmnIdx(%d), Check frequency-priority-based-mobility-control-support%s\n", VCCB_C_RED,
                      plmnIdx, VCCB_C_RESET);
                continue;
            }

            if (FALSE == pcellFreqPrioritizationHoSupport)
            {
                PRINT("%s[NOK] plmnIdx(%d), Check pcell-freq-prioritization-handover-support%s\n", VCCB_C_RED,
                      plmnIdx, VCCB_C_RESET);
                continue;
            }

            if (CI_use == pCell->measurementsData.measurementObjectsNRDb[INTRAFREQ_OBJECT_IDX]
                              .extension.plmnBasedControl.plmn[plmnIdx]
                              .usage)
            {
                intraFreqPrio = pCell->measurementsData.measurementObjectsNRDb[INTRAFREQ_OBJECT_IDX]
                                    .extension.plmnSpecific[plmnIdx]
                                    .freqPriorityForSa;
            }

            for (objIdx = 0; MAX_NR_OF_OBJECT_ID_DB - 1 > objIdx; objIdx++)
            {
                const measurementObjectNRBaseDb_type *ptMO =
                    &pCell->measurementsData.measurementObjectsNRDb[objIdx].base;
                const measurementObjectNRExtensionDb_type *ptMOControl =
                    &pCell->measurementsData.measurementObjectsNRDb[objIdx].extension;

                if (CI_use != ptMO->usage)
                {
                    continue;
                }

                // option t (Check only the frequency of target cell)
                if ((OPT_PRESENT == pDbg->m.targetCellNumPresent) && (ptMO->ssbFrequency != pTargetCell->ssbArfcn))
                {
                    continue;
                }

                if (CI_use != ptMOControl->plmnBasedControl.plmn[plmnIdx].usage)
                {
                    PRINT("%s[NOK] plmnIdx(%d),MO(idx:%d, ssbFreq:%d), Check plmn-support-entries%s\n", VCCB_C_RED,
                          plmnIdx, objIdx, ptMO->ssbFrequency, VCCB_C_RESET);
                    continue;
                }

                objFreqPrio = ptMOControl->plmnSpecific[plmnIdx].freqPriorityForSa;
                if (objFreqPrio > intraFreqPrio)
                {
                    pcellFreqPriorityHandoverEvent = ptMO->pcellFreqPriHoEvent;
                    if (reportType == pcellFreqPriorityHandoverEvent)
                    {
                        PRINT("%s[OK] plmnIdx(%d), MO(idx:%d, ssbFreq:%d): targetFP(%d) > servingFP(%d) %s\n",
                              VCCB_C_GREEN, plmnIdx, objIdx, ptMO->ssbFrequency, objFreqPrio, intraFreqPrio,
                              VCCB_C_RESET);
                    }
                    else
                    {
                        PRINT(
                            "%s[NOK] plmnIdx(%d), MO(idx:%d, ssbFreq:%d): Check "
                            "pcell-freq-prioritization-handover-event-type%s\n",
                            VCCB_C_RED, plmnIdx, objIdx, ptMO->ssbFrequency, VCCB_C_RESET);
                    }
                }
                else
                {
                    PRINT("%s[NOK] plmnIdx(%d), MO(idx:%d, ssbFreq:%d): targetFP(%d) <= servingFP(%d)%s\n", VCCB_C_RED,
                          plmnIdx, objIdx, ptMO->ssbFrequency, objFreqPrio, intraFreqPrio, VCCB_C_RESET);
                }
            }
        }
    }

    if (false == plmnStatus)
    {
        PRINT("%s[NOK] Check plmn-index-info %s\n", VCCB_C_RED, VCCB_C_RESET);
    }

    return GOOD;
}

const char *FnITSCP_GetValidResult_ReportConfigNR(reportConfigurationBaseDb_type *p, const MeasObjectDebugFlag *pDbg,
                                                  uint16_t cellNum)
{
    if (p == NULL) return CHECKER_ERROR_RETURN("NULL");
    if (pDbg == NULL) return CHECKER_ERROR_RETURN("NULL");
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return CHECKER_ERROR_RETURN("MAX_CELL_NUM_ITSCP_VCCB");

    // TODO
    uint8_t reportType = p->reportType;
    uint8_t reportPurpose = p->reportPurpose;
    int8_t status = GOOD;

    if (measReport_A1 == reportType)
    {
        switch (reportPurpose)
        {
            case a1Purpose_deactivateInterFrequency:
            {
                return CHECKER_GOOD_RETURN("Same with A2_activateInterFrequency");
            }
            default:
                break;
        }
    }
    else if (measReport_A2 == reportType)
    {
        switch (reportPurpose)
        {
            case a2Purpose_activateInterFrequency:
            {
                status = checkEndcInterFrequencyMeasurement(p, pDbg, cellNum);
                if(ERROR == status) return CHECKER_ERROR_RETURN("NOK");
                return CHECKER_GOOD_RETURN("");
            }
            default:
                break;
        }
    }
    else if (measReport_A3 == reportType)
    {
        switch (reportPurpose)
        {
            default:
                break;
        }
    }
    else if (measReport_A4 == reportType)
    {
        switch (reportPurpose)
        {
            case a4Purpose_FreqPrioPSCellChange:
            {
                status = checkEndcFreqPriorPscellChangeMeasurement(p, pDbg, cellNum);
                if(ERROR == status) return CHECKER_ERROR_RETURN("NOK");
                return CHECKER_GOOD_RETURN("");
            }
            case a4Purpose_PcellPriorHandover:
            {
                status = checkSaPcellPriorHandoverMeasurement(p, pDbg, cellNum);
                if(ERROR == status) return CHECKER_ERROR_RETURN("NOK");
                return CHECKER_GOOD_RETURN("");
            }
            default:
                break;
        }
    }
    else if (measReport_A5 == reportType)
    {
        switch (reportPurpose)
        {
            case a5Purpose_FreqPrioPSCellChange:
            {
                status = checkEndcFreqPriorPscellChangeMeasurement(p, pDbg, cellNum);
                if(ERROR == status) return CHECKER_ERROR_RETURN("NOK");
                return CHECKER_GOOD_RETURN("");
            }
            case a5Purpose_PcellPriorHandover:
            {
                status = checkSaPcellPriorHandoverMeasurement(p, pDbg, cellNum);
                if(ERROR == status) return CHECKER_ERROR_RETURN("NOK");
                return CHECKER_GOOD_RETURN("");
            }
            default:
                break;
        }
    }

    return CHECKER_GOOD_RETURN("OK");
}

const char *FnITSCP_GetValidResult_ReportConfigEUTRA(reportConfigurationBaseDb_type *p, const MeasObjectDebugFlag *pDbg,
                                                  uint16_t cellNum)
{
    if (p == NULL) return CHECKER_ERROR_RETURN("NULL");
    if (pDbg == NULL) return CHECKER_ERROR_RETURN("NULL");
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return CHECKER_ERROR_RETURN("MAX_CELL_NUM_ITSCP_VCCB");

    return CHECKER_GOOD_RETURN("OK");
}

