// This function provides the information of  plmnIndexInfo for specific gnbNum
void FnITSCP_PrintGnbPlmnIndexInfo(const int gnbNum)
{
    if (gnbNum >= MAX_GNB_PER_SYS_ITSCP_VCCB) return;

    const VccbGnbInfo_type *pGnb = &PGNBINFO[gnbNum];

    int plmnIdx;
    for (plmnIdx = 0; plmnIdx < MAX_PLMN_INDEX; plmnIdx++)
    {
        const plmnIdInfo_type *pGnbPlmn = &pGnb->plmnIndexInfo[plmnIdx];
        if (pGnbPlmn->shmStatus == EQUIP)
        {
            PRINT("%d %06x(%d) ", plmnIdx, pGnbPlmn->longId, pGnbPlmn->longId);
        }
    }
    PRINT("\n");
}

/**
 * @brief      get report type and purpose from changeEvent of MeasObj
 * @param      event : changeEvent of MeasObj (in)
 * @param      serviceType : 0 - EN, 1 - NR, 2 - SA (in)
 * @param      type : report type (out)
 * @param      purpose : report purpose (out)
 */
void FnITSCP_GetTypeAndPurposeFromMoEvent(uint8_t event, uint8_t serviceType, uint8_t *type, uint8_t *purpose)
{
    if (serviceType >= SERVICE_TYPE_MAX) return;
    if (type == NULL) return;
    if (purpose == NULL) return;

    uint8_t reportPurposeTable_A3[SERVICE_TYPE_MAX] = {a3Purpose_NRPSCellChange, a3Purpose_nrdcNrPSCellChange,
                                                       a3Purpose_intraNrHandover};

    uint8_t reportPurposeTable_A4[SERVICE_TYPE_MAX] = {a4Purpose_NRPSCellChange, a4Purpose_nrdcNrPSCellChange,
                                                       a4Purpose_intraNrHandover};

    uint8_t reportPurposeTable_A5[SERVICE_TYPE_MAX] = {a5Purpose_NRPSCellChange, a5Purpose_nrdcNrPSCellChange,
                                                       a5Purpose_intraNrHandover};

    switch (event)
    {
        case 0:  // PSCellChange_EventA3, IntraNrHandover_EventA3
            *type = measReport_A3;
            *purpose = reportPurposeTable_A3[serviceType];
            break;

        case 1:  // PSCellChange_EventA5, IntraNrHandover_EventA5
            *type = measReport_A5;
            *purpose = reportPurposeTable_A5[serviceType];
            break;

        case 2:  // PSCellChange_EventA4, IntraNrHandover_EventA4
            *type = measReport_A4;
            *purpose = reportPurposeTable_A4[serviceType];
            break;

        default:
            break;
    }
}

void FnITSCP_GetTypeAndPurposeFromEutraMoEvent(uint8_t event, uint8_t serviceType, uint8_t *type, uint8_t *purpose)
{
    if (serviceType >= SERVICE_EUTRA_TYPE_MAX) return;
    if (type == NULL) return;
    if (purpose == NULL) return;

    uint8_t reportPurposeTable_B1[SERVICE_EUTRA_TYPE_MAX] = {b1Purpose_eutraHandover, b1Purpose_trafficBasedHandover,
                                                       b1Purpose_loadBalancingIratHandover};

    uint8_t reportPurposeTable_B2[SERVICE_EUTRA_TYPE_MAX] = {b2Purpose_eutraHandover, b2Purpose_trafficBasedHandover,
                                                       b2Purpose_loadBalancingIratHandover};

    switch (event)
    {
        case 0:  // InterRatHandover_EventB1, trafficBasedHandover_EventB1, InterRatHandover_EventB1
            *type = measReport_B1Eutra;
            *purpose = reportPurposeTable_B1[serviceType];
            break;

        case 1:  // InterRatHandover_EventB2, trafficBasedHandover_EventB2, InterRatHandover_EventB2
            *type = measReport_B2Eutra;
            *purpose = reportPurposeTable_B2[serviceType];
            break;

        default:
            break;
    }
}

/**
 * @brief      check if changeEvent of MeasObj is in ReportConfig
 * @param      measIdx : DB index of MeasObj
 * @param      event : changeEvent of MeasObj
 * @param      serviceType : 0 - EN, 1 - NR, 2 - SA
 * @param      pReportConfig : pointer of ReportConfig
 * @return     true : match changeEvent and ReportConfig
 * @return     false : not match changeEvent and ReportConfig
 */
bool FnITSCP_CompareMoEventWithRc(uint16_t measIdx, uint8_t event, uint8_t serviceType,
                                 reportConfigurationBaseDb_type *pReportConfig, enumServiceRatType type)
{
    if (pReportConfig == NULL) return false;

    uint8_t reportType = 0xFF;
    uint8_t reportPurpose = 0xFF;

    if (type == SERVICE_TYPE_NR)
        FnITSCP_GetTypeAndPurposeFromMoEvent(event, serviceType, &reportType, &reportPurpose);
    else
        FnITSCP_GetTypeAndPurposeFromEutraMoEvent(event, serviceType, &reportType, &reportPurpose);

    if (reportType != pReportConfig->reportType) return false;

    if (reportPurpose != pReportConfig->reportPurpose) return false;

    if (!GETBIT_U32(pReportConfig->measObjectSelection, measIdx)) return false;

    return true;
}

// This function provides a function to output summary information for MeasObject configuration failure and Target Cell
// Selection failure.
void FnITSCP_PrintMeasObjectNR_Summary(uint16_t cellNum, const MeasObjectDebugFlag *pDbg)
{
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return;
    if (pDbg == NULL) return;

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    uint16_t measIdx = 0;

    // -------------------------------------------------------------------------------------------------------------
    // | idx | ssbFreq | changeEvent         | SaCapa | opSmtc | smtc1       | cbrs | bandList   | moPrio | Result | freq priority:idx[SA,ENDC] ...
    // -------------------------------------------------------------------------------------------------------------
    // |   1 |    1350 | EN:A5/ NR:A3/ SA:A5 | true   | false  | P:0 O:0 D:0 | ---- | n:3 [   1] |      0 | OK     |
    // |  20 |    1250 | EN:A3/ NR:A3/ SA:A3 | true   | false  | P:0 O:0 D:0 | ---- | n:3 [   1] |      0 | OK     |
    // -------------------------------------------------------------------------------------------------------------

    PRINT(
        "| idx | ssbFreq | changeEvent         | SaCapa | opSmtc | smtc1       | cbrs | bandList   | moPrio | "
        "Result | freq priority:idx[SA,ENDC] ...\n");
    FnITSCP_PrintLine();

    for (measIdx = 0; measIdx < MAX_NR_OF_OBJECT_ID_DB; measIdx++)
    {
        bool isCbrsBand = false;
        uint64_t loop = 0;
        measurementObjectNRBaseDb_type *p = &pCell->measurementsData.measurementObjectsNRDb[measIdx].base;
        measurementObjectNRExtensionDb_type *pExt = &pCell->measurementsData.measurementObjectsNRDb[measIdx].extension;

        if (p->usage != CI_use) continue;
        // +-----------------------------------------------------------------
        // |  0  | 641664  | EN:A3/ NR:A3/ SA:A3 | 1      |  0ff   | p:2 o:5 d:0 |  -   | n:1 [ 48 ]

        // pre
        for (loop = 0; loop < MAX_MEAS_FREQ_BAND_COMMON_NR_EUTRA; loop++)
        {
            if ((CI_use == p->freqBandIndicatorDbList.freqBand[loop].usage) &&
                (CBRS_BAND == p->freqBandIndicatorDbList.freqBand[loop].band))
            {
                isCbrsBand = true;
                break;
            }
        }

        // idx
        PRINT("| %3u ", measIdx);

        // ssbFreq - Indicates the frequency of MO.
        PRINT("| %7u ", p->ssbFrequency);

        // changeEvent - It indicates the event for SPCell change.
        PRINT("| EN:%s/ ", FnITSCP_GetHandoverEventString(p->nrPSCellChangeEvent));
        PRINT("NR:%s/ ", FnITSCP_GetHandoverEventString(p->nrdcPSCellChangeEvent));
        PRINT("SA:%s ", FnITSCP_GetHandoverEventString(p->intraNrHandoverEvent));

        uint8_t checkEvent = 0; // 2^0 : EN, 2^1 : NR, 2^2 : SA
        for (uint16_t index = 0; index < MAX_NR_OF_REPORT_CONFIG_ID_DB; index++)
        {
            reportConfigurationBaseDb_type *pReportConfig = &pCell->measurementsData.reportConfigurationsDb[index].base;

            if (pReportConfig->usage != CI_use) continue;

            if (!GETBIT_U8(checkEvent, SERVICE_TYPE_ENDC) &&
                FnITSCP_CompareMoEventWithRc(measIdx, p->nrPSCellChangeEvent, SERVICE_TYPE_ENDC, pReportConfig, SERVICE_TYPE_NR) == true)
                checkEvent |= (1 << SERVICE_TYPE_ENDC);

            if (!GETBIT_U8(checkEvent, SERVICE_TYPE_NRDC) &&
                FnITSCP_CompareMoEventWithRc(measIdx, p->nrdcPSCellChangeEvent, SERVICE_TYPE_NRDC, pReportConfig, SERVICE_TYPE_NR) == true)
                checkEvent |= (1 << SERVICE_TYPE_NRDC);

            if (!GETBIT_U8(checkEvent, SERVICE_TYPE_SA) &&
                FnITSCP_CompareMoEventWithRc(measIdx, p->intraNrHandoverEvent, SERVICE_TYPE_SA, pReportConfig, SERVICE_TYPE_NR) == true)
                checkEvent |= (1 << SERVICE_TYPE_SA);

            if (checkEvent == e_BitMask_3bit) break;
        }

        // SaCapable - Indicates whether SA is supported.
        PRINT("| %-6s ", p->saCapable ? "true" : "false");

        // opSmtc - Indicates whether SMTC1 comparison is performed.
        PRINT("| %-6s ", (p->operatorConfiguredSmtc1 ? "true" : "false"));

        // smtc1 - Indicates information about SMTC1.
        PRINT("| P:%u O:%u D:%u ", p->smtc1.periodicityAndOffset.periodicity, p->smtc1.periodicityAndOffset.offset,
              p->smtc1.duration);

        // cbrs - In case of CBRS band, it indicates whether to use CBRS MO.
        if (isCbrsBand == false)
        {
            PRINT("| %-4s ", "----");
        }
        else
        {
            PRINT("| %-4s ", (p->cbrsEnabled) ? "on" : "off");
        }

        // bandList - Indicates the band information supported by the MO.
        int nrOfBands = 0, firstBand = 0;
        for (freqBand_type &rFreqBand: p->freqBandIndicatorDbList.freqBand)
        {
            if (CI_use != rFreqBand.usage)
            {
                continue;
            }
            if (0 == firstBand)
            {
                firstBand = rFreqBand.band;
            }
            ++nrOfBands;
        }
        PRINT("| n:%u [%4u] ", nrOfBands, firstBand);

        // moPriority
        PRINT("| %6u ", p->moPriority);

        // Result
        PRINT("| %-6s ", FnITSCP_GetValidResult_MeasObjectNR(p, pDbg, measIdx));

        // freq priority
        PRINT("|");
        int plmnIdx;
        for (plmnIdx = 0; plmnIdx < MAX_PLMN_INDEX; plmnIdx++)
        {
            if (CI_use != pExt->plmnBasedControl.plmn[plmnIdx].usage) continue;

            PRINT("%d[%2d,%2d] ", plmnIdx, pExt->plmnSpecific[plmnIdx].freqPriorityForSa, pExt->plmnSpecific[plmnIdx].freqPriorityForEndc);
        }

        // line end
        PRINT("\n");

        if (checkEvent < e_BitMask_3bit)
        {
            if (!GETBIT_U8(checkEvent, SERVICE_TYPE_ENDC))
            {
                PRINT("\t\t %sThere is no report type for ENDC-SN %s\n", VCCB_C_RED, VCCB_C_RESET);
            }

            if (!GETBIT_U8(checkEvent, SERVICE_TYPE_NRDC))
            {
                PRINT("\t\t %sThere is no report type for NRDC-SN %s\n", VCCB_C_RED, VCCB_C_RESET);
            }

            if (!GETBIT_U8(checkEvent, SERVICE_TYPE_SA))
            {
                PRINT("\t\t %sThere is no report type for Non-DC / NRDC-MN %s\n", VCCB_C_RED, VCCB_C_RESET);
            }
        }
    }
}

void FnITSCP_PrintMeasObjectEUTRA_Summary(uint16_t cellNum, const MeasObjectDebugFlag *pDbg)
{
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return;
    if (pDbg == NULL) return;

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    uint16_t measIdx = 0;

    // -------------------------------------------------------------------------------------------------------------
    // | idx |  earfcn | changeEvent         | measBw | VoNR  | EmerFB | OnDemand | bandList   | moPriority | Result | freq priority:idx ...
    // -------------------------------------------------------------------------------------------------------------
    // |   0 |    2000 | SA:B1/ TR:B1/ NA:-- | 3      | true  | false   | false   | n:1 [   4] |          0 | OK     |
    // -------------------------------------------------------------------------------------------------------------

    PRINT(
        "| idx |  earfcn | changeEvent         | measBw | VoNR  | EmerFB | OnDemand | bandList   | moPriority | Result | freq priority:idx ...\n");
    FnITSCP_PrintLine();

    for (measIdx = 0; measIdx < MAX_NR_OF_OBJECTEUTRA_ID_DB; measIdx++)
    {
        measurementObjectEUTRABaseDb_type *p = &pCell->measurementsData.measurementObjectsEUTRADb[measIdx].base;
        measurementObjectEUTRAExtensionDb_type *pExt = &pCell->measurementsData.measurementObjectsEUTRADb[measIdx].extension;
        uint16_t band[MAX_MEAS_FREQ_BAND_COMMON_NR_EUTRA] = {0};
        uint16_t bandCnt = 0, bandIdx = 0;

        if (p->usage != CI_use) continue;

        // Get Band List
        for (bandIdx = 0; bandIdx < MAX_MEAS_FREQ_BAND_COMMON_NR_EUTRA; bandIdx++)
        {
            if (p->freqBandIndicatorDbList.freqBand[bandIdx].usage == CI_use)
            {
                band[bandCnt++] = p->freqBandIndicatorDbList.freqBand[bandIdx].band;
            }
        }

        // idx
        PRINT("| %3u ", measIdx);

        // ssbFreq - Indicates the frequency of MO.
        PRINT("| %7u ", p->carrierFreq);

        // changeEvent - It indicates the event for SPCell change.
        PRINT("| SA:%s/ ", FnITSCP_GetInterRatHandoverEventString(p->interRatHandoverEvent));
        PRINT("TR:%s/ ", FnITSCP_GetInterRatHandoverEventString(p->trafficBasedHandoverEvent));
        PRINT("NA:-- ");

        uint8_t checkEvent = 0, found = 0; // 2^0 : Coverage, 2^1 : Traffic, 2^2 : Load Balancing
        for (uint8_t index = 0; index < VCCB_ARRAY_COUNT(pCell->measurementsData.reportConfigInterRatDb); index++)
        {
            reportConfigurationBaseDb_type *pReportConfig = &pCell->measurementsData.reportConfigInterRatDb[index].base;

            if (pReportConfig->usage != CI_use) continue;

            // Coverage based HO
            if (!GETBIT_U8(checkEvent, SERVICE_EUTRA_HO) &&
                    FnITSCP_CompareMoEventWithRc(measIdx, p->interRatHandoverEvent, SERVICE_EUTRA_HO, pReportConfig, SERVICE_TYPE_EUTRA) == true)
                checkEvent |= (1 << SERVICE_EUTRA_HO);

            if ((pReportConfig->reportType == measReport_B1Eutra && pReportConfig->reportPurpose == b1Purpose_eutraHandover) ||
                    (pReportConfig->reportType == measReport_B2Eutra && pReportConfig->reportPurpose == b2Purpose_eutraHandover))
                found |= (1 << SERVICE_EUTRA_HO);

            // Traffic based HO
            if (!GETBIT_U8(checkEvent, SERVICE_EUTRA_TR_HO) &&
                    FnITSCP_CompareMoEventWithRc(measIdx, p->trafficBasedHandoverEvent, SERVICE_EUTRA_TR_HO, pReportConfig, SERVICE_TYPE_EUTRA) == true)
                checkEvent |= (1 << SERVICE_EUTRA_TR_HO);

            if ((pReportConfig->reportType == measReport_B1Eutra && pReportConfig->reportPurpose == b1Purpose_trafficBasedHandover) ||
                    (pReportConfig->reportType == measReport_B2Eutra && pReportConfig->reportPurpose == b2Purpose_trafficBasedHandover))
                found |= (1 << SERVICE_EUTRA_TR_HO);

            // LB HO
            if (!GETBIT_U8(checkEvent, SERVICE_EUTRA_LB_HO) &&
                    FnITSCP_CompareMoEventWithRc(measIdx, p->loadBasedIratHandoverEvent, SERVICE_EUTRA_LB_HO, pReportConfig, SERVICE_TYPE_EUTRA) == true)
                checkEvent |= (1 << SERVICE_EUTRA_LB_HO);

            if ((pReportConfig->reportType == measReport_B1Eutra && pReportConfig->reportPurpose == b1Purpose_loadBalancingIratHandover) ||
                    (pReportConfig->reportType == measReport_B2Eutra && pReportConfig->reportPurpose == b2Purpose_loadBalancingIratHandover))
                found |= (1 << SERVICE_EUTRA_LB_HO);

            if (checkEvent == e_BitMask_3bit) break;
        }

        // allowedMeasBandwidth
        PRINT("| %-6d ", p->allowedMeasBandwidth);

        // voiceSupportFlag
        PRINT("| %-5s ", (p->voiceSupportFlag ? "true" : "false"));

        // emergencyFallbackSupportFlag
        PRINT("| %-7s ", (p->emergencyFallbackSupportFlag ? "true" : "false"));

        // supportOnDemandMobility
        PRINT("| %-7s ", (p->supportOnDemandMobility ? "true" : "false"));

        // bandList - Indicates the band information supported by the MO.
        PRINT("| n:%u [", bandCnt);

        if (bandCnt == 0)
        {
            PRINT("%4u", 0);
        }
        else
        {
            // display one band (use measInfo command to display more)
            {
                PRINT("%4u", band[0]);
            }
        }
        PRINT("] ");

        // moPriorityEutra
        PRINT("| %10u ", p->moPriorityEutra);

        // Result
        PRINT("| %-6s ", FnITSCP_GetValidResult_MeasObjectEUTRA(p, pDbg));

        // freq priority
        PRINT("|");
        int plmnIdx;
        for (plmnIdx = 0; plmnIdx < MAX_PLMN_INDEX; plmnIdx++)
        {
            if (CI_use != pExt->plmnBasedControl.plmn[plmnIdx].usage) continue;

            PRINT("%d[%2d] ", plmnIdx, pExt->plmnSpecific[plmnIdx].moPriorityEutra);
        }

        // line end
        PRINT("\n");

        if (checkEvent < e_BitMask_3bit)
        {
            if (!GETBIT_U8(checkEvent, SERVICE_EUTRA_HO))
            {
                PRINT("\t\t %sThere is no report type for EUTRA HO %s\n", VCCB_C_RED, VCCB_C_RESET);

                if (GETBIT_U8(found, SERVICE_EUTRA_HO))
                    PRINT("\t\t %s- Check MO selection %s\n", VCCB_C_YELLOW, VCCB_C_RESET);
            }

            if (!GETBIT_U8(checkEvent, SERVICE_EUTRA_TR_HO) && GETBIT_U8(found, SERVICE_EUTRA_TR_HO)) // Not frequently used
            {
                PRINT("\t\t %sThere is no report type for Traffic EUTRA HO %s\n", VCCB_C_RED, VCCB_C_RESET);

                if (GETBIT_U8(found, SERVICE_EUTRA_TR_HO))
                    PRINT("\t\t %s- Check MO selection %s\n", VCCB_C_YELLOW, VCCB_C_RESET);
            }

            if (!GETBIT_U8(checkEvent, SERVICE_EUTRA_LB_HO) && GETBIT_U8(found, SERVICE_EUTRA_TR_HO)) // Not frequently used
            {
                PRINT("\t\t %sThere is no report type for LB EUTRA HO %s\n", VCCB_C_RED, VCCB_C_RESET);

                if (GETBIT_U8(found, SERVICE_EUTRA_LB_HO))
                    PRINT("\t\t %s- Check MO selection %s\n", VCCB_C_YELLOW, VCCB_C_RESET);
            }
        }

    }
}

void FnITSCP_PrintReportConfigNR_Summary(uint16_t cellNum, const MeasObjectDebugFlag *pDbg)
{
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return;
    if (pDbg == NULL) return;

    VccbCellInfo_type *const pCell = &PCELLINFO[cellNum];
    uint16_t index = 0;

    // -------------------------------------------------------------------------------------------------------------
    // | idx | FOR | type | purpose                  | moSelect | Result
    // -------------------------------------------------------------------------------------------------------------
    // |   0 | ALL  | A2   | ( 1) NRPSCellRelease                         | ALL      | OK
    // -------------------------------------------------------------------------------------------------------------

    PRINT("| idx | FOR  | type | purpose                                      | moSelect | Result\n");
    FnITSCP_PrintLine();

    for (index = 0; index < MAX_NR_OF_REPORT_CONFIG_ID_DB; index++)
    {
        reportConfigurationBaseDb_type *pReportConfig = &pCell->measurementsData.reportConfigurationsDb[index].base;

        if (pReportConfig->usage != CI_use) continue;

        // |  0  | ALL  | A2   | (10)NRPSCellRelease      | 0x100000 |  0ff   | OK    | Need A3 ?

        // type
        PRINT("| %3u ", index);

        // for
        PRINT("| ALL  ");  // TODO : .. NRDC SA NSA ETC ...

        // type
        PRINT("| %-4s ", getReportConfigTypeStr(static_cast<enumMeasurementReportType>(pReportConfig->reportType)));

        // purpose
        PRINT("| (%2d) %-39s ", pReportConfig->reportPurpose,
              getReportConfigPurposeStr(static_cast<enumMeasurementReportType>(pReportConfig->reportType), pReportConfig->reportPurpose));

        // moSelect -- INTRA
        if (ALL_MEASOBJECT_SELECTION == pReportConfig->measObjectSelection)
            PRINT("| %-8s ", "ALL");
        else
            PRINT("| 0x%05X ", pReportConfig->measObjectSelection);

        // result
        PRINT("| %-6s ", FnITSCP_GetValidResult_ReportConfigNR(pReportConfig, pDbg, cellNum));

        // line end
        PRINT("\n");
    }
}

