int GetMeasInfo_Proc(uint16_t cellNum, const MeasObjectDebugFlag *pDbg)
{
    if (cellNum >= MAX_CELL_NUM_ITSCP_VCCB) return ERROR;
    if (pDbg == NULL) return ERROR;

    FnITSCP_PrintLine();
    PRINT("Measurement Configuration (CellNum: %u)\n", cellNum);
    FnITSCP_PrintLine();
    PRINT("\n");

    // Detail Mode
    if (pDbg->m.detailModePresent == OPT_PRESENT)
    {
        FnITSCP_PrintCellMeasInfo_Detail(cellNum, pDbg);
        return GOOD;
    }

    // Summary Mode
    FnITSCP_PrintCellMeasInfo_Summary(cellNum, pDbg);

    return GOOD;
}

int GetMeasInfo(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("itscp_vccb get cfg cell measInfo <cellNum> [option]\n");
        PRINT(" -t<targetCellNum> : Check the operation from the point of view of the target cell.\n");
        PRINT(" -p<0:nsa,1:sa> : Check the behavior from the SA/NSA perspective.\n");
        PRINT(" -d :This is the mode to output detail information.\n");
        PRINT(" -d<0: NRDC-MN, 1: NRDC-SN, 2: NEDC-MN> :This is to output debug for MRDC..\n");
    };
    uint16_t cellNum = 0;
    MeasObjectDebugFlag dbg;

    memset(&dbg.m, 0x00, sizeof(dbg.m));

    if (argc < 2)
    {
        SHOW_USAGE();
        return GOOD;
    }
    uint16_t maxCellNum = MAX_CELL_NUM_ITSCP_VCCB;
    cellNum = StrUtil::itscp_strtoul<uint16_t>(argv[1]);
    if (cellNum >= maxCellNum)
    {
        SHOW_USAGE();
        return GOOD;
    }

    if (argc >= 3)  // Option
    {
        itscpOptionParser itscpOption(argc, argv, "dt:p:m:");
        for(auto &option : itscpOption.option)
        {
            uint8_t callType;
            uint16_t targetCellNum;
            uint8_t mrdcMode;
            switch (option.key)
            {
                case 'p':
                    callType = StrUtil::itscp_strtoul<uint8_t>(option.val.c_str());
                    if (callType != E_CALLTYPE_NSA && callType != E_CALLTYPE_SA)
                    {
                        PRINT("-p is 0 or 1\n");
                        SHOW_USAGE();
                        return GOOD;
                    }
                    dbg.callType = callType;
                    dbg.m.callTypePresent = OPT_PRESENT;
                    PRINT("Apply Option : %c\n", option.key);
                    break;
                case 't':
                    targetCellNum = StrUtil::itscp_strtoul<uint16_t>(option.val.c_str());
                    if (targetCellNum >= maxCellNum)
                    {
                        PRINT("-t is max value over! (%u < %u)\n", targetCellNum, maxCellNum);
                        SHOW_USAGE();
                        return GOOD;
                    }
                    dbg.targetCellNum = targetCellNum;
                    dbg.m.targetCellNumPresent = OPT_PRESENT;
                    PRINT("Apply Option : %c\n", option.key);
                    break;
                case 'd':
                    dbg.m.detailModePresent = OPT_PRESENT;
                    PRINT("Apply Option : %c\n", option.key);
                    break;

                case 'm':
                    mrdcMode = StrUtil::itscp_strtoul<uint8_t>(option.val.c_str());
                    if (mrdcMode >= ITSCP_MEAS_OPT_M_NRDC_MAX)
                    {
                        PRINT("-m is max value over! (%u < %u), {0: NRDC-MN, 1: NRDC-SN, 2: NEDC-MN}\n", mrdcMode,
                              ITSCP_MEAS_OPT_M_NRDC_MAX);
                        SHOW_USAGE();
                        return GOOD;
                    }
                    dbg.mrdcMode = mrdcMode;
                    dbg.m.mrdcPresent = OPT_PRESENT;
                    PRINT("Apply Option : %c\n", option.key);
                    break;

                case '?':
                    SHOW_USAGE();
                    return GOOD;
                default:
                    break;
            }
        }
    }

    return GetMeasInfo_Proc(cellNum, &dbg);
}

