int GetCfgCallDropRatioHighAlarm(int32_t argc, char *argv[])
{
    VccbCallDropRatioHighAlarm_type& rDropAlarm = PCFG->acpfInfo.callDropRatioHighAlarm;

    bool isDetail = false;
    if ((argc == 2) && (!strcasecmp(argv[1], "detail")))
    {
        isDetail = true;
    }

    struct tm lastCheckTime;
    localtime_r((time_t *)&PCFG->acpfInfo.callDropRatioHighAlarm.lastCheckTime.tv_sec, &lastCheckTime);

    PRINT("+==============================================+\n");
    PRINT("| Call Drop Ratio High Alarm Info              |\n");
    PRINT("+----------------------------------------------+\n");
    SHOW_VALUE_OF(rDropAlarm, alarmEnabled);
    SHOW_VALUE_OF(rDropAlarm, monitoringPeriod);
    SHOW_VALUE_OF(rDropAlarm, abnormalReleaseRatioThreshold);
    SHOW_VALUE_OF(rDropAlarm, instantMonitoringPeriod);
    SHOW_VALUE_OF(rDropAlarm, releasedCallThreshold);
    SHOW_VALUE_OF(rDropAlarm, alarmSeverity);
    SHOW_VALUE_OF(rDropAlarm, excludedCrrCount);
    if (isDetail)
    {
        PRINT("+----------------------------------------------+\n");
        for (int crrListIdx = 0; crrListIdx < MIN(MAX_EXCLUDED_CRR_LIST, rDropAlarm.excludedCrrCount); crrListIdx++)
        {
            SHOW_VALUE_OF_LIST_HEX(rDropAlarm, excludedCRRList, crrListIdx);
        }
        PRINT("+----------------------------------------------+\n");
        PRINT(" lastCheckTime\t= %02d%02d%02d %02d:%02d:%02d\n", lastCheckTime.tm_year % 100, lastCheckTime.tm_mon + 1,
              lastCheckTime.tm_mday, lastCheckTime.tm_hour, lastCheckTime.tm_min, lastCheckTime.tm_sec);

        int threadId = 0;
        for (threadId = 0; threadId < MAX_CALL_THREAD_NUM_ITSCP_VCCB; threadId++)
        {
            SHOW_VALUE_OF_LIST(rDropAlarm, prevCallReleaseCount, threadId);
        }
        for (threadId = 0; threadId < MAX_CALL_THREAD_NUM_ITSCP_VCCB; threadId++)
        {
            SHOW_VALUE_OF_LIST(rDropAlarm, prevAbnormalCallReleaseCount, threadId);
        }
        PRINT("+----------------------------------------------+\n");
        SHOW_VALUE_OF(rDropAlarm, instantCallDropHighCount);
        for (threadId = 0; threadId < MAX_CALL_THREAD_NUM_ITSCP_VCCB; threadId++)
        {
            SHOW_VALUE_OF_LIST(rDropAlarm, currCallReleaseCount, threadId);
        }
        for (threadId = 0; threadId < MAX_CALL_THREAD_NUM_ITSCP_VCCB; threadId++)
        {
            SHOW_VALUE_OF_LIST(rDropAlarm, currAbnormalCallReleaseCount, threadId);
        }
    }
    PRINT("+==============================================+\n");

    return GOOD;
}

