int GetCfgNbrAudit(int32_t argc, char *argv[])  // NBR_AUDIT_22B
{
    (void)argc;
    (void)argv;

    VccbNbrReadAuditInfo_type *pNbrAudit = &PCFG->confd.nbrAudit;
    int gnbNum, cellNum;
    ConfStatus gnbStatus[MAX_GNB_CU_CP_FUNCTION_PER_SYS];

    PRINT("+===============================================+\n");
    PRINT("| NBR Audit Info                                +\n");
    PRINT("+-----------------------------------------------+\n");

    PRINT("Enabled: %s\n", (pNbrAudit->nbrAuditEnabled ? "Yes" : "No"));
    PRINT("Audit hour: every %d o'clock \n", pNbrAudit->nbrAuditHour);
    PRINT("Audit check hour(Dbg): %d \n", pNbrAudit->nbrAuditCheckHour);
    PRINT("nbrAuditFlag:%d nbrAuditForceFlag:%d (Dbg)\n", pNbrAudit->nbrAuditFlag, pNbrAudit->nbrAuditForceFlag);
    PRINT("+-----------------------------------------------+\n");
    PRINT("Total audit run count: %u \n", pNbrAudit->syncFullCnt);
    if (pNbrAudit->nbrAuditEnd >= pNbrAudit->nbrAuditStart)
    {
        PRINT("Last audit time: %lu (sec) \n", pNbrAudit->nbrAuditEnd - pNbrAudit->nbrAuditStart);
    }
    PRINT("Audit MIN time: %lu (sec) \n", pNbrAudit->nbrAuditMinTime);
    PRINT("Audit MAX time: %lu (sec) \n", pNbrAudit->nbrAuditMaxTime);
    PRINT("Audit run count on GNBs if exist \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (pNbrAudit->syncGnbCnt[gnbNum])
        {
            PRINT(" - GNB(#%d): %u \n", gnbNum, pNbrAudit->syncGnbCnt[gnbNum]);
        }
    }
    PRINT("Last NBR ENB/GNB cell count from the audit if exist \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (pNbrAudit->syncGnbCnt[gnbNum])
        {
            PRINT(" - Before Audit GNB(#%d) GNB: %u  ENB:%u \n", gnbNum, pNbrAudit->auditNbrGnbCellCnt[gnbNum][0],
                  pNbrAudit->auditNbrEnbCellCnt[gnbNum][0]);
            PRINT(" - After  Audit GNB(#%d) GNB: %u  ENB:%u \n", gnbNum, pNbrAudit->auditNbrGnbCellCnt[gnbNum][1],
                  pNbrAudit->auditNbrEnbCellCnt[gnbNum][1]);
        }
    }

    PRINT("Audit Count after the reset of GNB(s) DB if exist \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (pNbrAudit->syncGnbResetCnt[gnbNum])
        {
            PRINT(" - NBR GNB Reset GNB(#%d): %u  \n", gnbNum, pNbrAudit->syncGnbResetCnt[gnbNum]);
        }
        if (pNbrAudit->syncEnbResetCnt[gnbNum])
        {
            PRINT(" - NBR ENB Reset GNB(#%d): %u  \n", gnbNum, pNbrAudit->syncEnbResetCnt[gnbNum]);
        }
    }
    PRINT("Audit start time after detecting the need of reset: %u min\n", pNbrAudit->waitingTimeToSync);
    PRINT("+-----------------------------------------------+\n");
    PRINT("Initial NBR Read Done(Dbg): %s \n", (pNbrAudit->initialNbrReadFlag ? "Yes" : "No"));
    PRINT("Initial NBR GNB's Cell flag if true(Dbg) \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
        gnbStatus[gnbNum] = pGnb->status;
    }
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (gnbStatus[gnbNum] != EQUIP) continue;

        PRINT(" - GNB(#%d): %s \n", gnbNum, (pNbrAudit->initialReadNbrGnbCellFlag[gnbNum] ? "Yes" : "No"));
    }
    PRINT("Initial Cell NBR flag if true(Dbg) \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (gnbStatus[gnbNum] != EQUIP) continue;

        PRINT(" - GNB(#%d): %s \n", gnbNum, (pNbrAudit->initialReadCellNbrFlag[gnbNum] ? "Yes" : "No"));
    }
    PRINT("Initial NBR ENB's Cell flag if true(Dbg) \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (gnbStatus[gnbNum] != EQUIP) continue;

        PRINT(" - GNB(#%d): %s \n", gnbNum, (pNbrAudit->initialReadNbrEnbCellFlag[gnbNum] ? "Yes" : "No"));
    }
    PRINT("Initial Cell EUTRA NBR flag if true(Dbg) \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (gnbStatus[gnbNum] != EQUIP) continue;

        PRINT(" - GNB(#%d): %s \n", gnbNum, (pNbrAudit->initialReadCellEutraNbrFlag[gnbNum] ? "Yes" : "No"));
    }

    PRINT("+-----------------------------------------------+\n");
    PRINT("Mismatched Count from audits \n");
    PRINT(" - NBR GNB Cell Count if exist\n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (pNbrAudit->misNbrGnbCellCnt[gnbNum])
        {
            PRINT("    GNB(#%d): %u \n", gnbNum, pNbrAudit->misNbrGnbCellCnt[gnbNum]);
        }
    }
    PRINT(" - NBR ENB Cell Count if exist\n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (pNbrAudit->misNbrEnbCellCnt[gnbNum])
        {
            PRINT("    GNB(#%d): %u \n", gnbNum, pNbrAudit->misNbrEnbCellCnt[gnbNum]);
        }
    }

    PRINT(" - Cell NBR Count if exist \n");
    for (cellNum = 0; cellNum < MAX_CELL_NUM_ITSCP_VCCB; cellNum++)
    {
        if (pNbrAudit->misCellNbrCnt[cellNum])
        {
            PRINT("    Cell(#%d): %u \n", cellNum, pNbrAudit->misCellNbrCnt[cellNum]);
        }
    }

    PRINT(" - Cell EUTRA NBR Count if exist \n");
    for (cellNum = 0; cellNum < MAX_CELL_NUM_ITSCP_VCCB; cellNum++)
    {
        if (pNbrAudit->misCellEutraNbrCnt[cellNum])
        {
            PRINT("    Cell(#%d): %u \n", cellNum, pNbrAudit->misCellEutraNbrCnt[cellNum]);
        }
    }

    PRINT("Current NBR GNB/ENB Cell Count GNBs if exist \n");
    for (gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; gnbNum++)
    {
        if (gnbStatus[gnbNum] != EQUIP) continue;

        PRINT(" - GNB(#%d): NBR GNB - %u, NBR ENB - %u  \n", gnbNum, pNbrAudit->curNbrGnbCellCnt[gnbNum],
              pNbrAudit->curNbrEnbCellCnt[gnbNum]);
    }

    return GOOD;
}

