//SVR23B FGR-LC0710
int GetGnbSliceAwareLoadBalancing(int32_t argc, char *argv[])
{
    uint16_t gnbNum = 0;
    uint16_t sliceIndex = 0;

    if (2 != argc)
    {
        PRINT(
            "Usage : itscp_vccb get cfg gnb sliceAwareLoadBalancing gnbNum[] (wrong argument number - expected 2, "
            "received = %d)\n",
            argc);
        return GOOD;
    }

    CHECK_ARGC_SAVE_ARGV(2, gnbNum, MAX_GNB_PER_SYS_ITSCP_VCCB);

    VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
    if (pGnb->status != EQUIP)
    {
        PRINT("gNB(gNBNum: %d) is NOT Equip\n", pGnb->status);
        return GOOD;
    }

    PRINT("+=================================================================+\n");
    PRINT("| gNB sliceAwareLoadBalancing (GNB_NUM[%d] GNB_ID[%u])\n",
        gnbNum, pGnb->globalGnbId.gnbId.id);
    PRINT("+=================================================================+\n");
    PRINT("| > sliceAwareLbInfo \n");
    PRINT("|    sliceLbswitch (%d) \n", pGnb->sliceAwareLbInfo.sliceLbswitch);
    PRINT("|    waitTimerValue (%d) \n", pGnb->sliceAwareLbInfo.waitTimerValue);
    PRINT("|    sliceLbSwitchForRedcap (%d) \n", pGnb->sliceAwareLbInfo.sliceLbSwitchForRedcap);
    PRINT("|    mrWaitTimerValueForRedcap (%d) \n", pGnb->sliceAwareLbInfo.mrWaitTimerValueForRedcap);
    PRINT("+-----------------------------------------------------------------+\n");

    sliceLoadControlInfo_type *pSlice = NULL;

    for (sliceIndex = 0; sliceIndex < MAX_ACTIVE_SLICE_NUM; sliceIndex++)
    {
        pSlice = &pGnb->sliceLoadControlInfo[sliceIndex];

        if (pSlice->usage != CI_use) continue;

        PRINT("| > sliceLoadControlInfo[%d] \n", sliceIndex);
        PRINT("|    plmnIndex (%d) \n", pSlice->plmnIndex);
        PRINT("|    sst (%d), sd (%d), sdPresent (%d) \n",
            pSlice->sNssai.sst, pSlice->sNssai.sd, pSlice->sNssai.sdPresent);
        PRINT("|    sstsd (0x%X) \n", GET_SNSSAI_FROM_SST_AND_SD(pSlice->sNssai.sst, pSlice->sNssai.sd));
        PRINT("|    priority (%d) \n", pSlice->priority);
        PRINT("|    > sliceAwareLbConf \n");
        PRINT("|        sliceTransmissionType (%d) \n",
            pSlice->sliceAwareLbConf.sliceTransmissionType);
        PRINT("|        capacityThresholdDl (%d), capacityThresholdUl (%d) \n",
            pSlice->sliceAwareLbConf.capacityThresholdDl, pSlice->sliceAwareLbConf.capacityThresholdUl);
        PRINT("|        deltaCapacityThresholdDl (%d), deltaCapacityThresholdUl (%d) \n",
            pSlice->sliceAwareLbConf.deltaCapacityThresholdDl, pSlice->sliceAwareLbConf.deltaCapacityThresholdUl);
        PRINT("|        deltaCapacityThresholdRedcapDl (%d), deltaCapacityThresholdRedcapUl (%d) \n",
            pSlice->sliceAwareLbConf.deltaCapacityThresholdRedcapDl, pSlice->sliceAwareLbConf.deltaCapacityThresholdRedcapUl);
        PRINT("|        slaViolationSwitch (%d) \n", pSlice->sliceAwareLbConf.slaViolationSwitch);
        PRINT("|        slaViolationThDl (%d), slaViolationThUl (%d) \n",
            pSlice->sliceAwareLbConf.slaViolationThDl, pSlice->sliceAwareLbConf.slaViolationThUl);
        PRINT("+-----------------------------------------------------------------+\n");
    }

    return GOOD;
}

int getCallRestrictedGnbInfo(int32_t argc, char *argv[])
{
    callInfo_type *ptCi;
    uint32_t callId;
    char timeString[128] = {0};
    struct tm sTime;
    if (argc != 2)
    {
        PRINT(
            "Usage : itscp_vccb get call restrictedGnbInfo [callId] (wrong argument number expected=2, received=%d)\n",
            argc);
        return GOOD;
    }

    callId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);
    if (callId >= MAX_UE_NUM_ITSCP_VCCB)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }

    if (PENVCALL[callId].usage != CI_use)
    {
        PRINT("CallId(%d) not used !! \n", callId);
        return GOOD;
    }

    ptCi = &(PENVCALL[callId]);

    NrdcSnRestrictedGnbsByOvld_type *pRestrictedGnbs = &ptCi->restrictedGnbsforNrdcSn;

    PRINT("+---------------------------------------------------------------------+\n");
    PRINT("| Call ID : %d Print restricted Gnbs by overload for NRDC SN\n", callId);
    PRINT("+---------------------------------------------------------------------+\n");
    PRINT("| isDisabled(%d) currIdx(%d) noofElm(%d)\n", pRestrictedGnbs->isDisabled, pRestrictedGnbs->currIdx,
          pRestrictedGnbs->noofElm);
    PRINT("+---------------------------------------------------------------------+\n");
    PRINT("| Index | globalGnbId                | time \n");
    PRINT("|       | mcc   | mnc   | gnbId.id   | \n");
    PRINT("+---------------------------------------------------------------------+\n");
    for (uint16_t loop = 0; loop < MAX_RESTRICTED_GNB_BY_OVLD; loop++)
    {
        localtime_r((time_t *)&pRestrictedGnbs->gnbList[loop].timeStamp, &sTime);
        snprintf(timeString, 128, "%4d.%02d.%02d | %02d:%02d:%02d", 1900 + sTime.tm_year, sTime.tm_mon + 1,
                 sTime.tm_mday, sTime.tm_hour, sTime.tm_min, sTime.tm_sec);
        PRINT("| %5u | 0x%3X | 0x%3X | %10u | %s \n", loop, pRestrictedGnbs->gnbList[loop].globalGnbId.plmn.s2.mcc,
              pRestrictedGnbs->gnbList[loop].globalGnbId.plmn.s2.mnc,
              pRestrictedGnbs->gnbList[loop].globalGnbId.gnbId.id, timeString);
        PRINT("+---------------------------------------------------------------------+\n");
    }

    return GOOD;
}

int getCallDrxConfig(int32_t argc, char *argv[])
{
    callInfo_type *ptCi;
    uint32_t callId;
    if (argc < 2)
    {
        PRINT(
            "Usage : itscp_vccb get call drxConfig [option] [callId] (wrong argument number expected over 2, "
            "received=%d)\n",
            argc);
        return GOOD;
    }

    bool backupOpt = false;

    itscpOptionParser itscpOption(argc, argv, "b");
    for(auto &option : itscpOption.option)
    {
        switch (option.key)
        {
            case 'b':
            {
                backupOpt = true;
                break;
            }
            default:
                break;
        }
    }

    callId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);

    if (callId >= MAX_UE_NUM_ITSCP_VCCB)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }

    if (PENVCALL[callId].usage != CI_use)
    {
        PRINT("CallId(%d) not used !! \n", callId);
        return GOOD;
    }

    ptCi = &(PENVCALL[callId]);
    VccbDrxConfigInfo_type *drxConfig = &ptCi->drxCuInfo.drxConfigInfo;
    PRINT("======== Call[%u] Drx Config Info ========\n", callId);
    PRINT("isPresent : %s\n", drxConfig->isPresent ? "true" : "false");
    if (!drxConfig->isPresent)
    {
        PRINT("=====================================================\n");
    }
    else
    {
        PRINT("storeType : %s\n", drxConfig->storeType == VCCB_LONG_CYCLE_START_OFFSET ? "VCCB_LONG_CYCLE_START_OFFSET"
                                                                                       : "VCCB_DRX_CONFIG_INFO");

        if (drxConfig->storeType == VCCB_DRX_CONFIG_INFO)
        {
            PRINT("drxLongCycleStartOffsetType : %u, drxLongCycleStartOffset : %u, drxInactivityTimer : %u\n",
                  drxConfig->storeData.drxConfig.drxLongCycleStartOffsetType,
                  drxConfig->storeData.drxConfig.drxLongCycleStartOffset,
                  drxConfig->storeData.drxConfig.drxInactivityTimer);

            PRINT("drxHarqRttTimerDL : %u, drxHarqRttTimerUL : %u\n", drxConfig->storeData.drxConfig.drxHarqRttTimerDL,
                  drxConfig->storeData.drxConfig.drxHarqRttTimerUL);

            PRINT("drxRetransmissionTimerDL : %u, drxRetransmissionTimerUL : %u\n",
                  drxConfig->storeData.drxConfig.drxRetransmissionTimerDL,
                  drxConfig->storeData.drxConfig.drxRetransmissionTimerUL);

            PRINT("shortDrxFlag : %u, drxShortCycle : %u, drxShortCycleTimer : %u, drxSlotOffset : %u\n",
                  drxConfig->storeData.drxConfig.shortDrxFlag, drxConfig->storeData.drxConfig.drxShortCycle,
                  drxConfig->storeData.drxConfig.drxShortCycleTimer, drxConfig->storeData.drxConfig.drxSlotOffset);
        }
        else
        {
            PRINT("longCycleStartOffset : %u\n", drxConfig->storeData.longCycleStartOffset);
        }
        PRINT("=====================================================\n");
    }

    if (backupOpt)
    {
        VccbDrxConfigInfo_type *backupDrxConfig = &ptCi->drxCuInfo.backupDrxConfigInfo;
        PRINT("======== Call[%u] Backup Drx Config Info ========\n", callId);
        PRINT("isPresent : %s\n", backupDrxConfig->isPresent ? "true" : "false");
        if (!backupDrxConfig->isPresent)
        {
            PRINT("=====================================================\n");
        }
        {
            PRINT("storeType : %s\n", backupDrxConfig->storeType == VCCB_LONG_CYCLE_START_OFFSET
                                          ? "VCCB_LONG_CYCLE_START_OFFSET"
                                          : "VCCB_DRX_CONFIG_INFO");

            if (backupDrxConfig->storeType == VCCB_DRX_CONFIG_INFO)
            {
                PRINT("drxLongCycleStartOffsetType : %u, drxLongCycleStartOffset : %u, drxInactivityTimer : %u\n",
                      backupDrxConfig->storeData.drxConfig.drxLongCycleStartOffsetType,
                      backupDrxConfig->storeData.drxConfig.drxLongCycleStartOffset,
                      backupDrxConfig->storeData.drxConfig.drxInactivityTimer);

                PRINT("drxHarqRttTimerDL : %u, drxHarqRttTimerUL : %u\n",
                      backupDrxConfig->storeData.drxConfig.drxHarqRttTimerDL,
                      backupDrxConfig->storeData.drxConfig.drxHarqRttTimerUL);

                PRINT("drxRetransmissionTimerDL : %u, drxRetransmissionTimerUL : %u\n",
                      backupDrxConfig->storeData.drxConfig.drxRetransmissionTimerDL,
                      backupDrxConfig->storeData.drxConfig.drxRetransmissionTimerUL);

                PRINT("shortDrxFlag : %u, drxShortCycle : %u, drxShortCycleTimer : %u, drxSlotOffset : %u\n",
                      backupDrxConfig->storeData.drxConfig.shortDrxFlag,
                      backupDrxConfig->storeData.drxConfig.drxShortCycle,
                      backupDrxConfig->storeData.drxConfig.drxShortCycleTimer,
                      backupDrxConfig->storeData.drxConfig.drxSlotOffset);
            }
            else
            {
                PRINT("longCycleStartOffset : %u\n", backupDrxConfig->storeData.longCycleStartOffset);
            }
        }
        PRINT("=====================================================\n");
    }
    return GOOD;
}

int getCallLtmInfo(int32_t argc, char *argv[])
{
    callInfo_type *ptCi;
    uint32_t callId;
    if (argc < 2)
    {
        PRINT(
            "Usage : itscp_vccb get call ltmInfo [option] [callId] (wrong argument number expected over 2, "
            "received=%d)\n",
            argc);
        return GOOD;
    }

    callId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);

    if (callId >= MAX_UE_NUM_ITSCP_VCCB)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }

    if (PENVCALL[callId].usage != CI_use)
    {
        PRINT("CallId(%d) not used !! \n", callId);
        return GOOD;
    }

    ptCi = &(PENVCALL[callId]);

    ltmUeInfo_type &rLtmUeInfo = ptCi->ltmUeInfo;

    PRINT("======== Call[%u] Ltm Info ===============\n", callId);

    // call level info
    {
        PRINT("numOfCellList : %u\n", rLtmUeInfo.numOfCellList);
    }

    // ltmCellInfo_type
    if (rLtmUeInfo.numOfCellList > 0)
    {
        PRINT("currentCgi: plmn.longId(%X) ci(%lu)\n",
                ptCi->nRCGI.plmn.longId, ptCi->nRCGI.ci);

        for (auto &rCell : rLtmUeInfo.cellList)
        {
            if (rCell.handle.usage == 0) continue;

            PRINT(" ltmCellIdx(%u) ltmStatus(%u) ltmAction(%u)\n", rCell.handle.ltmCellIdx, rCell.handle.ltmStatus, rCell.handle.ltmAction);

            PRINT("  flag: receivedDuUeId(%u) rrc_activation_flag(%u)\n", rCell.handle.flag.receivedDuUeId, rCell.handle.flag.rrc_activation_flag);

            PRINT("  cellSelection: cellNum(%u) bandNr(%u)\n",
                    rCell.data.cellSelection.cellNum, rCell.data.cellSelection.bandNr);

            PRINT("  nrcgi: plmn.longId(%X) ci(%lu)\n",
                    rCell.data.nrcgi.plmn.longId, rCell.data.nrcgi.ci);

            PRINT("  pci(%x) crnti(%u)\n", rCell.data.pci, rCell.data.crnti);

            PRINT("  du: f1Idx(%d) duUEid(%u)\n", rCell.handle.du.f1Idx, rCell.handle.du.duUEid);

            for (auto rDrb : rCell.data.tnlAddr.drb)
            {
                if (rDrb.f1uDlInfo.numTLAbit == 0) continue;

                PRINT("  drb tnl: numTLAbit(%d) TEID(%u) TLAddr [0x", rDrb.f1uDlInfo.numTLAbit, rDrb.f1uDlInfo.TEID);
                int byteLength = MIN((rDrb.f1uDlInfo.numTLAbit + 7) / 8, MAX_TLA_BYTE);
                for (int loop1 = 0; loop1 < byteLength; loop1++)
                {
                    PRINT("%02X", rDrb.f1uDlInfo.TLAddr[loop1]);
                }
                PRINT("] \n");
            }
        }
    }
    PRINT("=====================================================\n");

    return GOOD;
}

