uint64_t FnVCCB_ConvertMaskedIMEISVBytesToNumber(const VccbMaskedIMEISV_type& imeisvContainer, std::size_t startIndex, std::size_t numOfBytes)
{
    AUTO_TRACE_FUNC;

    if (startIndex >= MASKED_IMEISV_BUF_SIZE) return std::numeric_limits<uint64_t>::max();
    if (startIndex + numOfBytes > MASKED_IMEISV_BUF_SIZE) return std::numeric_limits<uint64_t>::max();
    uint64_t converted = 0;
    for (std::size_t index = startIndex; index < startIndex + numOfBytes; index++)
    {
        uint8_t byte = imeisvContainer.value[index];
        converted *= 100;
        converted += ((byte & 0xF0) >> 4) * 10U;
        converted += (byte & 0x0F);
    }
    return converted;
}

/****************************************************
 * @brief      This function obtains the TAC, SVN from a VccbMaskedIMEISV_type
 * @param[in]  imeisvContainer : reference to structure containing a byte array representing masked IMEISV
 * @return     uint32_t, uint8_t pair representing the TAC, SVN extracted from the imeisvContainer
 ****************************************************/
std::pair<uint32_t, uint8_t> FnVCCB_GetTacAndSvnFromMaskedIMEISV(const VccbMaskedIMEISV_type& imeisvContainer)
{
    AUTO_TRACE_FUNC;

    constexpr std::size_t TAC_START = 0;
    constexpr std::size_t TAC_LENGTH = 4;
    constexpr std::size_t SVN_START = 7;
    constexpr std::size_t SVN_LENGTH = 1;

    uint32_t tac = static_cast<uint32_t>(
            FnVCCB_ConvertMaskedIMEISVBytesToNumber(imeisvContainer, TAC_START, TAC_LENGTH));
    uint8_t svn = static_cast<uint8_t>(
            FnVCCB_ConvertMaskedIMEISVBytesToNumber(imeisvContainer, SVN_START, SVN_LENGTH));
    return std::make_pair(tac, svn);
}


int GetCallMaskedImeisv(int32_t argc, char *argv[])
{
    if (argc != 2)
    {
        PRINT("Usage : itscp_vccb get call maskedImeisv [callId] (wrong argument number expected=2, received=%d)\n", argc);
        return GOOD;
    }

    uint32_t callId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);
    if (callId >= MAX_UE_NUM_ITSCP_VCCB)
    {
        PRINT("CallId(%d) is out of range !! \n", callId);
        return GOOD;
    }

    if (PENVCALL[callId].usage != CI_use)
    {
        PRINT("CallId(%d) is not used !! \n", callId);
        return GOOD;
    }

    callInfo_type *ptCi = &(PENVCALL[callId]);
    PRINT("Masked IMEISV %s\n",
            ptCi->ueInfo.imeisvBuf.maskedIMEISVPresent == OPT_PRESENT ? "present" : "absent");
    if (ptCi->ueInfo.imeisvBuf.maskedIMEISVPresent != OPT_PRESENT)
    {
        return GOOD;
    }
    const auto [tac, svn] = FnVCCB_GetTacAndSvnFromMaskedIMEISV(ptCi->ueInfo.imeisvBuf.maskedIMEISV);
    PRINT("TAC: %u, SVN: %u\n", tac, svn);

    return GOOD;
}

int GetCfgGnbOverloadedGnbList(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    struct timespec now = { 0, 0 };

    /* Get timestamp */
    if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) // fail to get time
    {
        PRINT("clock_gettime Error!! \n");
    }

    PRINT("+============================================================+\n");
    PRINT(" Overloaded GNB List : Time(%ld)\n", now.tv_sec);
    PRINT("--------------------------------------------------------------\n");

    uint16_t gnbNum = 0;
    MACRO_GET_ALL_VALID_GNB_FORLOOP_START(gnbNum);  // pGnb inside

        PRINT("========= GNB_NUM[%d] GNB_ID[%10u] ======================\n",
                gnbNum, pGnb->globalGnbId.gnbId.id);
        PRINT(" Overloaded Tgt GNB Control : %s \n",
                (pGnb->cfg.restrictHoToOverloadedGnb.featureEnabled ? "Enabled" : "Disabled"));
        PRINT("--------------------------------------------------------------\n");
        PRINT(" Index |    longId |        Id |   Time(val) |     Time(str) |\n");
        PRINT("--------------------------------------------------------------\n");

        overloadedHoTgtGnbList_type *pList = &pGnb->overloadedTgtGnb;

        if (pList->start >= MAX_OVERLOADED_TGT_GNB ||
                pList->end >= MAX_OVERLOADED_TGT_GNB) continue;

        char timeString[128] = { 0, };
        struct tm sTime;

        uint16_t loop = pList->start;
        while (loop != pList->end)
        {
            localtime_r((time_t *)&pList->tgtGnbInfo[loop].endTime, &sTime);
            snprintf(timeString, 128, " %02d:%02d:%02d.%03u",  sTime.tm_hour, sTime.tm_min, sTime.tm_sec,
                    (unsigned int)pList->tgtGnbInfo[loop].endTime / 1000);

            PRINT(" %5u | %9X | %9u | %11lu | %11s |\n", loop,
                    pList->tgtGnbInfo[loop].tgtGnbId.plmn.longId, pList->tgtGnbInfo[loop].tgtGnbId.gnbId.id,
                    pList->tgtGnbInfo[loop].endTime, timeString);

            loop++;
            if (loop >= MAX_OVERLOADED_TGT_GNB)
            {
                loop %= MAX_OVERLOADED_TGT_GNB;
            }
        }

        PRINT("--------------------------------------------------------------\n");

    MACRO_GET_ALL_VALID_GNB_FORLOOP_END();

    PRINT("+============================================================+\n\n");

    return GOOD;
}

