        PRINT("\n");
        PRINT("--------------------------------------------------\n");
        PRINT(" == NR Small Cell PCI List on GNB[%u] == \n", gnbNum);
        PRINT("--------------------------------------------------\n");
        PRINT(" PCI Idx | Usage | Range Idx | Start | End | CIO(rsrp, rsrq, sinr) |\n");
        PRINT("--------------------------------------------------\n");
        VccbNrSmallCellPciList_type *pGnbNrPciList = NULL;

        for (uint8_t idx = 0; idx < MAX_NR_SMALLCELL_PCI_ENTRIES; idx++)
        {
            pGnbNrPciList = &pGnb->nrSmallCellPciList[idx];

            if (CI_use != pGnbNrPciList->usage) continue;

            for (uint8_t index = 0; index < MAX_NR_SMALLCELL_PCI_RANGE_ENTRIES; index++)
            {
                VccbNrSmallCellPciRange_type *pRangeList = &pGnbNrPciList->pciRange[index];

                if (CI_use != pRangeList->usage) continue;

                PRINT(" %7u | %5u | %9u | %5u | %3u | rsrp(%3u),rsrq(%3u),sinr(%3u) |\n", idx, pGnbNrPciList->usage, index,
                        pRangeList->pciStart, pRangeList->pciEnd, pRangeList->cellIndividualOffset.rsrpOffsetSSB,
                        pRangeList->cellIndividualOffset.rsrqOffsetSSB, pRangeList->cellIndividualOffset.sinrOffsetSSB);
            }
        }

        PRINT("--------------------------------------------------\n");
