int GetFeatureNrdcRestrictGnb(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("USAGE : itscp_vccb get feature nrdc restrictedGnb [callId]\n");
    };
    if (argc < 2)
    {
        SHOW_USAGE();
        return GOOD;
    }

    uint32_t callId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);
    if (callId >= MAX_UE_NUM_ITSCP_VCCB)
    {
        PRINT("CallId(%d) over ranged !! \n", callId);
        return GOOD;
    }
    if (PENVCALL[callId].usage != CI_use)
    {
        PRINT("CallId(%d) not used !! \n", callId);
        return GOOD;
    }
    callInfo_type *ptCi = &(PENVCALL[callId]);

    PRINT("==================================================\n");
    PRINT("= NRDC Gnb Restrict information                  =\n");
    PRINT("==================================================\n");
    PRINT("= BlockList Gnb Information                      =\n");
    PRINT("--------------------------------------------------\n");
    NrdcScgBlockListInfo_type *pBlocklistInfo = &ptCi->blockListInfo;
    PRINT("= callId [%4d]\n", ptCi->callId);
    PRINT("= Blocklist usage [%s]\n", (pBlocklistInfo->usage) ? " ENABLED" : "DISABLED");
    PRINT("= Current Index: %3d\n", pBlocklistInfo->currentIndex);
    PRINT("= Current Blocklist Size: %d\n", pBlocklistInfo->count);
    PRINT("--------------------------------------------------\n");

    if (pBlocklistInfo->currentIndex == 0xFF)
    {
        PRINT("= SN Blocklist for CALL #%d is EMPTY!\n", ptCi->callId);
    }
    else
    {
        int idx = 0;
        for (idx = 0; idx < pBlocklistInfo->count; idx++)
        {
            if (pBlocklistInfo->blocklist[idx].plmn.longId != 0)
            {
            PRINT("| blocklist[%d] gnbId(%d), plmn(0x%X) (mcc:%03X, mnc:%03X)\n", idx,
                    pBlocklistInfo->blocklist[idx].gnbId.id, pBlocklistInfo->blocklist[idx].plmn.longId,
                    pBlocklistInfo->blocklist[idx].plmn.s2.mcc, pBlocklistInfo->blocklist[idx].plmn.s2.mnc);
            }
        }
    }

    PRINT("==================================================\n");
    PRINT("= Overload Gnb Information                       =\n");
    PRINT("--------------------------------------------------\n");
    if (PDBG->flag.disable_RestrictingGnbTobeSnByOvld == VCCB_FLAG_ON)
    {
        PRINT("= Overload Restrict usage is off.\n");
        PRINT("= If you want to use gnb restriction by overload operation, Use below command\n");
        PRINT("= itscp_vccb set dbg flag disable_RestrictingGnbTobeSnByOvld off\n");
    }
    else
    {
        PRINT("= callId [%4d]\n", ptCi->callId);
        NrdcSnRestrictedGnbsByOvld_type *restrictedGnbList = &ptCi->restrictedGnbsforNrdcSn;
        PRINT("= Current Index: %d\n", restrictedGnbList->currIdx);
        PRINT("= Current OverloadList Size: %d\n", restrictedGnbList->noofElm);
        PRINT("= Restricted Gnb Life Time: %u\n", PDBG->value.restrictedGnbLifeTime);
        PRINT("= Current Expired Timestamp: %lu\n", time(NULL) - PDBG->value.restrictedGnbLifeTime);
        PRINT("--------------------------------------------------\n");

        if (restrictedGnbList->noofElm == 0)
        {
            PRINT("= SN Overloaded Gnb List for callId[%d] is EMPTY!\n", ptCi->callId);
        }
        else
        {
            for (int idx = 0; idx < restrictedGnbList->noofElm; idx++)
            {
            RestrictedGnb_type *restrictedGnb = &restrictedGnbList->gnbList[idx];
            PRINT("= OverloadList[%d] gnbId(%u), plmn(0x%X), (mcc:%03X, mnc:%03X), timeStamp(%ld)", idx,
                  restrictedGnb->globalGnbId.gnbId.id, restrictedGnb->globalGnbId.plmn.longId,
                  restrictedGnb->globalGnbId.plmn.s2.mcc, restrictedGnb->globalGnbId.plmn.s2.mnc,
                  restrictedGnb->timeStamp);
            if (restrictedGnb->timeStamp < (time(NULL) - PDBG->value.restrictedGnbLifeTime))
            {
                PRINT(VCCB_C_LRED " <Expired>\n" VCCB_C_RESET);
            }
            else
            {
                PRINT("\n");
            }
            }
        }
    }
    PRINT("==================================================\n");
    return GOOD;
}

int GetFeatureNrdcBasic(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("USAGE : itscp_vccb get feature nrdc basic [gnbId] [cellId]\n");
    };
    PRINT(VCCB_C_LBLUE "[ Get Nrdc Control Info ]\n " VCCB_C_RESET);
    GetCfgGnbNrdcControl(argc - 2, argv);
    PRINT(VCCB_C_LBLUE "\n[ Get GNB NbrXn Info ]\n " VCCB_C_RESET);
    GetGnbNbrXnInfo(argc - 2, argv);
    PRINT(VCCB_C_LBLUE "[ Get Qos Drb Mapping Info ]\n " VCCB_C_RESET);
    GetQosDrbMappingInfo(argc - 2, argv);
    PRINT(VCCB_C_LBLUE "\n[ Get GNB Du Info ]\n " VCCB_C_RESET);
    GetGnbGnbDuInfo(argc - 2, argv);

    if (argc >= 3)
    {
        char gnbNumStr[6];
        uint16_t gnbNum;
        uint32_t gnbId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 2]);
        GetGnbNumFromId(&gnbNum, gnbId);
        if (gnbNum == UNKNOWN_GNB_NUM)
        {
            PRINT("Wrong Input(gnbId:%u)!!\n", gnbId);
            SHOW_USAGE();
            return GOOD;
        }
        snprintf(gnbNumStr, sizeof(gnbNumStr), "%d", gnbNum);

        char cellNumStr[6];
        uint16_t cellNum;
        uint32_t cellId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);
        if (ERROR == GetCellNumFromCellId(gnbNum, cellId, &cellNum))
        {
            PRINT("Wrong Input(cellId:%u)!!\n", cellId);
            SHOW_USAGE();
            return GOOD;
        }
        snprintf(cellNumStr, sizeof(cellNumStr), "%d", cellNum);

        char *agmt[3];
        agmt[0] = argv[0];
        agmt[1] = gnbNumStr;
        PRINT(VCCB_C_LBLUE "\n[ Get GNB[%u] NbrGnbCell ]\n " VCCB_C_RESET, gnbNum);
        GetGnbNbrGNBCell(2, agmt);

        agmt[1] = cellNumStr;
        PRINT(VCCB_C_LBLUE "\n[ Get CELL[%u] CellNbrInfo ]\n" VCCB_C_RESET, cellNum);
        GetCellNbrInfo(2, agmt);

        PRINT(VCCB_C_LBLUE "\n[ Get CELL[%u] NrdcCellInfo ]\n " VCCB_C_RESET, cellNum);
        GetNrdcCellInfo(2, agmt);

        PRINT(VCCB_C_LBLUE "\n[ Get CELL[%u] ColocCellInfo ] " VCCB_C_RESET, cellNum);
        GetColocCellinfo(2, agmt);
    }
    return GOOD;
}

int GetCellNum(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("USAGE : itscp_vccb get info cell cellNum [gnbId] [cellId]\n");
    };
    if(argc < 3)
    {
        SHOW_USAGE();
        return GOOD;
    }
    uint16_t gnbNum;
    uint32_t gnbId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 2]);
    GetGnbNumFromId(&gnbNum, gnbId);
    if (gnbNum == UNKNOWN_GNB_NUM)
    {
        PRINT("Wrong Input(invalid gnbId(%u))!!\n", gnbId);
        SHOW_USAGE();
        return GOOD;
    }

    uint16_t cellNum;
    uint32_t cellId = StrUtil::itscp_strtoul<uint32_t>(argv[argc - 1]);
    if (ERROR == GetCellNumFromCellId(gnbNum, cellId, &cellNum))
    {
        PRINT("Wrong Input(invalid cellId:%u)!!\n", cellId);
        SHOW_USAGE();
        return GOOD;
    }

    PRINT("+ GNB ID(%u) & CELL ID(%u) : CELL NUM[%u] +\n", gnbId, cellId, cellNum);
    return GOOD;
}

