int GetCfgPdcpDuplicationConfig(int32_t argc, char *argv[])
{
    const auto SHOW_USAGE = []()
    {
        PRINT("USAGE1 : itscp_vccb get cfg gnb pdcpDuplicationConfig <gnbId>\n");
        PRINT("USAGE2 : itscp_vccb get cfg gnb pdcpDuplicationConfig <gnbId> <MCC> <MNC>\n");
    };

    if ((2 > argc) || (4 < argc))
    {
        PRINT("Wrong argument number - expected 2 or 4, received=%d)\n", argc);
        SHOW_USAGE();
        return GOOD;
    }

    uint16_t gnbNum;
    uint32_t gnbId = StrUtil::itscp_strtoul<uint32_t>(argv[1]);
    GetGnbNumFromId(&gnbNum, gnbId);
    if (gnbNum == UNKNOWN_GNB_NUM)
    {
        PRINT("Wrong Input(invalid gnbId:%u)!!\n", gnbId);
        SHOW_USAGE();
        return GOOD;
    }

    VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
    if (pGnb->status != EQUIP)
    {
        PRINT("gNB(gNBNum: %d) is NOT Equip\n", pGnb->status);
        return GOOD;
    }

    uint32_t mcc;
    uint32_t mnc;
    if (4 == argc)
    {
        mcc = StrUtil::itscp_strtoul<uint32_t>(argv[2]);
        mnc = StrUtil::itscp_strtoul<uint32_t>(argv[3]);
    }
    const pdcpDuplication_type *const pPdcpDuplication = &pGnb->cfg.pdcpDuplication;

    PRINT("+==============================================================+\n");
    PRINT("|            PDCP Duplication Configuration per GNB            |\n");
    PRINT("+--------------------------------------------------------------+\n");
    PRINT("+============= GNB_NUM[%d] GNB_ID[%10u] ==================+\n",
            gnbNum, pGnb->globalGnbId.gnbId.id);
    PRINT("| pdcpDuplicationOnOff = %d\n", pPdcpDuplication->pdcpDuplicationOnOff);
    PRINT("+==========================================\n");
    for (uint16_t configIdx = 0; configIdx < MAX_PDCP_DUPLICATION_CONFIG; ++configIdx)
    {
        if (CI_use == pPdcpDuplication->pdcpDuplicationConfig[configIdx].usage)
        {
            const pdcpDuplicationConfig_type *const pPdcpDuplicationConfig = &pPdcpDuplication->pdcpDuplicationConfig[configIdx];
            if ((2 == argc) ||
                ((4 == argc) &&
                 (mcc == pPdcpDuplicationConfig->plmn.s2.mcc) &&
                 (mnc == pPdcpDuplicationConfig->plmn.s2.mnc)))
            {
                PRINT("| PDCP Duplication Index = %d\n", configIdx);
                PRINT("| mcc = %#X\n", pPdcpDuplicationConfig->plmn.s2.mcc);
                PRINT("| mnc = %#X\n", pPdcpDuplicationConfig->plmn.s2.mnc);
                PRINT("| sst = %d\n", pPdcpDuplicationConfig->sst);
                PRINT("| sd = %d\n", pPdcpDuplicationConfig->sd);
                PRINT("| qos5qi = %d\n", pPdcpDuplicationConfig->qos5qi);
                PRINT("| dlPdcpDuplicationOnOff = %d\n", pPdcpDuplicationConfig->dlPdcpDuplicationOnOff);
                PRINT("+==========================================\n");
            }
        }
    }
    PRINT("+==============================================================+\n");

    return GOOD;
}

int GetSliceStatCounterListInfo(int argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+-----------------------------------------------------+\n");
    PRINT("| gnbNum |  idx  |  plmnIdx  |    sNssai(sst/sd)       \n");
    PRINT("+-----------------------------------------------------+\n");
    for (uint8_t gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; ++gnbNum)
    {
        VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
        if (pGnb->status != EQUIP) continue;

        for (uint8_t idx = 0; idx < MAX_SLICE_STAT_YANG; idx++)
        {
            if (pGnb->sliceStatCounterList[idx].usage != CI_use) continue;

            PRINT("|   %3d  |   %2d  |    %3u    |     0x%x/0x%x\n", gnbNum, idx,
                pGnb->sliceStatCounterList[idx].plmnIndex,
                pGnb->sliceStatCounterList[idx].sNssai.sst,
                pGnb->sliceStatCounterList[idx].sNssai.sd);
        }
    }
    PRINT("+-----------------------------------------------------+\n");

    return GOOD;
}

std::string CovertDigitToStrforPrint(uint8_t *digit, uint32_t length, uint32_t filllength)
{
    std::string result = "<unknown>";;
    std::ostringstream oss;

    if (digit == nullptr || length == 0)
    {
        return result;
    }

    if( filllength != 0 )
    {
        for (uint32_t i = 0; i < (filllength - length) ; i++)
        {
            oss << std::hex << std::uppercase << std::setw(2) << std::setfill('0') << 0;;
        }
    }

    for (uint32_t i = 0; i < length ; i++)
    {
        oss << std::hex << std::uppercase << std::setw(2) << std::setfill('0')
            << static_cast<int>(digit[i]);
    }

    result = oss.str();

    return result;
}

int GetCfgRacsConfiguration(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+===================================================+\n");
    PRINT("| RACS Configuration Information                    |\n");
    PRINT("| (/managed-element/racs-function-on-off)           |\n");
    PRINT("+---------------------------------------------------+\n");
    PRINT("  - racsFunctionOnOff :                    %d\n", PCFG->acpfInfo.racsFunctionOnOff);
    PRINT("+---------------------------------------------------+\n");
#if defined(__NVGNB__)
    PRINT("  - NVGNB not support RACS (FOO:%d) \n", PFOO->VF_RACS);
#else
    PRINT("  - racsCapaIdListNum :                    %d\n", PRACSINFO->racsCapaIdListNum);
    PRINT("+---------------------------------------------------+\n");

    int32_t idx = 0;
    for (idx = 0; idx < MIN(PRACSINFO->racsCapaIdListNum, MAX_UE_CAPA_ID_CNT); idx++)
    {
        if (PRACSINFO->racsCapaIdList[idx].usage == CI_no_use && PRACSINFO->racsCapaBufferList[idx].usage == CI_no_use)
            continue;

        PRINT(" -[%3d] Usage - ID:%u, Buffer:%u \n", idx, PRACSINFO->racsCapaIdList[idx].usage, PRACSINFO->racsCapaBufferList[idx].usage);
        PRINT(" -      amfIndex:%d, IdLength:%d, ID:%s, plmn_longId:%x\n", PRACSINFO->racsCapaIdList[idx].amfIndex,
              PRACSINFO->racsCapaIdList[idx].ueCapaIdLength,
              CovertDigitToStrforPrint(PRACSINFO->racsCapaIdList[idx].ueCapaID, PRACSINFO->racsCapaIdList[idx].ueCapaIdLength).c_str(),
              PRACSINFO->racsCapaIdList[idx].plmn_longId);
        PRINT(" -      bufferLength:%d \n", PRACSINFO->racsCapaBufferList[idx].length);
        PRINT("+---------------------------------------------------+\n");
    }
#endif
    return GOOD;
}

int GetCfgImeisvFeatureControlConfiguration(int32_t argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+===================================================+\n");
    PRINT("| IMEISV Feature Control Configuration Information  |\n");
    PRINT("+---------------------------------------------------+\n");
    PRINT("  - function on/off       :  %d\n", PCFG->imeisvFeatControlInfo.featureControlEnabled);
    PRINT("+---------------------------------------------------+\n");
    PRINT("  - num of active entries :  %d\n", PCFG->imeisvFeatControlInfo.noOfEntries);
    PRINT("+---------------------------------------------------+\n");

    const auto& entries = PCFG->imeisvFeatControlInfo.entries;
    int32_t idx = 0;
    for (idx = 0;
         idx < MIN(PCFG->imeisvFeatControlInfo.noOfEntries, MAX_IMEISV_FEATURE_CONTROL_INFORMATION_ENTRIES);
         idx++)
    {
        const auto& currentEntry = entries[idx];
        VccbMaskedIMEISV_type maskedImeisvContainer;
        memcpy(maskedImeisvContainer.value, &currentEntry.maskedImeisv, sizeof(uint64_t));

        const auto [tac, svn] = FnVCCB_GetTacAndSvnFromMaskedIMEISV(maskedImeisvContainer);
        PRINT("+---------------------------------------------------+\n");
        PRINT(" idx: %d\n", idx);
        PRINT(" tac: %u, svn: %u  (maskedImeisv: 0x%016llx)\n", tac, svn, static_cast<unsigned long long>(currentEntry.maskedImeisv));
        // add feature control on/off entries
        PRINT(" vonr-support-per-imeisv: %s\n", (currentEntry.featureSupport.vonrSupportPerImeisv) ? "enable" : "disable");
        PRINT("+---------------------------------------------------+\n");
    }
    return GOOD;
}

