int GetCapaSizeReduceFunction(int argc, char *argv[])
{
    (void)argc;
    (void)argv;

    PRINT("+-----------------------------------------------------------------------+\n");
    PRINT("|        |       | threshold | threshold | threshold |   plmnIndex ON   |\n");
    PRINT("| gnbNum | Usage |     NG    |     XN    |    IRAT   | (0/1/2/3/4/5/6/7)|\n");
    PRINT("+-----------------------------------------------------------------------+\n");
    for (uint8_t gnbNum = 0; gnbNum < MAX_GNB_PER_SYS_ITSCP_VCCB; ++gnbNum)
    {
        VccbGnbInfo_type *const pGnb = &PGNBINFO[gnbNum];
        if (pGnb->status != EQUIP) continue;

        PRINT("| %6u ", gnbNum);
        PRINT("| %5s ", (pGnb->ueCapaSizeReduceInfo.usage == VCCB_FLAG_ON) ? "Use" : "NoUse");
        PRINT("| %9u ", pGnb->ueCapaSizeReduceInfo.triggerThresholdNg);
        PRINT("| %9u ", pGnb->ueCapaSizeReduceInfo.triggerThresholdXn);
        PRINT("| %9u ", pGnb->ueCapaSizeReduceInfo.triggerThresholdIrat);
        PRINT("|  %u/%u/%u/%u/%u/%u/%u/%u |\n", pGnb->ueCapaSizeReduceInfo.plmnReduceOn[0],
              pGnb->ueCapaSizeReduceInfo.plmnReduceOn[1], pGnb->ueCapaSizeReduceInfo.plmnReduceOn[2],
              pGnb->ueCapaSizeReduceInfo.plmnReduceOn[3], pGnb->ueCapaSizeReduceInfo.plmnReduceOn[4],
              pGnb->ueCapaSizeReduceInfo.plmnReduceOn[5], pGnb->ueCapaSizeReduceInfo.plmnReduceOn[6],
              pGnb->ueCapaSizeReduceInfo.plmnReduceOn[7]);
    }
    PRINT("+-----------------------------------------------------------------------+\n");

    return GOOD;
}

int GetCellLbmSpecificMeas(int32_t argc, char *argv[])
{
    if (argc < 2)
    {
        PRINT("get cfg cell lbmSpecificMeas [cellNum]\n");
        return GOOD;
    }

    uint16_t cellNum = MAX_CELL_PER_VNF;
    CHECK_ARGC_SAVE_ARGV(2, cellNum, MAX_CELL_NUM_ITSCP_VCCB);

    const VccbCellInfo_type& cell = PCELLINFO[cellNum];

    if (N_EQUIP == cell.status)
    {
        PRINT("Not Equip Cell, cellNum: %d!\n", cellNum);
        return GOOD;
    }

    const std::string parameterSetNames[4] = {
        "Window 0 Update",
        "Window 0 Fallback",
        "Window 1 Update",
        "Window 1 Fallback"
    };

    PRINT("==========================================\n");
    PRINT("| LBM Specific Meas for cellNum(%u):\n", cellNum);
    for (int parameterSetIdx = 0; parameterSetIdx < MAX_NR_LBM_CONFIG_ENTRIES - 1; parameterSetIdx++)
    {
        PRINT("==========================================\n");
        PRINT("| %s\n", parameterSetNames[parameterSetIdx].c_str());
        PRINT("==========================================\n");
        for (int moIdx = 0; moIdx < MAX_NR_OF_OBJECT_ID_DB - 1; moIdx++)
        {
            const lbmSpecificMeasObject_type& mo = cell.lbmSpecificMeasurementData.moListPerLbmParameterSet[parameterSetIdx].mo[moIdx]; 
            PRINT("| idx = %d\n", moIdx);
            PRINT("==========================================\n");
            PRINT("| usage                    = %d\n", mo.usage);
            PRINT("| target meas object index = %u\n", mo.targetMeasObjectIndex);
            PRINT("| a2 delta rsrp            = %u\n", mo.a2ScellReleaseDelta.thDeltaRsrp);
            PRINT("| a2 delta rsrq            = %u\n", mo.a2ScellReleaseDelta.thDeltaRsrq);
            PRINT("| a4 delta rsrp            = %u\n", mo.a4ScellAdditionDelta.thDeltaRsrp);
            PRINT("| a4 delta rsrq            = %u\n", mo.a4ScellAdditionDelta.thDeltaRsrq);
            PRINT("==========================================\n");
        }
    }

    return GOOD;
}

int GetGnbFr2UplinkGapControl(int32_t argc, char *argv[])
{
    uint16_t gnbNumMin = 0;
    int32_t gnbNumMax = MAX_GNB_PER_SYS_ITSCP_VCCB;

    if (argc > 2)
    {
        PRINT("Usage : itscp_vccb get cfg gnb ulFr2gap or itscp_vccb get cfg gnb ulFr2gap [GNB_NUM]\n");
        return GOOD;
    }

    if (argc == 2)
    {
        uint16_t gnbNum = StrUtil::itscp_strtoul<uint16_t>(argv[1]);
        if (gnbNum >= gnbNumMax)
        {
            PRINT("GNB_NUM(%u) out of range(0,%u), printing all\n", gnbNum, gnbNumMax);
        }
        else
        {
            gnbNumMin = gnbNum;
            gnbNumMax = gnbNum + 1;
        }
    }

    PRINT("+===============================================+\n");
    PRINT("| FR2 Uplink Gap Control                        +\n");
    PRINT("+-----------------------------------------------+\n");

    for (uint16_t gnbNum = gnbNumMin; gnbNum < gnbNumMax; gnbNum++)
    {
        const VccbGnbInfo_type &rGnb = PGNBINFO[gnbNum];
        if (rGnb.status != EQUIP)
        {
            continue;
        }
        const Fr2UplinkGapControl_type &rFr2UlGapCtrl = rGnb.cfg.fr2UplinkGapControl;

        PRINT("========= GNB_NUM[%d] GNB_ID[%10u] =========\n", gnbNum, rGnb.globalGnbId.gnbId.id);
        PRINT("fr2-uplink-gap-control/fr2-uplink-gap-control-switch: %d\n", rFr2UlGapCtrl.controlSwitch);
        PRINT("+===============================================+\n");
    }

    return GOOD;
}

